import React, { useCallback, useEffect, useMemo, useState, useRef } from 'react'
import ReactDOM from 'react-dom'
import { AddsOverlayProvider, useAddsOverlay } from '@/provider/adds-overlay-provider'
import usePopupObserver from '@/hooks/usePopupObserver'
import DisableStatus from './disable-status'
import ToggleAllAdds from './toggle-all-adds'
type propType = {
    username: string
    container: HTMLDivElement
}
const AddsOverlayWrapper = ({ username, container }: propType) => {
    const { userMainInfo, toggleDisableAdd, ownerDisabledAdds, loadingDisabledAdds } =
        useAddsOverlay()

    const userDisabled = useMemo(
        () => !!ownerDisabledAdds.find(i => i === username),
        [ownerDisabledAdds, username]
    )

    const memoizedToggleDisabledAdd = useCallback(() => {
        toggleDisableAdd(username)
    }, [toggleDisableAdd, username])

    useEffect(() => {
        ReactDOM.render(
            <DisableStatus
                toggleDisabledAdd={memoizedToggleDisabledAdd}
                userDisabled={userDisabled}
                userMainInfo={userMainInfo}
                username={username}
                loadingDisabledAdds={loadingDisabledAdds}
            />,
            container
        )

        return () => {
            ReactDOM.unmountComponentAtNode(container)
        }
    }, [
        memoizedToggleDisabledAdd,
        userDisabled,
        ownerDisabledAdds,
        userMainInfo,
        loadingDisabledAdds,
        container,
        username
    ])

    return null
}

const AllAddsToggle = ({ container }) => {
    const {
        userMainInfo,
        setRefetchDisableAdds,
        loadingDisabledAdds,
        setLoadingDisabledAdds,
        disableAllAdds,
        setDisableAllAdds
    } = useAddsOverlay()
    useEffect(() => {
        ReactDOM.render(
            <ToggleAllAdds
                userMainInfo={userMainInfo}
                loadingDisabledAdds={loadingDisabledAdds}
                setRefetchDisableAdds={setRefetchDisableAdds}
                setLoadingDisabledAdds={setLoadingDisabledAdds}
                disableAllAdds={disableAllAdds}
                setDisableAllAdds={setDisableAllAdds}
            />,
            container
        )

        return () => {
            ReactDOM.unmountComponentAtNode(container)
        }
    }, [
        container,
        userMainInfo,
        loadingDisabledAdds,
        setRefetchDisableAdds,
        setLoadingDisabledAdds,
        setDisableAllAdds,
        disableAllAdds
    ])

    return null
}

const AddsOverlay = () => {
    const [_, setUsernames] = useState([])
    const previousUsernames = useRef([])
    const usernamesContainerMap = useRef(new Map())

    const injectAddsOverlay = useCallback(() => {
        const addsPopupClass =
            '.LtQF8 .zYgGl .JB8Z3 .ReactVirtualized__Grid__innerScrollContainer[role="list"]'

        const popup = document.querySelector(addsPopupClass)
        if (!popup) return

        const usersDivList = popup.querySelectorAll('div.H8CAi')

        let overlayContainer = document.getElementById('addsOverlayContainer')
        if (!overlayContainer) {
            overlayContainer = document.createElement('div')
            overlayContainer.setAttribute('id', 'addsOverlayContainer')
            document.body.appendChild(overlayContainer)
        }

        const currentUsernames = []
        const overlayElements = []

        usersDivList.forEach(user => {
            const userNameDiv = user.querySelector('.NKUoR .RMaXm .iQDcn.nonIntl')
            if (!userNameDiv) return

            const username = userNameDiv.textContent
            const infoElement = user.querySelector('.sGsBQ')
            if (!infoElement) return

            currentUsernames.push(username)

            let container = usernamesContainerMap.current.get(username)

            if (!container || !document.body.contains(container)) {
                container = document.createElement('div')
                container.setAttribute('id', `adds-${username}`)
                infoElement.prepend(container)
                usernamesContainerMap.current.set(username, container)
            }

            overlayElements.push({ container, username })
        })

        // Step 1: Update the state with the current usernames list
        setUsernames(currentUsernames)

        // Step 2: Clean up any removed usernames from the DOM
        const removedUsernames = Array.from(usernamesContainerMap.current.keys()).filter(
            username => !currentUsernames.includes(username)
        )

        removedUsernames.forEach(username => {
            const container = usernamesContainerMap.current.get(username)
            if (container) {
                ReactDOM.unmountComponentAtNode(container)
                usernamesContainerMap.current.delete(username)
            }
        })
        let toggleAllAddsContainer
        const addedMeContainer = document.querySelector('.LtQF8 .zYgGl .JB8Z3') as HTMLDivElement

        if (addedMeContainer) {
            toggleAllAddsContainer = document.querySelector('#toggle-add-all-friends')
            if (!toggleAllAddsContainer) {
                toggleAllAddsContainer = document.createElement('div')
                toggleAllAddsContainer.setAttribute('id', 'toggle-add-all-friends')
                addedMeContainer.prepend(toggleAllAddsContainer)
                addedMeContainer.style.position = 'relative'
                toggleAllAddsContainer.style.position = 'absolute'
                toggleAllAddsContainer.style.top = '8px'
                toggleAllAddsContainer.style.left = '8px'
            }
        }

        // Step 3: Render the overlay elements for each user
        ReactDOM.render(
            <AddsOverlayProvider>
                {addedMeContainer && <AllAddsToggle container={toggleAllAddsContainer} />}
                {overlayElements.map(overlay => (
                    <AddsOverlayWrapper
                        key={overlay.username}
                        username={overlay.username}
                        container={overlay.container}
                    />
                ))}
            </AddsOverlayProvider>,
            overlayContainer
        )
        previousUsernames.current = currentUsernames
    }, [setUsernames])
    usePopupObserver(
        '.LtQF8 .zYgGl .JB8Z3 .ReactVirtualized__Grid__innerScrollContainer[role="list"]',
        injectAddsOverlay
    )

    return null
}

export default AddsOverlay
