import * as React from 'react'
import { Label } from '../ui/label'
import Help from './help'
import { Textarea } from '../ui/textarea'

type propType = {
    label?: string
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    suffix?: React.ReactNode
    prefix?: React.ReactNode
} & Omit<React.ComponentProps<typeof Textarea>, 'prefix'>

const CETextarea = React.forwardRef<HTMLTextAreaElement, propType>(
    (props: propType, ref: React.ForwardedRef<HTMLTextAreaElement>) => {
        const { error, info, label, htmlFor, suffix, prefix, ...rest } = props
        return (
            <div className="flex flex-col">
                {label ? (
                    <div className="flex gap-1 mb-2.5 items-center">
                        <Label htmlFor={htmlFor}>{label}</Label>
                        {info && <Help label={info} />}
                    </div>
                ) : null}

                <Textarea id={htmlFor} {...rest} ref={ref} />

                {error && <p className="text-venetian-red text-sm mt-0.5">{error}</p>}
            </div>
        )
    }
)

export default CETextarea
