import { useEffect, useCallback, useRef } from 'react'

const usePopupObserver = (selector: string, callback: () => void) => {
    const observerRef = useRef<MutationObserver | null>(null)
    const intervalRef = useRef<NodeJS.Timeout | null>(null)
    const timeoutRef = useRef<NodeJS.Timeout | null>(null)

    const setupObserver = useCallback(() => {
        observerRef.current = new MutationObserver(mutations => {
            // Clear existing timeout
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current)
            }

            // Set a new timeout
            timeoutRef.current = setTimeout(() => {
                callback()
            }, 50) // Short delay to batch rapid updates
        })

        const startObserving = () => {
            const container = document.querySelector(selector)
            if (container) {
                observerRef.current?.observe(container, {
                    childList: true,
                    subtree: true
                })
                callback() // Initial call
                console.log('Started observing')
                return true
            }
            return false
        }

        if (!startObserving()) {
            intervalRef.current = setInterval(() => {
                if (startObserving()) {
                    clearInterval(intervalRef.current!)
                }
            }, 100)
        }
    }, [selector, callback])

    const setupDocumentObserver = useCallback(() => {
        const documentObserver = new MutationObserver(mutations => {
            const container = document.querySelector(selector)

            if (container && observerRef.current) {
                // Check if the target element exists in the mutations
                const targetExists = mutations.some(mutation => {
                    return Array.from(mutation.addedNodes).some(node => {
                        return (
                            node instanceof Element &&
                            (node.matches(selector) || node.querySelector(selector))
                        )
                    })
                })

                if (targetExists) {
                    observerRef.current.disconnect()
                    observerRef.current.observe(container, {
                        childList: true,
                        subtree: true
                    })
                    callback()
                    console.log('Reconnected')
                }
            }
        })

        documentObserver.observe(document.body, {
            childList: true,
            subtree: true
        })

        return documentObserver
    }, [selector, callback])

    useEffect(() => {
        setupObserver()
        const documentObserver = setupDocumentObserver()

        return () => {
            if (intervalRef.current) {
                clearInterval(intervalRef.current)
            }
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current)
            }
            if (observerRef.current) {
                observerRef.current.disconnect()
            }
            documentObserver.disconnect()
        }
    }, [setupObserver, setupDocumentObserver])
}

export default usePopupObserver
