import CEButton from '@/components/shared/ce-button'
import CEUnderlineInput from '@/components/shared/ce-underline-input'
import { useChatting } from '@/provider/chatting-provider'
import React, { useEffect, useState } from 'react'
import * as API from '@/scripts/api'
import { setLocalPresetValue } from '@/lib/common'

const City = () => {
    const { preset, setPreset } = useChatting()

    const { details = {} } = preset
    const { city, timezone, matchUsersLocation = false } = details
    const [currentCity, setCurrentCity] = useState(city)
    const [editCity, setEditCity] = useState(false)
    const [loading, setLoading] = useState(false)
    const [currentTime, setCurrentTime] = useState<string>('')

    const handleSubmit = async () => {
        if (!currentCity.trim()) return
        setLoading(true)

        const response = await API.getTimezone(currentCity.trim())

        if (response) {
        }
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                timezone: response.data?.timezone,
                city: currentCity.trim()
            }
        }))
        await setLocalPresetValue({ timezone: response.data?.timezone, city: currentCity.trim() })

        setLoading(false)
        setEditCity(false)
    }

    useEffect(() => {
        if (!timezone) return
        const intervalId = setInterval(updateTime, 30 * 1000)
        updateTime()

        return () => clearInterval(intervalId)
    }, [timezone])

    useEffect(() => {
        if (matchUsersLocation) {
            setCurrentCity(city)
            setEditCity(false)
        }
    }, [matchUsersLocation])

    const updateTime = () => {
        if (timezone) {
            const formattedTime = new Intl.DateTimeFormat('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                timeZone: timezone,
                hour12: true // Use 12-hour format with AM/PM
            }).format(new Date())

            setCurrentTime(`${timezone} timezone now ${formattedTime}`)
        } else {
            setCurrentTime('')
        }
    }

    return (
        <div>
            <div className="flex gap-2">
                <div className="flex-1">
                    <CEUnderlineInput
                        placeholder="City"
                        name="city"
                        value={currentCity || ''}
                        onChange={e => {
                            setCurrentCity(e.target.value)
                        }}
                        autoComplete="off"
                        disabled={!editCity}
                    />
                </div>
                <CEButton
                    size="sm"
                    onClick={() => {
                        if (editCity) {
                            handleSubmit()
                        } else {
                            setEditCity(true)
                        }
                    }}
                    disabled={matchUsersLocation}
                    submitting={loading}
                >
                    {editCity ? 'Submit' : 'Edit'}
                </CEButton>
            </div>
            {currentTime ? <span className="text-ce-gray-500 text-sm">{currentTime}</span> : null}
        </div>
    )
}

export default City
