import * as React from 'react'
import { Label } from '../ui/label'
import Help from './help'
import { Textarea } from '../ui/textarea'
import CEButton from './ce-button'

type propType = {
    label?: string
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    linkPlaceholder: string
} & Omit<React.ComponentProps<typeof Textarea>, 'prefix'>

const CTAInput = React.forwardRef<HTMLTextAreaElement, propType>(
    (props: propType, ref: React.ForwardedRef<HTMLTextAreaElement>) => {
        const inputRef = React.useRef<HTMLTextAreaElement>(null)

        const {
            error,
            info,
            label,
            htmlFor,
            linkPlaceholder,
            onChange,
            disabled = false,
            ...rest
        } = props

        const handleButtonClick = () => {
            const newValue = (inputRef.current.value || '') + ' ' + linkPlaceholder
            if (onChange) {
                // Manually trigger onChange event
                const event = new Event('input', {
                    bubbles: true
                }) as unknown as React.ChangeEvent<HTMLTextAreaElement>
                Object.defineProperty(event, 'target', {
                    writable: true,
                    value: inputRef.current
                })
                inputRef.current.value = newValue
                inputRef.current.dispatchEvent(event as unknown as Event)
                onChange(event)
            }
        }

        return (
            <div className="flex flex-col">
                {label ? (
                    <div className="flex gap-1 mb-2.5 items-center">
                        <Label htmlFor={htmlFor}>{label}</Label>
                        {info && <Help label={info} />}
                    </div>
                ) : null}

                <Textarea
                    id={htmlFor}
                    {...rest}
                    onChange={e => {
                        onChange(e)
                    }}
                    disabled={disabled}
                    ref={inputRef}
                />
                <CEButton
                    className="text-blue-primary border-blue-primary mt-2 w-fit h-8 px-2"
                    variant="outline"
                    disabled={disabled}
                    onClick={handleButtonClick}
                >
                    {linkPlaceholder}
                </CEButton>

                {error && <p className="text-venetian-red text-sm mt-0.5">{error}</p>}
            </div>
        )
    }
)

export default CTAInput
