import CEInput from '@/components/shared/ce-input'
import { useGetStarted } from '@/provider/get-started-provider'
import React from 'react'
import { Label } from '@/components/ui/label'

const CTA = () => {
    const { preset, setPreset } = useGetStarted()

    const updateCTAInfo = (e: React.ChangeEvent<HTMLInputElement>) => {
        setPreset(prev => ({
            ...prev,
            cta: {
                ...prev.cta,
                ctaSet: {
                    ...prev.cta.ctaSet,
                    ctaInfo: [{ ...prev.cta.ctaSet.ctaInfo[0], [e.target.name]: e.target.value }]
                }
            }
        }))
    }

    return (
        <div className="flex flex-col gap-4">
            <Label>CTA</Label>
            <CEInput
                label="Platform"
                htmlFor="platform"
                name="platform"
                placeholder="Platform"
                value={preset.cta.ctaSet.ctaInfo[0].platform}
                onChange={updateCTAInfo}
            />
            <CEInput
                label="Link"
                htmlFor="link"
                name="link"
                placeholder="Link"
                value={preset.cta.ctaSet.ctaInfo[0].link}
                onChange={updateCTAInfo}
            />
        </div>
    )
}

export default CTA
