import React, { useEffect, useState } from 'react'
import { cn } from '@/lib/utils'
import Header from '@/components/content/header'
import { Toaster } from '@/components/ui/toaster'
import ContentBody from '@/components/content'
import { useChatting } from '@/provider/chatting-provider'
import ChattingOverlay from '@/components/content/chatting-overlay'
import 'slick-carousel/slick/slick.css'
import 'slick-carousel/slick/slick-theme.css'
import {
    checkSnapChatReloadTooManyTime,
    snapChatReloadToManyTimes,
    snapChatReloadToManyTimesRefreshable
} from '@/lib/snapChatReloadTooManyTime'
import { checkFriendsLoadedFeed } from '@/lib/checkFriendFeedLoaded'
import { snapChatNeedsToReload } from '@/lib/snapChatNeedsToReload'
import AddsOverlay from '@/components/content/adds-overlay'
const App = () => {
    const [isOpen, setIsOpen] = useState(true)
    const [mediaEnabled, setMediaEnabled] = useState(true)
    const { setHaveCameraIntegrated } = useChatting()
    const [isEnglishLanguage, setIsEnglishLanguage] = useState(navigator.language.startsWith('en-'))

    useEffect(() => {
        const checkLanguageChange = () => {
            const isEnglish = navigator.language.startsWith('en-')
            if (isEnglish !== isEnglishLanguage) {
                setIsEnglishLanguage(isEnglish)
            }
        }

        // Check for changes every 5 second (adjust the interval as needed)
        const intervalId = setInterval(checkLanguageChange, 5000)

        return () => clearInterval(intervalId) // Cleanup on unmount
    }, [isEnglishLanguage])

    const toggleIsOpen = () => {
        setIsOpen(prevIsOpen => !prevIsOpen)
    }

    const checkWebcamIntegrated = () => {
        navigator.mediaDevices
            .getUserMedia({ video: true })
            .then(stream => {
                console.log('media stream got enabled')
                setHaveCameraIntegrated(true)
            })
            .catch(error => {
                console.log('media stream not got enabled')
                setHaveCameraIntegrated(false)
                console.error('Error accessing media devices:', error)
            })
    }

    useEffect(() => {
        const handlePermissionChange = async () => {
            try {
                const permissionStatus = await navigator.permissions.query({
                    name: 'camera' as PermissionName
                })

                const updateMediaEnabled = () => {
                    if (permissionStatus.state === 'granted') {
                        setMediaEnabled(true)
                    } else {
                        setMediaEnabled(false)
                    }
                }

                // Initial check
                updateMediaEnabled()

                // Listen for changes
                permissionStatus.onchange = updateMediaEnabled
            } catch (error) {
                console.error('Error checking camera permissions:', error)
                setMediaEnabled(false)
            }
        }

        handlePermissionChange()
    }, [])

    const updateSnapContentWidth = () => {
        const container = document.querySelector('.Vbjsg.WJjwl')
        if (container) {
            if (isOpen) {
                container.setAttribute('style', 'margin-right: 380px')
                console.log('on')
            } else {
                container.removeAttribute('style')
                console.log('off')
            }
        }
    }

    useEffect(() => {
        updateSnapContentWidth()
    }, [isOpen])

    useEffect(() => {
        checkWebcamIntegrated()
        const messageListener = (request, sender, sendResponse) => {
            if (request.type === 'toggleAction') {
                setIsOpen(prevIsOpen => !prevIsOpen)
            }
        }

        chrome.runtime.onMessage.addListener(messageListener)
        return () => chrome.runtime.onMessage.removeListener(messageListener)
    }, [])

    useEffect(() => {
        const body = document.querySelector('body')
        if (body) {
            body.style.minHeight = 'calc(100vh - 8px)'
        }
    }, [])

    useEffect(() => {
        const reloadPage = () => {
            setTimeout(() => {
                window.location.reload()
            }, 3000)
        }
        window.addEventListener('offline', reloadPage)
        return () => window.removeEventListener('offline', reloadPage)
    }, [])

    useEffect(() => {
        const checkRefreshableContent = () => {
            const isReloadNeeded = snapChatNeedsToReload()
            if (isReloadNeeded) {
                // reloading the page
                clearInterval(timer)
                setTimeout(() => {
                    window.location.reload()
                }, 3000)
            }
        }
        // execute on interval
        const timer = setInterval(checkRefreshableContent, 5000)

        // removing interval from memory also when component unmounts
        return () => {
            clearInterval(timer)
        }
    }, [])

    useEffect(() => {
        // Set an interval to check the feed every 2 seconds
        const timer = setInterval(() => {
            const { success, shouldClearInterval } = checkFriendsLoadedFeed()

            if (shouldClearInterval) {
                clearInterval(timer) // Stop the interval if the feed is loaded
                setTimeout(() => {
                    window.location.reload()
                }, 3000)
            }
        }, 5000)

        // Cleanup the interval when the component unmounts
        return () => {
            clearInterval(timer)
        }
    }, [])

    useEffect(() => {
        // Set an interval to check the feed every 2 seconds
        const timer = setInterval(() => {
            const { success, shouldClearInterval } = checkSnapChatReloadTooManyTime()

            if (shouldClearInterval) {
                clearInterval(timer) // Stop the interval if the feed is loaded
            }

            if (!success && shouldClearInterval) {
                const timer = setInterval(() => {
                    const isRefreshable = snapChatReloadToManyTimesRefreshable()
                    console.log('### isRefreshable ', isRefreshable)
                    if (isRefreshable) {
                        clearInterval(timer)
                        setTimeout(() => {
                            window.location.reload()
                        }, 3000)
                    }
                }, 2000)
            }
        }, 2000)

        // Cleanup the interval when the component unmounts
        return () => {
            clearInterval(timer)
        }
    }, [])

    return (
        <>
            <ChattingOverlay />
            <AddsOverlay />
            <div
                className={cn(
                    `fixed w-[370px] h-full top-0 right-0 overflow-y-auto p-4 bg-primary z-[2147483666] text-white`,
                    isOpen ? '' : 'hidden'
                )}
                id="snapbot-container-body"
            >
                <Header toggleIsOpen={toggleIsOpen} />
                <ContentBody mediaEnabled={mediaEnabled} isEnglishLanguage={isEnglishLanguage} />
                <Toaster />
            </div>
            <div className="fixed z-[21474836661]" id="snap-bot-container-portal"></div>
        </>
    )
}

export default App
