import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
    'flex items-center justify-center gap-1 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2  disabled:opacity-50 disabled:cursor-not-allowed ring-offset-slate-950 focus-visible:ring-slate-300',
    {
        variants: {
            variant: {
                default: 'bg-blue-primary text-white hover:bg-blue-primary/90',
                destructive: 'bg-blood-organ text-slate-50 hover:bg-blood-organ/90',
                outline:
                    'border border-slate-800 bg-slate-950 hover:bg-slate-950/90 hover:text-slate-90',
                secondary: 'bg-slate-950 text-slate-50 hover:bg-slate-950/80',
                ghost: 'hover:bg-slate-800 hover:text-slate-50',
                link: 'underline-offset-4 hover:underline text-slate-50'
            },
            size: {
                default: 'h-10 px-4 py-2',
                sm: 'h-9 rounded-md px-3',
                lg: 'h-11 rounded-md px-6',
                icon: 'h-10 w-10'
            }
        },
        defaultVariants: {
            variant: 'default',
            size: 'lg'
        }
    }
)

export interface ButtonProps
    extends React.ButtonHTMLAttributes<HTMLButtonElement>,
        VariantProps<typeof buttonVariants> {
    asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
    ({ className, variant, size, asChild = false, ...props }, ref) => {
        const Comp = asChild ? Slot : 'button'
        return (
            <Comp
                className={cn(buttonVariants({ variant, size, className }))}
                ref={ref}
                {...props}
            />
        )
    }
)
Button.displayName = 'Button'

export { Button, buttonVariants }
