import * as React from 'react'
import { Label } from '../ui/label'
import {
    Select,
    SelectContent,
    SelectGroup,
    SelectItem,
    SelectLabel,
    SelectTrigger,
    SelectValue
} from '@/components/ui/select'
import Help from './help'
import { ChevronDown, X } from 'lucide-react'

type propType = {
    label?: string
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    suffix?: React.ReactNode
    prefix?: React.ReactNode
    options: {
        label: React.ReactNode
        value: string
    }[]
    placeholder?: string
    triggerProps?: React.ComponentProps<typeof SelectTrigger>
} & React.ComponentProps<typeof Select>

function ClearableSelect(props: propType) {
    const {
        error,
        info,
        label,
        htmlFor,
        suffix,
        prefix,
        options,
        placeholder,
        value,
        triggerProps = { className: 'w-full', size: 'lg' },
        onValueChange = (value: string | undefined) => {},
        ...rest
    } = props
    return (
        <div className="flex flex-col flex-1">
            {label ? (
                <div className="flex gap-1 mb-2.5 items-center">
                    <Label htmlFor={htmlFor}>{label}</Label>
                    {info && <Help label={info} />}
                </div>
            ) : null}
            <Select value={value} onValueChange={onValueChange} {...rest}>
                <SelectTrigger
                    value={value}
                    {...triggerProps}
                    suffix={
                        value ? (
                            <button
                                className="absolute right-3 top-[calc(50%-8px)]"
                                onClick={e => {
                                    e.stopPropagation()
                                    onValueChange(null)
                                }}
                            >
                                <X className="h-4 w-4 opacity-50" />
                            </button>
                        ) : (
                            <ChevronDown className="absolute right-3 top-[calc(50%-8px)] h-4 w-4 opacity-50" />
                        )
                    }
                >
                    <SelectValue
                        placeholder={
                            <span className="text-slate-400">Select {placeholder ?? '...'}</span>
                        }
                    />
                </SelectTrigger>
                <SelectContent>
                    <SelectGroup>
                        {options.length > 0 ? (
                            <>
                                {options.map(i => (
                                    <SelectItem value={i.value}>{i.label}</SelectItem>
                                ))}
                            </>
                        ) : (
                            <SelectLabel>No option available</SelectLabel>
                        )}
                    </SelectGroup>
                </SelectContent>
            </Select>
            {error && <p className="text-venetian-red text-sm mt-0.5">{error}</p>}
        </div>
    )
}

export default ClearableSelect
