import Compressor from 'compressorjs'

export const allowedImageType = ['image/png', 'image/jpg', 'image/jpeg']

export const readAsDataURLAsync = (file: File) =>
    new Promise((resolve, reject) => {
        const reader = new FileReader()

        reader.onabort = () => reject(new Error('File reading was aborted'))
        reader.onerror = () => reject(new Error('File reading has failed'))
        reader.onload = () => {
            const fileType = file.name.split('.').pop().toLowerCase()
            switch (fileType) {
                case 'png':
                case 'jpg':
                case 'jpeg':
                case 'bmp':
                    resolve(reader.result)
                    break
                default:
                    reject(new Error(`Unsupported file type: ${fileType}`))
            }
        }

        reader.readAsDataURL(file)
    })

export const compressImage = (file: File) =>
    new Promise((resolve, reject) => {
        new Compressor(file, {
            quality: 0.8, // Adjust the quality as needed (0 to 1)
            maxWidth: 900,
            maxHeight: 1600,
            success(result) {
                resolve(result)
            },
            error(err) {
                reject(new Error(`Unable to load file type: ${file.name}`))
            }
        })
    })
