import SectionTab from '@/components/shared/section-tab'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { isMainAndSexySnapListValid } from '@/lib/checkBotRunnable'
import { CHATTING_TABS, ChattingSectionType, SnapInvalidationType } from '@/lib/constants'
import { useChatting } from '@/provider/chatting-provider'
import { cloneDeep, includes, some } from 'lodash'
import React, { useMemo } from 'react'
import CTA from './cta'
import Layout from './layout'
import Main from './main'
import Opener from './opener'
import SnapAdds from './snap-adds'
import Snaps from './snaps'
import FollowUps from './follow-ups'
import { Switch } from '@/components/ui/switch'

const Chatting = () => {
    const {
        inCompletePresetSection,
        openSectionStack,
        setOpenSectionStack,
        preset,
        setPreset,
        userMainInfo,
        ownerDetails
    } = useChatting()

    const { details = {} } = preset

    const isSnapsInValid = useMemo(() => {
        if (preset && preset.details && preset.details.snaps) {
            return isMainAndSexySnapListValid(preset.details.snaps)
        }
        return [SnapInvalidationType.SnapsLT4]
    }, [preset])

    const initiallyDisable =
        Object.keys(preset).length === 0 ||
        Object.keys(ownerDetails).length === 0 ||
        !userMainInfo.attemptFetch

    return openSectionStack.length === 0 ? (
        <>
            <div className="flex justify-between items-start">
                <p className="text-ce-gray-400 text-2xl font-medium pb-4">Chatting</p>

                <Switch
                    id="default"
                    checked={details?.enableChatting}
                    disabled={initiallyDisable}
                    onCheckedChange={value => {
                        setPreset(prev => {
                            return {
                                ...prev,
                                details: {
                                    ...(prev.details ?? {}),
                                    enableChatting: value
                                }
                            }
                        })
                    }}
                />
            </div>

            <div className="flex flex-col">
                {CHATTING_TABS.map((i, index) => (
                    <SectionTab
                        prefixIcon={
                            <i.icon
                                fill={
                                    inCompletePresetSection.includes(
                                        i.value as keyof typeof ChattingSectionType
                                    ) ||
                                    !userMainInfo.attemptFetch ||
                                    Object.keys(ownerDetails).length === 0
                                        ? '#C41C1C'
                                        : '#0975F1'
                                }
                            />
                        }
                        onClick={() => {
                            setOpenSectionStack(prev => {
                                const newPrev = cloneDeep(prev)
                                newPrev.push(i.value)
                                return newPrev
                            })
                        }}
                        hideSeparator={index === CHATTING_TABS.length - 1}
                        disabled={initiallyDisable}
                        key={i.value}
                    >
                        {i.name}
                    </SectionTab>
                ))}
            </div>
        </>
    ) : (
        <Layout>
            {openSectionStack.includes(ChattingSectionType.MAIN) ? <Main /> : <></>}
            {openSectionStack.includes(ChattingSectionType.SNAPS) ? (
                <>
                    {!!isSnapsInValid.length && (
                        <Alert variant="destructive">
                            <AlertDescription>
                                <ul className="list-disc pl-4">
                                    {isSnapsInValid.includes(SnapInvalidationType.Description) && (
                                        <li>Description is mendatory in Main and Sexy snaps.</li>
                                    )}

                                    {isSnapsInValid.includes(SnapInvalidationType.SnapsLT4) && (
                                        <li>
                                            Minimum 4 snaps are required combined of Main and Sexy
                                            snaps.
                                        </li>
                                    )}
                                    {isSnapsInValid.includes(
                                        SnapInvalidationType.OutfitSnapLT4
                                    ) && (
                                        <li>
                                            Minimum 4 snaps are required combined of Main and Sexy
                                            snaps with same outfit.
                                        </li>
                                    )}
                                </ul>
                            </AlertDescription>
                        </Alert>
                    )}
                    <Snaps />
                </>
            ) : (
                <></>
            )}
            {openSectionStack.includes(ChattingSectionType.FOLLOW_UPS) ? <FollowUps /> : <></>}
            {openSectionStack.includes(ChattingSectionType.OPENER) ? <Opener /> : <></>}
            {openSectionStack.includes(ChattingSectionType.CTAPHASE) ? <CTA /> : <></>}
            {openSectionStack.includes(ChattingSectionType.SNAPADDS) ? <SnapAdds /> : <></>}
        </Layout>
    )
}

export default Chatting
