import CEButton from '@/components/shared/ce-button'
import CEInput from '@/components/shared/ce-input'
import { TELEGRAM_CONTACT } from '@/lib/constants'
import { useChatting } from '@/provider/chatting-provider'
import { useGetStarted } from '@/provider/get-started-provider'
import { authStore } from '@/scripts/store'
import React, { useEffect, useState } from 'react'
import Email from './email'
import Telegram from './telegram'

const LicenseKey = () => {
    const [licenseKey, setLicenseKey] = useState(authStore.license_key)
    const [loading, setLoading] = useState(false)
    const { setLicenseKey: setContextLicenseKey } = useGetStarted()
    const { resetModelList } = useChatting()

    useEffect(() => {
        if (authStore.license_key) {
            setLicenseKey(authStore.license_key)
        }
    }, [authStore.isAuthenticated])

    return (
        <div className="flex flex-col gap-4">
            <div className="w-full flex flex-row items-end gap-1">
                <div className="flex-1">
                    <CEInput
                        label="License Key"
                        placeholder="License key"
                        value={licenseKey}
                        onChange={e => {
                            setLicenseKey(e.target.value)
                        }}
                    />
                </div>

                <CEButton
                    onClick={async () => {
                        if (!licenseKey.trim()) return
                        setLoading(true)
                        resetModelList()
                        const res = await authStore.validateLicenseKey(licenseKey)
                        if (res) {
                            setContextLicenseKey({ isValid: true, key: licenseKey })
                        } else {
                            setContextLicenseKey({ isValid: false, key: '' })
                            console.log('Incorrect license key')
                        }
                        setLoading(false)
                    }}
                    submitting={loading}
                >
                    Submit
                </CEButton>
            </div>

            <Email />
            <Telegram />
            <CEButton
                className="w-full border border-slate-800 text-center text-white py-2 text-sm rounded mt-2 relative gap-1 cursor-pointer h-11 hover:border-blue-primary hover:text-blue-primary"
                onClick={() => {
                    window.open(TELEGRAM_CONTACT)
                }}
                variant="outline"
            >
                Buy More Conversations
            </CEButton>
        </div>
    )
}

export default LicenseKey
