import Help from '@/components/shared/help'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { OwnerSettingType } from '@/lib/types/user.type'
import React, { useEffect, useMemo } from 'react'
import { getUniqueID, handleParseInt } from '@/lib/common'
import TimeRange from './time-range'
import { cloneDeep } from 'lodash'
import { validateAddsRunCycle } from '@/lib/checkBotRunnable'
import CEInput from '@/components/shared/ce-input'
import { useChatting } from '@/provider/chatting-provider'
import { DEFAULT_OWNER_SETTINGS_VALUE } from '@/lib/defaultOwnerSettingValue'

const RunCycle = () => {
    const { ownerDetails, setOwnerDetails } = useChatting()
    const ownerPreset = ownerDetails?.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE

    const handleUpdateStartTimeSlot = (value: string, id: string) => {
        setOwnerDetails(prev => {
            const updatedSlot = cloneDeep(prev)

            updatedSlot.owner_setting = updatedSlot.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE
            const index = updatedSlot.owner_setting.runCycle.schedule.findIndex(i => i.id === id)
            updatedSlot.owner_setting.runCycle.schedule[index].start_time = value
            return updatedSlot
        })
    }

    const handleUpdateEndTimeSlot = (value: string, id: string) => {
        setOwnerDetails(prev => {
            const updatedSlot = cloneDeep(prev)

            updatedSlot.owner_setting = updatedSlot.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE
            const index = updatedSlot.owner_setting.runCycle.schedule.findIndex(i => i.id === id)
            updatedSlot.owner_setting.runCycle.schedule[index].end_time = value
            return updatedSlot
        })
    }

    const handleRemoveSlot = (id: string) => {
        setOwnerDetails(prev => {
            const updatedSlot = cloneDeep(prev)

            return {
                ...updatedSlot,
                owner_setting: {
                    ...updatedSlot.owner_setting,
                    runCycle: {
                        ...updatedSlot.owner_setting.runCycle,
                        schedule: updatedSlot.owner_setting.runCycle.schedule.filter(
                            i => i.id !== id
                        )
                    }
                }
            }
        })
    }

    const addNewSlotToDay = () => {
        setOwnerDetails(prev => {
            const updatedSlot = cloneDeep(prev)

            updatedSlot.owner_setting = updatedSlot.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE
            updatedSlot.owner_setting.runCycle.schedule.push({
                end_time: undefined,
                start_time: undefined,
                id: getUniqueID()
            })

            return updatedSlot
        })
    }

    const toggleEnable = (
        key: keyof OwnerSettingType,
        value: boolean,
        disable: (keyof OwnerSettingType)[]
    ) => {
        setOwnerDetails(prev => {
            const updatedSettings = cloneDeep(prev)
            updatedSettings.owner_setting =
                updatedSettings.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE

            if (value) {
                disable.forEach(key => {
                    updatedSettings.owner_setting[key].enabled = false
                })
            }
            updatedSettings.owner_setting[key].enabled = value
            return updatedSettings
        })
    }

    const updateDelay = (e: React.ChangeEvent<HTMLInputElement>) => {
        setOwnerDetails(prev => {
            const updatedSettings = cloneDeep(prev)
            updatedSettings.owner_setting =
                updatedSettings.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE
            const value = handleParseInt(e.target.value)
            if (!value && updatedSettings.owner_setting?.delayChatting?.enabled) {
                updatedSettings.owner_setting.delayChatting.enabled = false
            }
            updatedSettings.owner_setting.delayChatting.delay = value
            return updatedSettings
        })
    }

    const invalidSlots = useMemo(() => {
        const value = validateAddsRunCycle(ownerPreset.runCycle)

        return value
    }, [ownerPreset.runCycle])

    useEffect(() => {
        const value = validateAddsRunCycle(ownerPreset.runCycle)
        if (value.length > 0 && ownerPreset.runCycle.enabled) {
            toggleEnable('runCycle', false, ['delayChatting'])
        }
    }, [ownerPreset.runCycle])

    return (
        <div className="mb-8 p-3 bg-primary rounded-md flex flex-col gap-8">
            <div>
                <div className="flex justify-between items-center">
                    <div className="text-base font-semibold leading-6 inline-flex items-center gap-2">
                        <Label>Run cycle</Label>
                        <Help label={'Adds will only took place in selected time slots'} />
                    </div>

                    <Switch
                        id="run-cycle"
                        checked={ownerPreset.runCycle.enabled}
                        onCheckedChange={value => {
                            toggleEnable('runCycle', value, ['delayChatting'])
                        }}
                        disabled={!!invalidSlots.length}
                    />
                </div>

                <TimeRange
                    slots={ownerPreset.runCycle?.schedule ?? []}
                    handleUpdateStartTimeSlot={handleUpdateStartTimeSlot}
                    handleUpdateEndTimeSlot={handleUpdateEndTimeSlot}
                    handleRemoveSlot={handleRemoveSlot}
                    addNewSlotToDay={addNewSlotToDay}
                    invalidSlots={invalidSlots}
                />
            </div>

            <div>
                <div className="flex justify-between items-center mb-5">
                    <div className="text-base font-semibold leading-6 inline-flex items-center gap-2">
                        <Label>Delay Chatting</Label>
                        <Help label={'Chatting will initiate after stated minutes'} />
                    </div>

                    <Switch
                        id="delay-chatting"
                        checked={ownerPreset.delayChatting.enabled}
                        onCheckedChange={value => {
                            toggleEnable('delayChatting', value, ['runCycle'])
                        }}
                        disabled={!ownerPreset.delayChatting.delay}
                    />
                </div>

                <CEInput
                    suffix={'minute(s)'}
                    className="pr-[72px]"
                    type="number"
                    name="delay"
                    value={ownerPreset.delayChatting.delay}
                    onChange={updateDelay}
                />
            </div>
        </div>
    )
}

export default RunCycle
