import { ChevronDown, X } from 'lucide-react'
import * as React from 'react'

import { Command } from '@/components/ui/command'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from '@/components/ui/dialog'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Button } from '../ui/button'
import CEInput from './ce-input'
import Spinner from './spinner'

type propType = {
    children: (state: { searchValue: string }) => React.ReactNode
    value?: { title: string; id: string }
    placeholder?: string
    onClear: () => void
    inputProps?: React.ComponentProps<typeof CEInput>
    /**
     * id to be passed when handling delete operation
     */
    toBeDeletedId?: number
    /**
     * delete modal title
     */
    deleteModalTitle?: string
    /**
     * detailed description message of the modal
     */
    deleteModalDescription?: string
    /**
     * @description callback to be called when user clicks delete button
     * @param id id to be passed when delete is triggered from the modal delete button
     */
    onDeleteCallback?: (id: number) => void
    /**
     * @description callback to be called when user cancels delete operation
     */
    onCancelDeleteCallback?: () => void
    loading?: boolean
}

function CreatableSelect(props: propType) {
    const {
        children,
        value,
        placeholder,
        onClear,
        inputProps = {
            className: 'pr-8 w-full focus-visible:!ring-offset-0 focus-visible:!ring-transparent'
        },
        toBeDeletedId,
        deleteModalTitle,
        deleteModalDescription,
        onDeleteCallback,
        onCancelDeleteCallback,
        loading = false
    } = props
    const inputRef = React.useRef<HTMLInputElement>(null)
    const [open, setOpen] = React.useState(false)
    const [searchValue, setSearchValue] = React.useState('')

    React.useEffect(() => {
        if (value) {
            setOpen(false)
        }
        setSearchValue(value?.title ?? '')
    }, [value])

    React.useEffect(() => {
        let timeoutId
        if (open) {
            timeoutId = setTimeout(() => {
                inputRef.current.focus()
            }, 500)
        }
        return () => {
            clearTimeout(timeoutId)
        }
    }, [open])

    return (
        <>
            {/* generic delete modal starts */}
            <Dialog
                open={toBeDeletedId !== undefined}
                onOpenChange={
                    onCancelDeleteCallback ? onCancelDeleteCallback.bind(this) : undefined
                }
            >
                <DialogContent className="w-[320px] max-h-[90vh] !left-[unset] right-[20px] translate-x-0 overflow-auto p-2">
                    <DialogHeader className="py-2">
                        <DialogTitle className="text-white">{deleteModalTitle}</DialogTitle>
                        <DialogDescription className="text-white">
                            {deleteModalDescription}
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button
                            type="button"
                            variant="link"
                            size="sm"
                            onClick={
                                onCancelDeleteCallback
                                    ? onCancelDeleteCallback.bind(this)
                                    : undefined
                            }
                            disabled={loading}
                        >
                            Cancel
                        </Button>
                        <Button
                            type="submit"
                            variant="destructive"
                            size="sm"
                            onClick={
                                onDeleteCallback
                                    ? onDeleteCallback.bind(this, toBeDeletedId)
                                    : undefined
                            }
                            disabled={loading}
                        >
                            Delete {loading && <Spinner />}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
            {/* generic delete modal ends */}

            <Popover
                open={open}
                onOpenChange={value => {
                    setOpen(value)
                }}
            >
                <PopoverTrigger asChild disabled={loading}>
                    <div className="relative">
                        <CEInput
                            ref={inputRef}
                            role="combobox"
                            suffix={
                                loading ? (
                                    <Spinner />
                                ) : searchValue.trim() ? (
                                    <button
                                        onClick={e => {
                                            e.stopPropagation()
                                            onClear()
                                            setSearchValue('')
                                            setOpen(true)
                                        }}
                                    >
                                        <X className="ml-2 h-5 w-5 shrink-0 " />
                                    </button>
                                ) : (
                                    <ChevronDown className="ml-2 h-5 w-5 shrink-0 cursor-pointer" />
                                )
                            }
                            {...inputProps}
                            value={searchValue}
                            onChange={e => {
                                if (loading) return
                                if (value) {
                                    onClear()
                                }
                                setSearchValue(e.target.value)
                            }}
                            placeholder={placeholder}
                        />
                    </div>
                </PopoverTrigger>
                <PopoverContent
                    className="p-0"
                    style={{ width: `${inputRef.current?.offsetWidth}px` }}
                >
                    <Command>
                        {children({
                            searchValue: searchValue
                        })}
                    </Command>
                </PopoverContent>
            </Popover>
        </>
    )
}

export default CreatableSelect
