import CEInput from '@/components/shared/ce-input'
import { handleParseInt } from '@/lib/common'
import { PresetSettingType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import React from 'react'

const Settings = () => {
    const { preset, setPreset } = useChatting()
    const { details = {} } = preset
    const { settings = {} } = details

    const updateSettings = (name: keyof PresetSettingType, value) => {
        setPreset(prev => {
            return {
                ...prev,
                details: {
                    ...(prev.details ?? {}),
                    settings: {
                        ...(prev.details?.settings ?? {}),
                        [name]: value
                    }
                }
            }
        })
    }

    return (
        <div>
            <p className="text-ce-gray-400 text-2xl font-medium pb-4">Settings</p>
            <div className="flex flex-col gap-5">
                <CEInput
                    label="Delay Chatting When User Present"
                    info="There will be delay of specified seconds between every message when user is present."
                    suffix={'second(s)'}
                    className="pr-20"
                    type="number"
                    name="delayChatting"
                    onChange={e =>
                        updateSettings(
                            e.target.name as keyof PresetSettingType,
                            handleParseInt(e.target.value)
                        )
                    }
                    value={settings.delayChatting}
                />
                <CEInput
                    label="Auto Refresh"
                    info="How often you want the bot to refresh the page."
                    suffix={'minute(s)'}
                    className="pr-[72px]"
                    type="number"
                    value={settings?.autoRefresh}
                    name="autoRefresh"
                    onChange={e =>
                        updateSettings(
                            e.target.name as keyof PresetSettingType,
                            handleParseInt(e.target.value)
                        )
                    }
                />

                <CEInput
                    label="Don't Reply"
                    info="Bot will not reply to user older than X day(s)"
                    suffix={'day(s)'}
                    className="pr-14"
                    type="number"
                    name={'dontReply'}
                    onChange={e =>
                        updateSettings(
                            e.target.name as keyof PresetSettingType,
                            handleParseInt(e.target.value)
                        )
                    }
                    value={settings.dontReply}
                />
            </div>
        </div>
    )
}

export default Settings
