import { API_ENDPOINT, ERROR_MSG } from '@/lib/constants'
import { authStore } from '../store'
import { ApiResponse } from './types/response.type'

const uploadSnap = async (file: File): Promise<ApiResponse> => {
    try {
        const formData = new FormData()
        formData.append('file', file)

        const response = await fetch(`${API_ENDPOINT}/uploadSnap`, {
            method: 'POST',
            headers: { Authorization: authStore.getAPIKey() },
            body: formData
        })
        const resData = await response.json()
        if (!resData?.status) throw new Error(resData?.message)

        return resData
    } catch (error) {
        return {
            status: false,
            message: error?.message || ERROR_MSG.SOMETHING_WENT_WRONG
        }
    }
}

export default uploadSnap
