import CEButton from '@/components/shared/ce-button'
import { LocalStorage } from '@/lib/chrome-storage'
import { KEY_SB_CURRENT_MODEL_ID, KEY_SB_CURRENT_PRESET_ID, SnapTimeType } from '@/lib/constants'
import {
    DEFAULT_FOLLOW_UP,
    DEFAULT_OPENER,
    DEFAULT_SETTING,
    DEFAULT_SNAPS_APP
} from '@/lib/defaultPresetsValue'
import { LiveSnapType } from '@/lib/types/preset.type'
import { snapsType, useGetStarted } from '@/provider/get-started-provider'
import * as API from '@/scripts/api/index'
import { authStore } from '@/scripts/store'
import { ChevronLeft } from 'lucide-react'
import React, { useState } from 'react'

type propType = {
    children: React.ReactNode
    onBack: () => void
    onNext: () => void
    currentStep: number
}

const Layout = (props: propType) => {
    const { children, onBack, onNext, currentStep } = props
    const { preset, snaps } = useGetStarted()
    const [loading, setLoading] = useState(false)

    const handleUploadSnaps = async () => {
        const snapsObjects = async (i: snapsType) => {
            const res = await API.uploadSnap(i.file)
            if (res.status) {
                const snap: LiveSnapType = {
                    id: i.id,
                    lightning: SnapTimeType.NIGHT_TIME,
                    purpose: i.type,
                    snapUrl: res.data,
                    description: i.description
                }
                return snap
            } else {
                return false
            }
        }

        const uploadedSnaps = await Promise.all(
            snaps.map(async i => {
                return await snapsObjects(i)
            })
        )

        return uploadedSnaps.filter(i => typeof i !== 'boolean') as LiveSnapType[]
    }

    const createModelAndPreset = async () => {
        try {
            const { name, title, ...rest } = preset
            if (name.trim()) {
                const modelResponse = await API.createModel({
                    title: name.trim()
                })
                const savedSnaps = await handleUploadSnaps()
                if (modelResponse.status) {
                    const modelId = modelResponse.data.id
                    if (title.trim()) {
                        const presetResponse = await API.createPreset({
                            detail: {
                                ...rest,
                                matchUsersLocation: true,
                                enableChatting: true,
                                name: name,
                                opener: DEFAULT_OPENER,
                                snapsAdd: DEFAULT_SNAPS_APP,
                                followUps: DEFAULT_FOLLOW_UP,
                                snaps: savedSnaps,
                                settings: DEFAULT_SETTING
                            },
                            model_id: modelId,
                            title: title.trim(),
                            item_type: 'preset'
                        })
                        if (presetResponse.status) {
                            console.log('Preset created successfully')
                            const modelId = modelResponse.data.id
                            const presetId = presetResponse.data.id
                            return { modelId, presetId }
                        } else {
                            console.error('Error creating preset:', presetResponse.message)
                            return { modelId: modelResponse.data.id }
                        }
                    }
                } else {
                    console.error('Error creating model:', modelResponse.message)
                    return {}
                }
            }
        } catch (error) {
            console.error('Error:', error)
            return {}
        }
    }

    const handleSetPresets = async () => {
        setLoading(true)
        const { modelId, presetId } = (await createModelAndPreset()) ?? {}
        await LocalStorage.setItem(KEY_SB_CURRENT_MODEL_ID, modelId)
        await LocalStorage.setItem(KEY_SB_CURRENT_PRESET_ID, presetId)
        await API.flagPassStarter()
        await authStore.init()
        setLoading(false)
    }

    const isValidSnap = snaps.every(i => !!i.description.trim()) && snaps.length >= 4

    return (
        <div className="flex flex-col gap-4">
            <CEButton
                onClick={onBack}
                prefix={<ChevronLeft size={16} />}
                className="w-fit"
                size="sm"
                variant="secondary"
            >
                Back
            </CEButton>

            {children}
            <CEButton
                size="lg"
                onClick={currentStep < 5 ? onNext : handleSetPresets}
                submitting={loading}
                disabled={currentStep === 5 ? !isValidSnap : false}
            >
                {currentStep === 5 ? 'Save' : 'Next'}
            </CEButton>
        </div>
    )
}

export default Layout
