import * as React from 'react'
import { observer } from 'mobx-react-lite'
import { configure } from 'mobx'
import { UserInfoType } from '@/lib/types/user.type'
import { LocalStorage } from '@/lib/chrome-storage'
import { MULTI_PHASES, ServiceMessageName, USER_FRIENDS_GET_SUCCESSFULLY } from '@/lib/constants'
import * as API from '@/scripts/api'
import { callApiWithRetries, sleep } from '@/lib/common'
import { chattingStatusType, messageParamsType } from '@/lib/types/chatting-overlay.type'
import { cloneDeep, uniq } from 'lodash'
import { authStore } from '@/scripts/store'

type chattingOverlayProps = {
    children: React.ReactNode
}

type userMainInfoType = {
    data: UserInfoType
    attemptFetch: boolean
}

type ChattingOverlayType = {
    userStatus: chattingStatusType[]
    setUserStatus: React.Dispatch<React.SetStateAction<chattingStatusType[]>>
    setDisableAllChatting: React.Dispatch<React.SetStateAction<boolean>>
    setRefetchAllConversations: React.Dispatch<React.SetStateAction<boolean>>
    userMainInfo: UserInfoType
    userStatusFetchSuccessfully: boolean
    toggleIncludeInAnalytics: (uuid: string) => void
    togglePauseChatting: (uuid: string) => void
    markUserAsConverted: (uuid: string) => void
    disableAllChatting: boolean
}

const ChattingOverlayContext = React.createContext<ChattingOverlayType>({} as ChattingOverlayType)

configure({
    enforceActions: 'never'
})

export const ChattingOverlayProvider = observer(({ children }: chattingOverlayProps) => {
    const [userMainInfo, setUserMainInfo] = React.useState<userMainInfoType>({
        attemptFetch: false,
        data: null
    })
    const [disableAllChatting, setDisableAllChatting] = React.useState(false)
    const [userStatus, setUserStatus] = React.useState([] as chattingStatusType[])
    const [refetchAllConversations, setRefetchAllConversations] = React.useState(false)
    const [userStatusFetchSuccessfully, setUserStatusFetchSuccessfully] = React.useState(false)
    const backgroundGhostedUsers = React.useRef<string[]>([])

    const host = window.location.host
    const isUserLoggedIn = host === 'web.snapchat.com'

    const handleGetLoggedInUser = async () => {
        if (isUserLoggedIn) {
            do {
                const isUserGetSuccessfully = await LocalStorage.getItem(
                    USER_FRIENDS_GET_SUCCESSFULLY
                )
                await sleep(3000)
                if (isUserGetSuccessfully) {
                    const res = await API.getLoggedInUser()
                    if (res.status) {
                        setUserMainInfo({ attemptFetch: true, data: res.data.snapchatters[0] })
                        return
                    }
                    break
                }
            } while (true)
            window.location.reload()
        }
        setUserMainInfo({ attemptFetch: true, data: null })
    }

    React.useEffect(() => {
        handleGetLoggedInUser()
    }, [])

    React.useEffect(() => {
        if (userMainInfo.attemptFetch && isUserLoggedIn && !userMainInfo.data) {
            window.location.reload()
        }
    }, [userMainInfo])

    const toggleIncludeInAnalytics = React.useCallback((uuid: string) => {
        setUserStatus(prev => {
            const statuses = cloneDeep(prev)

            const index = statuses.findIndex(i => i.ruid === uuid)
            if (index > -1) {
                statuses[index] = {
                    ...statuses[index],
                    include_analytic_converted: !statuses[index].include_analytic_converted
                }
            }
            return statuses
        })
    }, [])

    const togglePauseChatting = React.useCallback((uuid: string) => {
        setUserStatus(prev => {
            const statuses = cloneDeep(prev)

            const index = statuses.findIndex(i => i.ruid === uuid)
            if (index > -1) {
                const pause_chatting = statuses[index].paused_chatting
                statuses[index] = {
                    ...statuses[index],
                    paused_chatting: !pause_chatting
                }
                chrome.runtime.sendMessage({
                    action: ServiceMessageName.PauseChatting,
                    data: { ruid: uuid, pause: !pause_chatting }
                })
            } else {
                statuses.push({
                    ruid: uuid,
                    phase: null,
                    chat_status: 'Main',
                    ghost_message_count: 0,
                    include_analytic_converted: true,
                    is_chat_disabled: false,
                    is_conversed: false,
                    runame: `Main-${uuid}`,
                    paused_chatting: true
                })

                chrome.runtime.sendMessage({
                    action: ServiceMessageName.PauseChatting,
                    data: { ruid: uuid, pause: true }
                })
            }

            return statuses
        })
    }, [])

    const markUserAsConverted = React.useCallback((uuid: string) => {
        setUserStatus(prev => {
            const statuses = cloneDeep(prev)

            const index = statuses.findIndex(i => i.ruid === uuid)
            if (index > -1) {
                statuses[index] = {
                    ...statuses[index],
                    is_conversed: true
                }
            }
            return statuses
        })
    }, [])

    const handleGetUserStatus = async () => {
        const getChatStatusCall = async () =>
            await API.getChatStatus({
                owner_id: userMainInfo.data.mutable_username
            })

        try {
            const response = await callApiWithRetries(getChatStatusCall)
            setUserStatus(response.data)
            setUserStatusFetchSuccessfully(true)
        } catch (error) {
            console.error('Error getting conversation status', error.message)
        }
    }

    React.useEffect(() => {
        if (userMainInfo.data && authStore.isAuthenticated) {
            handleGetUserStatus()
        }
    }, [userMainInfo, authStore.isAuthenticated])

    const handleMessage = React.useCallback(() => {
        return message => {
            if (message.action === ServiceMessageName.ChatOverLay) {
                const param = message.data.params as messageParamsType['data']
                const { uuid, state } = param

                if (state === 'Ghosting') {
                    backgroundGhostedUsers.current = uniq([...backgroundGhostedUsers.current, uuid])
                } else if (['Converted'].includes(state)) {
                    backgroundGhostedUsers.current = uniq(
                        backgroundGhostedUsers.current.filter(i => i !== uuid)
                    )
                }

                setUserStatus(prev => {
                    const statuses = cloneDeep(prev)

                    const index = statuses.findIndex(i => i.ruid === uuid)
                    switch (state) {
                        case 'Main Phase':
                            if (index === -1) {
                                statuses.push({
                                    ruid: uuid,
                                    phase: null,
                                    chat_status: state,
                                    ghost_message_count: 0,
                                    include_analytic_converted: true,
                                    is_chat_disabled: false,
                                    is_conversed: false,
                                    runame: `${state}-${uuid}`,
                                    paused_chatting: false
                                })
                            }
                            break
                        case 'Duplicate':
                            if (index === -1) {
                                statuses.push({
                                    ruid: uuid,
                                    phase: null,
                                    chat_status: 'duplicate',
                                    ghost_message_count: 0,
                                    include_analytic_converted: true,
                                    is_chat_disabled: false,
                                    is_conversed: false,
                                    runame: `${state}-${uuid}`,
                                    paused_chatting: false
                                })
                            } else {
                                statuses[index] = {
                                    ...statuses[index],
                                    is_chat_disabled: true,
                                    is_conversed: false,
                                    chat_status: 'duplicate'
                                }
                            }
                            break
                        case 'Converted':
                            if (index > -1) {
                                statuses[index] = {
                                    ...statuses[index],
                                    is_chat_disabled: true,
                                    is_conversed: true,
                                    chat_status: 'complete'
                                }
                            }
                            break
                        case 'Disabled':
                        case 'Complete':
                            if (index > -1) {
                                statuses[index] = {
                                    ...statuses[index],
                                    is_chat_disabled: true,
                                    is_conversed: false,
                                    chat_status: 'complete'
                                }
                            }
                            break
                        case 'Ghosting':
                            if (index > -1) {
                                statuses[index] = {
                                    ...statuses[index],
                                    ghost_message_count:
                                        statuses[index].ghost_message_count === 1
                                            ? 2
                                            : statuses[index].ghost_message_count,
                                    chat_status: 'ghosting'
                                }
                            }
                            break
                    }

                    return statuses
                })
            }
        }
    }, [])

    React.useEffect(() => {
        const messageHandler = handleMessage()
        chrome.runtime.onMessage.addListener(messageHandler)

        return () => {
            chrome.runtime.onMessage.removeListener(messageHandler)
        }
    }, [handleMessage])


    React.useEffect(() => {
        if (refetchAllConversations) {
            handleGetUserStatus()
            setRefetchAllConversations(false)
        }
    }, [refetchAllConversations])


    const value = {
        userStatus,
        setUserStatus,
        userMainInfo: userMainInfo.data,
        userStatusFetchSuccessfully,
        toggleIncludeInAnalytics,
        togglePauseChatting,
        markUserAsConverted,
        disableAllChatting,
        setDisableAllChatting,
        setRefetchAllConversations
    } as ChattingOverlayType

    return (
        <ChattingOverlayContext.Provider value={value}>{children}</ChattingOverlayContext.Provider>
    )
})

export const useChattingOverlay = () => {
    const context = React.useContext(ChattingOverlayContext)

    if (context === undefined)
        throw new Error('useChattingOverlay must be used within a ChattingOverlay')

    return context
}
