import React from 'react'
import Tabs from './tabs'
import { authStore } from '@/scripts/store'
import StartingGuide from './starting-guide'
import { observer } from 'mobx-react-lite'
import { configure } from 'mobx'

type propType = {
    mediaEnabled: boolean
    isEnglishLanguage: boolean
}
configure({
    enforceActions: 'never'
})
const ContentBody = observer((props: propType) => {
    return !authStore.show_starter_guide ? <Tabs {...props} /> : <StartingGuide />
})

export default ContentBody
