import { waitForElementTillLoad } from './common'

export const snapChatReloadToManyTimes = () => {
    const reloadTooManyTimeContent = document.querySelector(
        '.ELpTb .sjHS1 .N8iGC'
    ) as HTMLDivElement

    console.log('#### snapChatReloadToManyTimes', reloadTooManyTimeContent?.innerText)
    
    return !!reloadTooManyTimeContent?.innerText
        .replace(/\s/g, '')
        .toLowerCase()
        .includes('thepagehasbeenreloadedtoomanytimes')
}

export const snapChatReloadToManyTimesRefreshable = () => {
    const reloadTooManyTimeContent = document.querySelector(
        '.ELpTb .sjHS1 .N8iGC'
    ) as HTMLDivElement

    return !!reloadTooManyTimeContent?.innerText
        .replace(/\s/g, '')
        .toLowerCase()
        .includes('pleasetryagainin0seconds')
}

/**
 * Check the reload too many times
 * Returns an object with:
 * - success: boolean indicating if the feed loaded successfully
 * - shouldClearInterval: boolean to indicate if we should clear the interval
 */
export const checkSnapChatReloadTooManyTime = () => {
    try {
        // Check for the error message div indicating feed loading failure
        const reloadTooManyTimes = snapChatReloadToManyTimes()

        // Check for feed items inside the container

        // If there's an error message indicating the feed couldn't load
        if (reloadTooManyTimes) {
            console.log('Feed not loaded yet, retrying...')
            return { success: false, shouldClearInterval: true }
        }

        const feedContainer = document.querySelectorAll(
            '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'
        )

        // If feed items are found, it means the feed loaded successfully
        if (feedContainer && feedContainer.length > 0) {
            console.log('Feed loaded successfully!')
            return { success: true, shouldClearInterval: true }
        }

        // If feed is not loaded yet, but no error, continue retrying
        return { success: false, shouldClearInterval: false }
    } catch (error) {
        console.error('Error checking feed:', error)
        return { success: false, shouldClearInterval: false }
    }
}
