import CEInput from '@/components/shared/ce-input'
import Help from '@/components/shared/help'
import SectionHeader from '@/components/shared/section-header'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { Switch } from '@/components/ui/switch'
import { getUniqueID, handleParseInt } from '@/lib/common'
import { PresetFollowUpType } from '@/lib/types/preset.type'
import { cn } from '@/lib/utils'
import { useChatting } from '@/provider/chatting-provider'
import { cloneDeep } from 'lodash'
import { Plus } from 'lucide-react'
import React, { useEffect } from 'react'

const HoursLaterFollowUp = () => {
    const { preset, setPreset } = useChatting()
    const { details = {} } = preset
    const { followUps = {} as PresetFollowUpType } = details

    const { xHourFollowUp = {} as PresetFollowUpType['xHourFollowUp'] } = followUps
    const { messages, defaultSetting, hours } = xHourFollowUp

    useEffect(() => {
        if (!messages) {
            addMessage()
        }
    }, [])

    const addMessage = () => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                followUps: {
                    ...(prev.details?.followUps ?? {}),
                    xHourFollowUp: {
                        ...(prev.details?.followUps?.xHourFollowUp ?? {}),
                        messages: [
                            ...(prev.details?.followUps?.xHourFollowUp?.messages ?? []),
                            { id: getUniqueID(), message: '' }
                        ]
                    }
                } as PresetFollowUpType
            }
        }))
    }

    const removeMessage = (id: string) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                followUps: {
                    ...(prev.details?.followUps ?? {}),
                    xHourFollowUp: {
                        ...(prev.details?.followUps?.xHourFollowUp ?? {}),
                        messages: [
                            ...(prev.details?.followUps?.xHourFollowUp?.messages.filter(
                                i => i.id !== id
                            ) ?? [])
                        ]
                    }
                } as PresetFollowUpType
            }
        }))
    }

    const updateXHoursFollowUpValue = (
        key: keyof PresetFollowUpType['xHourFollowUp'],
        value: boolean | number
    ) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                followUps: {
                    ...(prev.details?.followUps ?? {}),
                    xHourFollowUp: {
                        ...(prev.details?.followUps?.xHourFollowUp ?? {}),
                        [key]: value
                    }
                } as PresetFollowUpType
            }
        }))
    }

    const updateXHoursFollowUpMessage = (id: string, value: string) => {
        setPreset(prev => {
            const newPrev = cloneDeep(prev)
            const messageIndex = (
                newPrev.details?.followUps?.xHourFollowUp?.messages ?? messages
            ).findIndex(i => i.id === id)

            newPrev.details.followUps.xHourFollowUp.messages[messageIndex].message = value

            return newPrev
        })
    }

    return (
        <div className="bg-primary rounded-md">
            <SectionHeader
                label="X Hours Follow Up"
                info={<p>The static message will be sent to user after X hours if not converted</p>}
            />
            <Separator />

            <div className="flex flex-col gap-5 p-3">
                <div className="flex gap-2 items-center">
                    <Label>Default follow up</Label>
                    <Help label="confirms the user has subscribed to the platform with a followup confirmation message." />
                    <div className="flex-grow" />
                    <Switch
                        checked={defaultSetting}
                        onCheckedChange={value => {
                            updateXHoursFollowUpValue('defaultSetting', value)
                        }}
                    />
                </div>
                <CEInput
                    label="Follow Up Hours"
                    type="number"
                    info={'Follow up message will be sent after specified hours'}
                    placeholder="Hours"
                    value={hours}
                    suffix="hour(s)"
                    className="pr-16"
                    disabled={defaultSetting}
                    onChange={e => {
                        updateXHoursFollowUpValue('hours', handleParseInt(e.target.value))
                    }}
                />

                <div className="flex flex-col gap-2 w-full">
                    <div className="flex gap-1 mb-0.5 items-center">
                        <Label className="mb-0.5">Messages</Label>
                        <Help
                            label={
                                'Random message from below added message will be sent to follow up'
                            }
                        />
                    </div>
                    {messages?.map(i => (
                        <div key={i.id} className="flex gap-2 items-center w-full">
                            <CEInput
                                value={i.message}
                                className={cn(
                                    'relative run-cycle',
                                    !i.message.trim()
                                        ? 'border-venetian-red focus-visible:ring-venetian-red'
                                        : ''
                                )}
                                disabled={defaultSetting}
                                placeholder="Type in a message..."
                                onChange={e => {
                                    const msg = e.target.value
                                    updateXHoursFollowUpMessage(i.id, msg)
                                }}
                            />
                            {messages?.length > 1 ? (
                                <button
                                    className="ml-auto  h-6 w-fit rounded"
                                    onClick={() => {
                                        removeMessage(i.id)
                                    }}
                                    disabled={defaultSetting}
                                >
                                    <img
                                        src={chrome.runtime.getURL('./assets/svg/bin.svg')}
                                        style={{ height: '24px' }}
                                    />
                                </button>
                            ) : null}
                        </div>
                    ))}

                    <Button
                        variant="link"
                        className="h-fit p-2 w-fit self-end"
                        onClick={() => {
                            addMessage()
                        }}
                        disabled={messages?.length === 5}
                    >
                        Add run <Plus size={18} color="#0975F1" />
                    </Button>
                </div>
            </div>
        </div>
    )
}

export default HoursLaterFollowUp
