import * as React from 'react'
import * as API from '@/scripts/api'
import {
    ChattingSectionType,
    DEFAULT_PRESET_LOCAL_VALUE,
    KEY_SB_BOT_CONFIG,
    KEY_SB_CURRENT_MODEL_ID,
    KEY_SB_CURRENT_PRESET_ID,
    SB_CAMERA_LOADED,
    SB_LOCAL_PRESET_VALUE,
    ServiceMessageName,
    TAB_LIST,
    TabType,
    USER_FRIENDS_GET_SUCCESSFULLY
} from '@/lib/constants'
import { authStore } from '@/scripts/store'
import { observer } from 'mobx-react-lite'
import { configure } from 'mobx'
import { LocalStorage } from '@/lib/chrome-storage'
import { PresetType } from '@/lib/types/preset.type'
import { ModelType } from '@/lib/types/model.type'
import { checkBotRunnable } from '@/lib/checkBotRunnable'
import { cloneDeep, debounce } from 'lodash'
import { OwnerDetailType, UserInfoType } from '@/lib/types/user.type'
import { callApiWithRetries, sleep } from '@/lib/common'
import { ClientInfoType } from '@/lib/types/clientInfo.type'

type chattingProviderProps = {
    children: React.ReactNode
}

type userMainInfoType = {
    data: UserInfoType
    attemptFetch: boolean
}

type ChattingStateType = {
    preset: PresetType
    selectedModel: number
    selectedFolder: number
    selectedPreset: number
    openSectionStack: string[]
    models: ModelType[]
    modelsPresets: PresetType[]
    modelsPresetFolder: PresetType[]
    inCompletePresetSection: (keyof typeof ChattingSectionType | keyof typeof TabType)[]
    botRunning: boolean
    ownerDetails: OwnerDetailType
    activeTab: string
    setPreset: React.Dispatch<React.SetStateAction<PresetType>>
    setSelectedModel: React.Dispatch<React.SetStateAction<number>>
    setSelectedFolder: React.Dispatch<React.SetStateAction<number>>
    setSelectedPreset: React.Dispatch<React.SetStateAction<number>>
    setOpenSectionStack: React.Dispatch<React.SetStateAction<string[]>>
    setHaveCameraIntegrated: React.Dispatch<React.SetStateAction<boolean>>
    resetModelAndPrest: () => void
    getModelList: (modelId?: number) => void
    getModelsPresetList: (presetId?: number, folderId?: number) => void
    setBotRunning: React.Dispatch<React.SetStateAction<boolean>>
    resetModelList: () => void
    setOwnerDetails: React.Dispatch<React.SetStateAction<OwnerDetailType>>
    setActiveTab: React.Dispatch<React.SetStateAction<string>>
    userMainInfo: userMainInfoType
    clientInfo: ClientInfoType
    setClientInfo: React.Dispatch<React.SetStateAction<ClientInfoType>>
}

const ChattingContext = React.createContext<ChattingStateType>({} as ChattingStateType)

const defaultDisableSection: (keyof typeof ChattingSectionType | keyof typeof TabType)[] = [
    'MAIN',
    'SNAPS',
    'OPENER',
    'CTAPHASE',
    'CTA_LINKS',
    'SNAPADDS',
    'FOLLOW_UPS'
]

configure({
    enforceActions: 'never'
})

export const ChattingProvider = observer(({ children }: chattingProviderProps) => {
    const syncPresetId = React.useRef(null)
    const trackUpdatingPresetCompleted = React.useRef(false)
    const pendingPresetUpdate = React.useRef(null)
    const presetUpdatePrevention = React.useRef(false)
    const trackUpdatingOwnerSettingCompleted = React.useRef(false)
    const pendingOwnerSettingUpdate = React.useRef(null)
    const ownerSettingUpdatePrevention = React.useRef(false)
    const [botRunning, setBotRunning] = React.useState(false)
    const [canSaveModelAndPreset, setCanSaveModelAndPreset] = React.useState(false)
    const [haveCameraIntegrated, setHaveCameraIntegrated] = React.useState(false)
    const [models, setModels] = React.useState<ModelType[]>([])
    const [modelsPresets, setModelsPresets] = React.useState<PresetType[]>([])
    const [modelsPresetFolder, setModelsPresetFolder] = React.useState<PresetType[]>([])
    const [selectedModel, setSelectedModel] = React.useState<number | null>(null)
    const [selectedFolder, setSelectedFolder] = React.useState<number | null>(null)
    const [selectedPreset, setSelectedPreset] = React.useState<number | null>(null)
    const [openSectionStack, setOpenSectionStack] = React.useState<
        (keyof typeof ChattingSectionType)[]
    >([])
    const [userMainInfo, setUserMainInfo] = React.useState<userMainInfoType>({
        attemptFetch: false,
        data: null
    })
    const [activeTab, setActiveTab] = React.useState(TAB_LIST[0].value)
    const [ownerDetails, setOwnerDetails] = React.useState<OwnerDetailType>({} as OwnerDetailType)
    const [inCompletePresetSection, setIncompletePresetSection] =
        React.useState<(keyof typeof ChattingSectionType | keyof typeof TabType)[]>(
            defaultDisableSection
        )
    const [preset, setPreset] = React.useState({} as PresetType)

    const [clientInfo, setClientInfo] = React.useState({
        email: '',
        telegram: ''
    } as ClientInfoType)

    const host = window.location.host
    const isUserLoggedIn = host === 'web.snapchat.com'

    const handleGetLoggedInUser = async () => {
        if (isUserLoggedIn) {
            do {
                const isUserGetSuccessfully = await LocalStorage.getItem(
                    USER_FRIENDS_GET_SUCCESSFULLY
                )
                await sleep(3000)
                if (isUserGetSuccessfully) {
                    const res = await API.getLoggedInUser()
                    if (res.status) {
                        setUserMainInfo({ attemptFetch: true, data: res.data.snapchatters[0] })
                        return
                    }
                    break
                }
            } while (true)
            window.location.reload()
        }

        setUserMainInfo({ attemptFetch: true, data: null })
    }

    const getOwnerDetail = async () => {
        const apiCall = async () => await API.getOwnerProfile(userMainInfo.data.mutable_username)

        try {
            const response = await callApiWithRetries(apiCall)
            setOwnerDetails(response.data)
        } catch (error) {
            console.error('Error while fetching owner details', error.message)
        }
    }

    React.useEffect(() => {
        if (authStore.isAuthenticated) {
            handleGetLoggedInUser()
        }
    }, [authStore.isAuthenticated])

    React.useEffect(() => {
        if (authStore.isAuthenticated) {
            setClientInfo({
                email: authStore.licenseInformation?.email ?? '',
                telegram: authStore.licenseInformation?.telegram ?? ''
            })
        }
    }, [authStore.isAuthenticated])

    React.useEffect(() => {
        if (userMainInfo.attemptFetch && isUserLoggedIn && !userMainInfo.data) {
            window.location.reload()
        }
    }, [userMainInfo])

    const resetModelList = () => {
        setBotRunning(false)
        setCanSaveModelAndPreset(false)
        setModels([])
        setModelsPresets([])
        setModelsPresetFolder([])
        setOpenSectionStack([])
        setIncompletePresetSection(defaultDisableSection)
        setSelectedModel(null)
        setSelectedFolder(null)
        setSelectedPreset(null)
        setPreset({} as PresetType)
        setActiveTab(TAB_LIST[0].value)
    }

    const resetModelAndPrest = () => {
        setSelectedModel(null)
        setSelectedFolder(null)
        setSelectedPreset(null)
    }

    const updatedInCompletePreset = React.useMemo(() => {
        if (Object.keys(preset).length === 0) {
            return defaultDisableSection
        } else {
            return checkBotRunnable(preset, clientInfo)
        }
    }, [preset, clientInfo])

    React.useEffect(() => {
        setIncompletePresetSection(updatedInCompletePreset)
    }, [preset, clientInfo])

    const updatePreset = debounce(async preset => {
        // Access the latest preset value directly
        const currentPreset = preset

        if (Object.keys(currentPreset).length === 0 || !selectedPreset) return
        if (!presetUpdatePrevention.current) {
            presetUpdatePrevention.current = true
            return
        }

        if (trackUpdatingPresetCompleted.current) {
            pendingPresetUpdate.current = currentPreset
            return
        }

        trackUpdatingPresetCompleted.current = true
        pendingPresetUpdate.current = null
        const updatedPreset = cloneDeep(currentPreset)
        delete updatedPreset.userid

        const res = await API.updatePreset(updatedPreset)
        trackUpdatingPresetCompleted.current = false

        if (pendingPresetUpdate.current) {
            const nextPreset = pendingPresetUpdate.current
            pendingPresetUpdate.current = null // Clear pending update
            await updatePreset(nextPreset) // Call updatePreset with new preset
        }

        if (res.status) {
            // Handle success
        } else {
            if (
                ['signal is aborted without reason', 'The user aborted a request.'].includes(
                    res.message
                )
            )
                return

            setOpenSectionStack([])
            setPreset({} as PresetType)
            await getSelectedPresetDetail()
            console.error(`Failed to update model: ${res.message}`)
        }
    }, 1000)

    React.useEffect(() => {
        updatePreset(preset)
        return () => {
            updatePreset.cancel()
        }
    }, [preset])

    const getModelList = async (modelId?: number) => {
        const apiCall = async () => await API.getAllModels()

        try {
            const response = await callApiWithRetries(apiCall)
            if (response.status) {
                let currentModelId: number
                if (modelId) {
                    currentModelId = modelId
                } else {
                    currentModelId = await LocalStorage.getItem(KEY_SB_CURRENT_MODEL_ID)
                }

                const models = response.data as ModelType[]

                let isCurrentModelIdInLicense = response.data.findIndex(i => {
                    return i.id === currentModelId
                })

                if (isCurrentModelIdInLicense > -1) {
                    setSelectedModel(models[isCurrentModelIdInLicense].id)
                }
                if (models.length > 0 && isCurrentModelIdInLicense === -1) {
                    await LocalStorage.setItem(KEY_SB_CURRENT_MODEL_ID, models[0].id)
                    setSelectedModel(models[0].id)
                }
                if (models.length === 0) {
                    await LocalStorage.removeItems([KEY_SB_CURRENT_MODEL_ID])
                }
                setModels(models)
            }
        } catch (error) {
            console.error(error.message)
            // Handle error accordingly
            return { status: false }
        }
    }

    const getModelsPresetList = async (presetId = null, folderId = null) => {
        setSelectedFolder(folderId)
        setSelectedPreset(presetId)

        const apiCall = async () => await API.getModelsPreset(selectedModel)

        try {
            const response = await callApiWithRetries(apiCall)
            if (response.status) {
                let currentPresetId: number

                if (presetId) {
                    currentPresetId = presetId
                } else if (!folderId) {
                    currentPresetId = await LocalStorage.getItem(KEY_SB_CURRENT_PRESET_ID)
                }

                const modelsPreset = response.data as PresetType[]

                const folders = modelsPreset.filter(i => i.item_type === 'folder')
                const presets = modelsPreset.filter(i => i.item_type !== 'folder')

                let isCurrentPresetIdInModel = presets.findIndex(i => {
                    return i.id == currentPresetId
                })

                if (folderId) {
                    setSelectedFolder(folderId)
                } else {
                    if (isCurrentPresetIdInModel > -1) {
                        if (presets[isCurrentPresetIdInModel].parent_id) {
                            setSelectedFolder(presets[isCurrentPresetIdInModel].parent_id)
                        }
                        setSelectedPreset(presets[isCurrentPresetIdInModel].id)
                    }

                    if (presets.length > 0 && isCurrentPresetIdInModel === -1) {
                        await LocalStorage.setItem(KEY_SB_CURRENT_PRESET_ID, presets[0].id)
                        if (presets[0].parent_id) {
                            setSelectedFolder(presets[0].parent_id)
                        }
                        setSelectedPreset(presets[0].id)
                    }
                    if (presets.length === 0) {
                        await LocalStorage.removeItems([KEY_SB_CURRENT_PRESET_ID])
                    }
                }

                setModelsPresets(presets)
                setModelsPresetFolder(folders)
            }
        } catch (error) {
            console.error('Error occurred while getting model preset list: ', error.message)
            setModelsPresets([])
            setModelsPresetFolder([])
            // Handle error accordingly
        }
    }

    const getSelectedPresetDetail = async () => {
        const value = {
            ...DEFAULT_PRESET_LOCAL_VALUE,
            ...(await LocalStorage.getItem(SB_LOCAL_PRESET_VALUE))
        }

        const apiCall = async () => await API.getSelectedPresetDetail(selectedPreset)
        try {
            const response = await callApiWithRetries(apiCall)
            if (response.status) {
                const presetDetail = response.data as PresetType
                setPreset({
                    ...presetDetail,
                    details: {
                        ...(presetDetail.details ?? {}),
                        ...value
                    }
                })
            }
        } catch (error) {
            console.error('Error occurred while getting preset detail: ', error.message)
            resetModelAndPrest()
            await getModelList()
        }
    }

    const saveModelAndPreset = async () => {
        if (!selectedModel) {
            await LocalStorage.removeItems(KEY_SB_CURRENT_MODEL_ID)
        } else {
            await LocalStorage.setItem(KEY_SB_CURRENT_MODEL_ID, selectedModel)
        }
        if (!selectedPreset) {
            await LocalStorage.removeItems(KEY_SB_CURRENT_PRESET_ID)
        } else {
            await LocalStorage.setItem(KEY_SB_CURRENT_PRESET_ID, selectedPreset)
        }
    }

    React.useEffect(() => {
        const func = async () => {
            await getModelList()
        }
        if (authStore.isAuthenticated && authStore.licenseInformation.pass_starter) {
            func()
        }
    }, [authStore.isAuthenticated, authStore.show_starter_guide, authStore.license_key])

    React.useEffect(() => {
        const func = async () => {
            await getModelsPresetList()
            setCanSaveModelAndPreset(true)
        }

        if (selectedModel) {
            func()
        } else {
            setModelsPresets([])
            setModelsPresetFolder([])
            setSelectedFolder(null)
            setSelectedPreset(null)
        }
    }, [selectedModel])

    React.useEffect(() => {
        if (!selectedFolder) {
            const presets = modelsPresets.find(i => i.id === selectedPreset)
            if (presets?.parent_id) {
                setSelectedPreset(null)
            }
        } else {
            const folderPresets = modelsPresets.filter(i => i.parent_id === selectedFolder)
            if (folderPresets.length > 0) {
                const selectedPresetIndex = folderPresets.findIndex(i => i.id === selectedPreset)
                if (selectedPresetIndex > -1) {
                    setSelectedPreset(folderPresets[selectedPresetIndex].id)
                } else {
                    setSelectedPreset(folderPresets[0].id)
                }
            } else {
                setSelectedPreset(null)
            }
        }
    }, [selectedFolder])

    React.useEffect(() => {
        setOpenSectionStack([])
        setPreset({} as PresetType)
        if (selectedPreset) {
            getSelectedPresetDetail()
        } else {
            setActiveTab(TAB_LIST[0].value)
            setOpenSectionStack([])
        }
    }, [selectedPreset])

    const handleSetBotConfig = async () => {
        if (Object.keys(preset).length === 0) return
        const botConfig = {
            model: models.find(i => i.id === selectedModel),
            preset: preset
        }
        await LocalStorage.setItem(KEY_SB_BOT_CONFIG, botConfig)

        chrome.runtime.sendMessage({ action: ServiceMessageName.UpdateBotConfig })
    }

    React.useEffect(() => {
        const func = async () => {
            if (botRunning) {
                await handleSetBotConfig()
                chrome.runtime.sendMessage({ action: ServiceMessageName.RunBot })
            } else {
                chrome.runtime.sendMessage({ action: ServiceMessageName.StopBot })
            }
        }
        func()
    }, [botRunning])

    React.useEffect(() => {
        if (canSaveModelAndPreset) {
            saveModelAndPreset()
        }
    }, [selectedModel, selectedPreset, canSaveModelAndPreset])

    const setBotConfig = debounce(handleSetBotConfig, 1000)

    React.useEffect(() => {
        setBotConfig()
        return () => {
            setBotConfig.cancel()
        }
    }, [preset])

    React.useEffect(() => {
        LocalStorage.setItem(SB_CAMERA_LOADED, haveCameraIntegrated)
    }, [haveCameraIntegrated])

    const setOwnerSetting = debounce(async (ownerDetails: OwnerDetailType) => {
        if (Object.keys(ownerDetails).length === 0 || !ownerDetails.owner_setting) return
        if (!ownerSettingUpdatePrevention.current) {
            ownerSettingUpdatePrevention.current = true
            return
        }

        if (trackUpdatingOwnerSettingCompleted.current) {
            pendingOwnerSettingUpdate.current = ownerDetails
            return
        }
        trackUpdatingOwnerSettingCompleted.current = true
        pendingOwnerSettingUpdate.current = null

        const res = await API.updateOwnerSetting({
            owner_id: userMainInfo.data.mutable_username,
            owner_setting: ownerDetails.owner_setting
        })
        trackUpdatingOwnerSettingCompleted.current = false
        if (pendingOwnerSettingUpdate.current) {
            const nextPreset = pendingOwnerSettingUpdate.current
            pendingOwnerSettingUpdate.current = null // Clear pending update
            await setOwnerSetting(nextPreset) // Call updatePreset with new preset
        }
        if (res.status) {
        } else {
            if (
                ['signal is aborted without reason', 'The user aborted a request.'].includes(
                    res.message
                )
            )
                return
            await getOwnerDetail()
            console.error(`Failed to update owner settings: ${res.message}`)
        }
    }, 1000)

    React.useEffect(() => {
        setOwnerSetting(ownerDetails)
        return () => {
            setOwnerSetting.cancel()
        }
    }, [ownerDetails])

    const handleSyncOwnerPreset = async () => {
        const syncOwnerPresetCall = async () =>
            await API.syncOwnerPreset({
                owner_id: userMainInfo.data.mutable_username,
                preset_id: selectedPreset
            })

        try {
            const response = await callApiWithRetries(syncOwnerPresetCall)
            await getOwnerDetail()
        } catch (error) {
            console.error('Error syncing preset with ownerid', error.message)
        }
    }

    React.useEffect(() => {
        if (userMainInfo.data && selectedPreset && syncPresetId.current !== selectedPreset) {
            syncPresetId.current = selectedPreset
            handleSyncOwnerPreset()
        }
    }, [userMainInfo, selectedPreset])

    const value = {
        botRunning,
        preset,
        selectedModel,
        selectedFolder,
        selectedPreset,
        openSectionStack,
        models,
        modelsPresets,
        modelsPresetFolder,
        inCompletePresetSection,
        userMainInfo,
        ownerDetails,
        activeTab,
        setPreset,
        setSelectedModel,
        setSelectedFolder,
        setSelectedPreset,
        setOpenSectionStack,
        resetModelAndPrest,
        getModelList,
        getModelsPresetList,
        setBotRunning,
        resetModelList,
        setHaveCameraIntegrated,
        setOwnerDetails,
        setActiveTab,
        clientInfo,
        setClientInfo
    } as ChattingStateType

    return <ChattingContext.Provider value={value}>{children}</ChattingContext.Provider>
})

export const useChatting = () => {
    const context = React.useContext(ChattingContext)

    if (context === undefined) throw new Error('useTheme must be used within a ThemeProvider')

    return context
}
