import CreatableSelect from '@/components/shared/creatable-select'
import { Button } from '@/components/ui/button'
import { CommandGroup, CommandItem } from '@/components/ui/command'
import { PresetType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import { Copy, Trash2 } from 'lucide-react'
import React, { useMemo, useState } from 'react'
import { cloneDeep } from 'lodash'
import { matchesString } from '@/lib/common'
import * as API from '@/scripts/api'
import { AddIcon } from '@/assets/icons'
import { DEFAULT_PRESET } from '@/lib/defaultPresetsValue'
import { cn } from '@/lib/utils'

const Presets = () => {
    const {
        modelsPresets,
        selectedFolder,
        selectedModel,
        selectedPreset,
        setSelectedPreset,
        getModelsPresetList
    } = useChatting()
    const [loading, setLoading] = useState(false)
    const [copyPreset, setCopyPreset] = useState<{
        preset_id: number
        open: boolean
    }>({
        preset_id: null,
        open: false
    })
    const [toBeDeletedPresetId, setToBeDeletedPresetId] = useState<number | undefined>()
    // memoized response
    const toBeDeletedPreset = useMemo(
        () => modelsPresets.find(i => i.id === toBeDeletedPresetId),
        [toBeDeletedPresetId]
    )

    const selectedModelOption = modelsPresets.find(i => i.id === selectedPreset)

    const handleCreatePreset = async (presetTitle: string) => {
        setLoading(true)
        const response = await API.createPreset({
            title: presetTitle,
            model_id: selectedModel,
            parent_id: selectedFolder,
            item_type: 'preset',
            detail: DEFAULT_PRESET
        })
        if (response.status) {
            await getModelsPresetList(response.data.id, selectedFolder)
        } else {
            console.log('Error while creating preset', response.message)
        }
        setLoading(false)
    }

    const handleDeletePreset = async (presetId: number) => {
        setLoading(true)
        const response = await API.deletePreset([presetId])
        if (response.status) {
            if (presetId === selectedPreset) {
                await getModelsPresetList(null, selectedFolder)
            } else {
                await getModelsPresetList(selectedPreset, selectedFolder)
            }
        } else {
            console.log('Error while deleting preset', response.message)
        }
        setLoading(false)
    }

    return (
        <CreatableSelect
            loading={loading}
            placeholder="Type in a preset..."
            value={
                selectedModelOption
                    ? { id: String(selectedModelOption.id), title: selectedModelOption.title }
                    : undefined
            }
            onClear={() => {
                setSelectedPreset(null)
            }}
            toBeDeletedId={toBeDeletedPresetId}
            deleteModalTitle={toBeDeletedPresetId ? `Delete preset` : ``}
            deleteModalDescription={
                toBeDeletedPresetId
                    ? `Are you sure you want to delete preset "${toBeDeletedPreset.title}"?`
                    : ``
            }
            onDeleteCallback={async id => {
                console.log(`Preset with id ${id} needs to be deleted`)
                await handleDeletePreset(id)
                setToBeDeletedPresetId(undefined)
            }}
            onCancelDeleteCallback={() => setToBeDeletedPresetId(undefined)}
        >
            {({ searchValue }) => {
                let filterPreset: PresetType[] = cloneDeep(
                    modelsPresets.filter(i => i.parent_id === selectedFolder)
                )

                if (searchValue.trim() && !selectedPreset) {
                    filterPreset = filterPreset.filter(i =>
                        matchesString(i.title.trim(), searchValue.trim())
                    )
                }

                const allowCreateNew =
                    modelsPresets.filter(i =>
                        matchesString(i.title.trim(), searchValue.trim(), true)
                    ).length === 0 && searchValue.trim()

                return (
                    <CommandGroup
                        className={cn(filterPreset.length === 0 && !allowCreateNew ? 'p-0' : '')}
                    >
                        {filterPreset.map(preset => (
                            <CommandItem
                                key={preset.id}
                                value={String(preset.id)}
                                onSelect={currentValue => {
                                    setSelectedPreset(Number(currentValue))
                                }}
                                disabled={loading}
                                className="cursor-pointer"
                            >
                                <div className="group flex justify-between items-center w-full gap-2">
                                    <p className="text-white text-base font-semibold flex-1 truncate">
                                        {preset.title}
                                    </p>
                                    <button
                                        className="hidden group-hover:inline-block"
                                        disabled={loading}
                                        onClick={e => {
                                            e.stopPropagation()
                                            setCopyPreset({ preset_id: preset.id, open: true })
                                        }}
                                    >
                                        <Copy size={18} />
                                    </button>
                                    <Button
                                        disabled={loading}
                                        size="icon"
                                        variant="destructive"
                                        className="h-8 w-8"
                                        onClick={e => {
                                            e.stopPropagation()
                                            setToBeDeletedPresetId(preset.id)
                                        }}
                                    >
                                        <Trash2 size={18} />
                                    </Button>
                                </div>
                            </CommandItem>
                        ))}
                        {allowCreateNew ? (
                            <CommandItem
                                disabled={loading}
                                value={String(searchValue)}
                                onSelect={() => {
                                    handleCreatePreset(searchValue.trim())
                                }}
                                className="cursor-pointer"
                            >
                                <div className="flex justify-between items-center w-full gap-2">
                                    <AddIcon fill="white" />
                                    <p className="text-white text-base font-semibold flex-1 truncate">
                                        Create preset '{searchValue.trim()}'
                                    </p>
                                </div>
                            </CommandItem>
                        ) : null}
                    </CommandGroup>
                )
            }}
        </CreatableSelect>
    )
}

export default Presets
