import { Label } from '@/components/ui/label'
import React, { useState } from 'react'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogTitle,
    DialogTrigger
} from '@/components/ui/dialog'
import CEButton from '@/components/shared/ce-button'
import { useChatting } from '@/provider/chatting-provider'
import { Separator } from '@/components/ui/separator'
import SnapPreview from '../snap-preview'
import {
    getSnapSource,
    OutfitSelectableForList,
    purposeOptions,
    PurposeType,
} from '@/lib/constants'
import * as VisuallyHidden from '@radix-ui/react-visually-hidden'
import CESelect from '@/components/shared/ce-select'
import { Checkbox } from '@/components/ui/checkbox'
import { uniq } from 'lodash'
import { ScrollArea, ScrollBar } from '@/components/ui/scroll-area'
import { Button } from '@/components/ui/button'
import { Trash2 } from 'lucide-react'

type propsType = {
    specificSnapIdsKey: string
    onChange: (key: string, value: string | string[]) => void
    specificSnapId: string[]
    disabled?: boolean
}

const SpecificMediaSelector = (props: propsType) => {
    const { preset } = useChatting()
    const { details = {} } = preset
    const { snaps = [] } = details

    const [snapPurpose, setSnapPurpose] = useState(PurposeType.MAIN)

    const { onChange, specificSnapId, specificSnapIdsKey, disabled = false } = props

    const removeSpecificSnap = (id: string) => {
        onChange(
            specificSnapIdsKey,
            specificSnapId.filter(i => i !== id)
        )
    }

    return (
        <div className="flex flex-col gap-3">
            <div>
                <Label className="text-sm font-medium ">
                    Specific media({`${specificSnapId.length}`} selected)
                </Label>
                <Dialog>
                    <DialogTrigger asChild>
                        <CEButton disabled={disabled} size="sm" className="mt-1 w-full">
                            Select media
                        </CEButton>
                    </DialogTrigger>
                    <DialogContent
                        className="w-[320px] max-h-[90vh] !left-[unset] right-[20px] translate-x-0 overflow-auto p-2"
                        aria-describedby="select-media"
                    >
                        <DialogTitle className="text-xl font-semibold text-ce-gray-400">
                            Select media
                        </DialogTitle>
                        <VisuallyHidden.Root>
                            <DialogDescription>Select media</DialogDescription>
                        </VisuallyHidden.Root>
                        <Separator />

                        <div className="flex gap-2">
                            <CESelect
                                options={purposeOptions}
                                value={snapPurpose}
                                onValueChange={value => setSnapPurpose(value as PurposeType)}
                            />
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {snaps
                                .filter(i => i.purpose === snapPurpose)
                                .map(i => {
                                    const outfitSelectable = OutfitSelectableForList.includes(i.purpose)
                                    return (
                                        <div
                                            className="relative rounded border border-slate-800 h-fit"
                                            key={i.id}
                                        >
                                            <Checkbox
                                                id={i.id}
                                                className="absolute top-2 left-2"
                                                checked={specificSnapId.includes(i.id)}
                                                onCheckedChange={checked => {
                                                    onChange(
                                                        specificSnapIdsKey,
                                                        checked
                                                            ? uniq([...specificSnapId, i.id])
                                                            : specificSnapId.filter(j => j !== i.id)
                                                    )
                                                }}
                                            />
                                            <Label htmlFor={i.id}>
                                                <SnapPreview
                                                    src={getSnapSource(i.snapUrl)}
                                                    className=""
                                                />
                                                {outfitSelectable && i.outfit ? (
                                                    <ul className="flex gap-0.5 flex-col p-1 pl-5 flex-1 list-disc">
                                                        <li>{i.outfit}</li>
                                                    </ul>
                                                ) : null}
                                            </Label>
                                        </div>
                                    )
                                })}
                        </div>
                        <DialogFooter className="absolute h-0 w-0 -z-50 opacity-0">
                            Save changes
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>
            {specificSnapId?.length > 0 ? (
                <ScrollArea className="whitespace-nowrap rounded-md">
                    <div className="flex w-max space-x-2 py-2">
                        {specificSnapId.map(i => {
                            const snapCard = snaps.find(j => j.id === i)
                            return (
                                <div
                                    className="min-w-[108px] flex flex-col border rounded border-slate-800"
                                    key={i}
                                >
                                    <Button
                                        variant="destructive"
                                        className="h-6 w-full rounded-t rounded-b-none"
                                        onClick={() => {
                                            removeSpecificSnap(i)
                                        }}
                                        disabled={disabled}
                                    >
                                        <Trash2 size={16} />
                                    </Button>
                                    <SnapPreview src={getSnapSource(snapCard.snapUrl)} />
                                </div>
                            )
                        })}
                    </div>
                    <ScrollBar orientation="horizontal" />
                </ScrollArea>
            ) : null}
        </div>
    )
}

export default SpecificMediaSelector
