import { cn } from '@/lib/utils'
import React from 'react'

type propType = React.ImgHTMLAttributes<HTMLImageElement>

const SnapPreview = (props: propType) => {
    const { className = "rounded-t-none", ...rest } = props
    return <img alt={`snap`} className={cn("w-[108px] h-[192px] object-cover rounded", className)} {...rest} />
}

export default SnapPreview
