import { API_ENDPOINT, ServiceMessageName } from "@/lib/constants"
import { ApiResponse } from "../types/response.type"
import { authStore } from "../../store"
import { DeleteStoryParamsType } from "../types/params.type"

const deleteModel = async (story: DeleteStoryParamsType): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/story/delete`,
                    params: {
                        method: 'DELETE',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey(),
                        },
                        body: JSON.stringify(story)
                    }
                }
            },
            callback
        )
    })
}

export default deleteModel