import React from 'react'
import { Button } from '../ui/button'
import Spinner from './spinner'

type propType = {
    children: string | React.ReactNode
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    suffix?: React.ReactNode
    prefix?: React.ReactNode
    submitting?: boolean
} & Omit<React.ComponentProps<typeof Button>, 'prefix'>

const CEButton = (props: propType) => {
    const { children, prefix, suffix, submitting, disabled, ...rest } = props
    return (
        <Button disabled={disabled ?? submitting} {...rest}>
            {prefix && prefix}
            {children}
            {suffix && suffix}
            {submitting && <Spinner />}
        </Button>
    )
}

export default CEButton
