import { Button } from '@/components/ui/button'
import { Image } from 'lucide-react'
import React from 'react'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogTitle,
    DialogTrigger
} from '@/components/ui/dialog'
import * as VisuallyHidden from '@radix-ui/react-visually-hidden'
import { Separator } from '@/components/ui/separator'
import { useChatting } from '@/provider/chatting-provider'
import { getSnapSource, PurposeType } from '@/lib/constants'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import SnapPreview from '@/components/content/snap-preview'
import { cn } from '@/lib/utils'

type propsType = {
    onChange: (media: string) => void
    disabled?: boolean
    media: string
}

const SelectStoryImage = (props: propsType) => {
    const { preset } = useChatting()
    const { details = {} } = preset
    const { snaps = [] } = details

    const { onChange, media } = props

    const storySnap = snaps?.filter(i => i.purpose === PurposeType.STORY) ?? []

    return (
        <>
            <Dialog>
                <DialogTrigger asChild>
                    <button className="flex flex-col border border-slate-800 bg-slate-950 rounded-md">
                        <div className="h-[120px] w-[67.5px]  rounded-md rounded-b-none flex justify-center items-center">
                            {media ? (
                                <img
                                    alt={`snap`}
                                    className={cn(
                                        'w-full h-full object-cover rounded rounded-b-none'
                                    )}
                                    src={getSnapSource(media)}
                                />
                            ) : (
                                <Image />
                            )}
                        </div>
                        <Button
                            variant="secondary"
                            className="bg-slate-800 text-white hover:bg-slate-800/90 w-full rounded-t-none h-6 px-0 rounded-b"
                            onClick={() => {}}
                        >
                            <span className="text-xs">Media</span>
                        </Button>
                    </button>
                </DialogTrigger>
                <DialogContent
                    className="w-[320px] max-h-[90vh] !left-[unset] right-[20px] translate-x-0 overflow-auto p-2"
                    aria-describedby="select-media"
                >
                    <DialogTitle className="text-xl font-semibold text-ce-gray-400">
                        Select media
                    </DialogTitle>
                    <VisuallyHidden.Root>
                        <DialogDescription>Select media</DialogDescription>
                    </VisuallyHidden.Root>
                    <Separator />

                    <div className="flex flex-wrap gap-2">
                        {storySnap.length > 0 ? (
                            storySnap.map(i => (
                                <div
                                    className="relative rounded border border-slate-800"
                                    key={i.id}
                                >
                                    <Checkbox
                                        id={i.id}
                                        className="absolute top-2 left-2"
                                        checked={media === i.snapUrl}
                                        onCheckedChange={checked => {
                                            onChange(checked ? i.snapUrl : '')
                                        }}
                                    />
                                    <Label htmlFor={i.id}>
                                        <SnapPreview src={getSnapSource(i.snapUrl)} className="" />
                                    </Label>
                                </div>
                            ))
                        ) : (
                            <div>No story snaps added</div>
                        )}
                    </div>
                    <DialogFooter className="absolute h-0 w-0 -z-50 opacity-0">
                        Save changes
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </>
    )
}

export default SelectStoryImage
