import * as React from 'react'
import { observer } from 'mobx-react-lite'
import { configure } from 'mobx'
import { OwnerDetailType, UserInfoType } from '@/lib/types/user.type'
import { LocalStorage } from '@/lib/chrome-storage'
import { ServiceMessageName, USER_FRIENDS_GET_SUCCESSFULLY } from '@/lib/constants'
import * as API from '@/scripts/api'
import { callApiWithRetries, sleep } from '@/lib/common'
import { authStore } from '@/scripts/store'
import { cloneDeep } from 'lodash'

type addsOverlayProps = {
    children: React.ReactNode
}

type userMainInfoType = {
    data: UserInfoType
    attemptFetch: boolean
}

type AddsOverlayType = {
    ownerDisabledAdds: OwnerDetailType['disabled_adds']
    userMainInfo: UserInfoType
    toggleDisableAdd: (username: string) => void
    loadingDisabledAdds: boolean
    disableAllAdds: boolean
    setRefetchDisableAdds: React.Dispatch<React.SetStateAction<boolean>>
    setLoadingDisabledAdds: React.Dispatch<React.SetStateAction<boolean>>
    setDisableAllAdds: React.Dispatch<React.SetStateAction<boolean>>
}

const AddsOverlayContext = React.createContext<AddsOverlayType>({} as AddsOverlayType)

configure({
    enforceActions: 'never'
})

export const AddsOverlayProvider = observer(({ children }: addsOverlayProps) => {
    const [userMainInfo, setUserMainInfo] = React.useState<userMainInfoType>({
        attemptFetch: false,
        data: null
    })
    const [disableAllAdds, setDisableAllAdds] = React.useState(false)
    const [loadingDisabledAdds, setLoadingDisabledAdds] = React.useState(true)
    const [refetchDisableAdds, setRefetchDisableAdds] = React.useState(false)
    const [ownerDisabledAdds, setOwnerDisabledAdds] = React.useState<
        OwnerDetailType['disabled_adds']
    >([] as OwnerDetailType['disabled_adds'])

    const host = window.location.host
    const isUserLoggedIn = host === 'web.snapchat.com'

    const handleGetLoggedInUser = async () => {
        if (isUserLoggedIn) {
            do {
                const isUserGetSuccessfully = await LocalStorage.getItem(
                    USER_FRIENDS_GET_SUCCESSFULLY
                )
                await sleep(1000)
                if (isUserGetSuccessfully) {
                    const res = await API.getLoggedInUser()
                    if (res.status) {
                        setUserMainInfo({ attemptFetch: true, data: res.data.snapchatters[0] })
                        return
                    }
                    break
                }
            } while (true)
            window.location.reload()
        }
        setUserMainInfo({ attemptFetch: true, data: null })
    }

    React.useEffect(() => {
        handleGetLoggedInUser()
    }, [])

    React.useEffect(() => {
        if (userMainInfo.attemptFetch && isUserLoggedIn && !userMainInfo.data) {
            window.location.reload()
        }
    }, [userMainInfo])

    const toggleDisableAdd = React.useCallback((username: string) => {
        setOwnerDisabledAdds(prev => {
            const usernames = cloneDeep(prev)
            const index = usernames.findIndex(i => i === username)
            if (index > -1) {
                usernames.splice(index, 1)
            } else {
                usernames.push(username)
            }
            return usernames
        })
    }, [])

    const handleGetDisabledAdds = async () => {
        const apiCall = async () => await API.getOwnerProfile(userMainInfo.data.mutable_username)
        setLoadingDisabledAdds(true)
        try {
            const response = await callApiWithRetries(apiCall)

            console.log(response.data.disabled_adds)
            setOwnerDisabledAdds(response.data.disabled_adds ?? [])
        } catch (error) {
            console.error('Error while fetching owner details', error.message)
        }
        setLoadingDisabledAdds(false)
    }

    React.useEffect(() => {
        if (userMainInfo.data && authStore.isAuthenticated) {
            handleGetDisabledAdds()
        }
    }, [userMainInfo, authStore.isAuthenticated])

    React.useEffect(() => {
        if (refetchDisableAdds) {
            handleGetDisabledAdds()
            setRefetchDisableAdds(false)
        }
    }, [refetchDisableAdds])

    const value = {
        ownerDisabledAdds: ownerDisabledAdds,
        userMainInfo: userMainInfo.data,
        toggleDisableAdd,
        loadingDisabledAdds,
        disableAllAdds,
        setRefetchDisableAdds,
        setLoadingDisabledAdds,
        setDisableAllAdds
    } as AddsOverlayType

    return <AddsOverlayContext.Provider value={value}>{children}</AddsOverlayContext.Provider>
})

export const useAddsOverlay = () => {
    const context = React.useContext(AddsOverlayContext)

    if (context === undefined) throw new Error('useAddsOverlay must be used within a AddsOverlay')

    return context
}
