import SpecificMediaSelector from '@/components/content/live-snap-source/specific-media-selector'
import CTAInput from '@/components/shared/cta-input'
import SectionHeader from '@/components/shared/section-header'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { Switch } from '@/components/ui/switch'
import { PresetCtaStaticMessageType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import React from 'react'

const FinalStaticMessage = () => {
    const { preset, setPreset } = useChatting()

    const { details = {} } = preset
    const { cta = {} } = details
    const { finalStaticMessage = {} as PresetCtaStaticMessageType } = cta
    const { bDefaultStaticMessage, message, snapIds = [] } = finalStaticMessage

    const updateCTAStaticMessage = (
        key: keyof PresetCtaStaticMessageType,
        value: string | boolean | string[]
    ) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                cta: {
                    ...(prev.details?.cta ?? {}),
                    finalStaticMessage: {
                        ...(prev.details?.cta?.finalStaticMessage ?? {}),
                        [key]: value
                    } as PresetCtaStaticMessageType
                }
            }
        }))
    }

    return (
        <div className="bg-primary rounded-md">
            <SectionHeader
                label="Final Static Message"
                info={
                    <>
                        <p>The static message you will be sending to adds</p>
                        <p className="mt-8">{`Example: im not gonna go back and forth here anymore like this if you actually wanna make content with me message me on my OF | {link}`}</p>
                    </>
                }
            />
            <Separator />

            <div className="flex flex-col gap-5 p-3">
                <CTAInput
                    label="Message"
                    placeholder="Add | for line break"
                    name="message"
                    onChange={e => {
                        updateCTAStaticMessage('message', e.target.value)
                    }}
                    value={message}
                    linkPlaceholder="{link}"
                    disabled={bDefaultStaticMessage}
                />

                <div className="flex items-center justify-between">
                    <Label htmlFor="defaultCta">Default Static Message</Label>
                    <Switch
                        id="defaultCta"
                        checked={bDefaultStaticMessage}
                        onCheckedChange={value => {
                            updateCTAStaticMessage('bDefaultStaticMessage', value)
                        }}
                    />
                </div>

                <SpecificMediaSelector
                    specificSnapIdsKey="snapIds"
                    specificSnapId={snapIds}
                    onChange={(key, value) => {
                        updateCTAStaticMessage(key as keyof PresetCtaStaticMessageType, value)
                    }}
                />
            </div>
        </div>
    )
}

export default FinalStaticMessage
