import React, { useEffect, useState } from 'react'
import Model from './model'
import Presets from './presets'
import PresetFolder from './preset-folder'
import { useChatting } from '@/provider/chatting-provider'
import { Switch } from '@/components/ui/switch'
import { ERROR_MSG, SB_BOT_ACTIVE, ServiceMessageName, TELEGRAM_CONTACT } from '@/lib/constants'
import { LocalStorage } from '@/lib/chrome-storage'
import CEAlert from '@/components/shared/ce-alert'
import { authStore } from '@/scripts/store'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import ContentBody from '../..'
import { observer } from 'mobx-react-lite'

type propType = React.ComponentProps<typeof ContentBody>

const Header = observer((props: propType) => {
    const { mediaEnabled, isEnglishLanguage } = props
    const host = window.location.host
    const [botActiveChecked, setBotActiveChecked] = useState(false)
    const [forceErrors, setForceErros] = useState('')
    const {
        botRunning,
        selectedFolder,
        selectedModel,
        inCompletePresetSection,
        selectedPreset,
        userMainInfo,
        ownerDetails,
        setBotRunning
    } = useChatting()
    const isUserLoggedIn = host === 'web.snapchat.com'

    useEffect(() => {
        const onBotIfActive = async () => {
            const wasBotActive = await LocalStorage.getItem(SB_BOT_ACTIVE)
            if (
                wasBotActive &&
                mediaEnabled &&
                isUserLoggedIn &&
                userMainInfo.attemptFetch &&
                authStore.licenseInformation.quota > 0 &&
                isEnglishLanguage
            ) {
                setBotRunning(true)
            } else {
                setBotRunning(false)
            }
            setBotActiveChecked(true)
        }
        if (
            inCompletePresetSection.length === 0 &&
            !botActiveChecked &&
            authStore.licenseInformation &&
            userMainInfo.attemptFetch
        ) {
            onBotIfActive()
        }

        if (botActiveChecked && inCompletePresetSection.length > 0 && botRunning) {
            setBotRunning(false)
        }
        if (!mediaEnabled && botActiveChecked && botRunning) {
            setBotRunning(false)
        }

        if (!isEnglishLanguage && botActiveChecked && botRunning) {
            setBotRunning(false)
        }
        if (botActiveChecked && botRunning && !(authStore.licenseInformation?.quota > 0)) {
            setBotRunning(false)
        }
    }, [
        inCompletePresetSection,
        mediaEnabled,
        isUserLoggedIn,
        userMainInfo,
        isEnglishLanguage,
        authStore.licenseInformation
    ])

    useEffect(() => {
        const messageListener = (request, sender, sendResponse) => {
            if (request.action === ServiceMessageName.ForceOffBot) {
                const data = request.data
                setBotRunning(false)
                LocalStorage.setItem(SB_BOT_ACTIVE, false)
                if (data.message === ERROR_MSG.TOP_UP_CONVERSATION_QUOTA) {
                    authStore.validateLicenseKey(authStore.getAPIKey())
                }
                setForceErros(data.message)
            }
        }

        chrome.runtime.onMessage.addListener(messageListener)
        return () => chrome.runtime.onMessage.removeListener(messageListener)
    }, [])

    useEffect(() => {
        if (authStore?.licenseInformation) {
            if (authStore.licenseInformation.quota <= 0) {
                setForceErros(ERROR_MSG.TOP_UP_CONVERSATION_QUOTA)
            }
        }
    }, [authStore.licenseInformation])

    return (
        <div className="flex flex-col gap-3 mb-3">
            <div className="flex gap-4 items-center">
                <Switch
                    disabled={
                        inCompletePresetSection.length > 0 ||
                        !mediaEnabled ||
                        !isUserLoggedIn ||
                        !isEnglishLanguage ||
                        Object.keys(ownerDetails).length === 0 ||
                        authStore.licenseInformation.quota <= 0
                    }
                    onCheckedChange={async value => {
                        await LocalStorage.setItem(SB_BOT_ACTIVE, value)
                        setBotRunning(value)
                    }}
                    checked={botRunning}
                />
            </div>
            {!!forceErrors && <CEAlert label={forceErrors} size="sm" />}
            {!mediaEnabled && <CEAlert label="Enable webcam permissions" size="sm" />}
            {!isEnglishLanguage && (
                <CEAlert label="Switch language to english in settings" size="sm" />
            )}

            <div className="flex items-center justify-between mt-2 mb-3">
                <div className="flex gap-1 items-center text-white text-sm font-medium">
                    {authStore.licenseInformation ? (
                        <span>{authStore.licenseInformation.quota}</span>
                    ) : (
                        <Skeleton className="w-10 h-4" />
                    )}
                    <span>conversations left</span>
                </div>
                <Button
                    size="lg"
                    variant="secondary"
                    onClick={() => {
                        window.open(TELEGRAM_CONTACT)
                    }}
                >
                    Get More
                </Button>
            </div>

            {!selectedPreset && !selectedModel ? (
                <CEAlert
                    label="You must enter a model to begin"
                    alertDescriptionProp={{ className: 'text-base' }}
                    size="default"
                />
            ) : null}

            <Model />
            {selectedModel && <PresetFolder />}
            {selectedFolder && <Presets />}
        </div>
    )
})

export default Header
