import { Input } from '@/components/ui/input'
import { getUniqueID } from '@/lib/common'
import { allowedImageType, compressImage, readAsDataURLAsync } from '@/lib/image-management'
import { ImageType } from '@/lib/types/preset.type'
import React, { useRef } from 'react'

type propType = {
    children: React.ReactNode
    onProcessImage: (images: ImageType[]) => void
} & React.ComponentProps<typeof Input>

const UploadFile = (props: propType) => {
    const ref = useRef<HTMLInputElement>(null)
    const { children, onProcessImage, ...rest } = props

    const onChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const images: ImageType[] = []
        if (e.target.files?.length > 0) {
            for (const file of e.target.files) {
                try {
                    const compressedFile = (await compressImage(file)) as File
                    const base64 = (await readAsDataURLAsync(compressedFile as File)) as string

                    images.push({
                        base64,
                        file: compressedFile,
                        id: getUniqueID()
                    })
                } catch (err) {
                    console.error('Error while processing file', err?.message)
                }
            }
        } else {
            console.error('No image selected')
        }
        onProcessImage(images)
        ref.current.value = ''
    }

    return (
        <div className="relative">
            {children}
            <Input
                type="file"
                accept={allowedImageType.toString()}
                className="absolute inset-0 opacity-0 z-50 h-full"
                onChange={onChange}
                multiple
                {...rest}
                ref={ref}
            />
        </div>
    )
}

export default UploadFile
