import * as React from 'react'
import { Label } from '../ui/label'
import {
    Select,
    SelectContent,
    SelectGroup,
    SelectItem,
    SelectLabel,
    SelectTrigger,
    SelectValue
} from '@/components/ui/select'
import Help from './help'

type propType = {
    label?: string
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    suffix?: React.ReactNode
    prefix?: React.ReactNode
    options: {
        label: React.ReactNode
        value: string
    }[]
    placeholder?: string
    triggerProps?: React.ComponentProps<typeof SelectTrigger>
} & React.ComponentProps<typeof Select>

function CESelect(props: propType) {

    const {
        error,
        info,
        label,
        htmlFor,
        suffix,
        prefix,
        options,
        placeholder,
        triggerProps = { className: 'w-full', size: 'lg' },
        ...rest
    } = props
    return (
        <div className="flex flex-col flex-1">
            {label ? (
                <div className="flex gap-1 mb-2.5 items-center">
                    <Label htmlFor={htmlFor}>{label}</Label>
                    {info && <Help label={info} />}
                </div>
            ) : null}
            <Select {...rest} >
                <SelectTrigger {...triggerProps} >
                    <SelectValue placeholder={<span className='text-slate-400'>Select {placeholder ?? '...'}</span>} />
                </SelectTrigger> 
                <SelectContent>
                    <SelectGroup>
                        {options.length > 0 ? (
                            <>
                                {options.map(i => (
                                    <SelectItem
                                        value={i.value}
                                    >
                                        {i.label}
                                    </SelectItem>
                                ))}
                            </>
                        ) : (
                            <SelectLabel>No option available</SelectLabel>
                        )}
                    </SelectGroup>
                </SelectContent>
            </Select>
            {error && <p className="text-venetian-red text-sm mt-0.5">{error}</p>}
        </div>
    )
}

export default CESelect
