import React, { useState } from 'react'

import {
    Tooltip as ShadTooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger
} from '@/components/ui/tooltip'
import { MessageSquareMore, MessageSquareOff } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import { Button } from '@/components/ui/button'
import { chattingStatusType } from '@/lib/types/chatting-overlay.type'
import * as API from '@/scripts/api'
import { UserInfoType } from '@/lib/types/user.type'
import Spinner from '@/components/shared/spinner'
import { formatCapitalizeString } from '@/lib/common'
import { Switch } from '@/components/ui/switch'
import { cn } from '@/lib/utils'

type propType = {
    status: chattingStatusType
    userMainInfo: UserInfoType
    toggleIncludeInAnalytics: (uuid: string) => void
    markUserAsConverted: (uuid: string) => void
    togglePauseChatting: (uuid: string) => void
    uuid: string
    userDisplayName: string
}

const StatePopover = React.memo((props: propType) => {
    const {
        uuid,
        status,
        userMainInfo,
        toggleIncludeInAnalytics,
        markUserAsConverted,
        togglePauseChatting,
        userDisplayName
    } = props

    const [loading, setLoading] = useState(false)
    const [togglePausingChat, setTogglePausingChat] = useState(false)
    const [converting, setConverting] = useState(false)

    const statusColorCode = {
        multiPhase: '#FD8BF9',
        ghosting: '#10ADFF',
        converted: '#6FD546',
        mainPhase: '#999999',
        completed: '#FD9207',
        duplicate: '#F43A56'
    }

    const {
        ruid,
        chat_status,
        is_conversed,
        include_analytic_converted,
        ghost_message_count,
        paused_chatting = false
    } = status || {}

    const getStatus = () => {
        if (is_conversed) {
            return 'Converted'
        }
        if (chat_status?.toLowerCase().includes('main') || ghost_message_count === 1) {
            return 'Main Phase'
        }

        return formatCapitalizeString(chat_status)
    }

    const getColor = () => {
        if (is_conversed) {
            return statusColorCode.converted
        }
        if (chat_status.toLowerCase().includes('duplicate')) {
            return statusColorCode.duplicate
        }
        if (chat_status.toLowerCase().includes('complete')) {
            return statusColorCode.completed
        }
        if (chat_status.toLowerCase().includes('main') || ghost_message_count === 1) {
            return statusColorCode.mainPhase
        }
        if (chat_status.toLowerCase().includes('ghosting')) {
            return statusColorCode.ghosting
        }
        return statusColorCode.multiPhase
    }

    const handleToggleIncludeAndExclude = async () => {
        setLoading(true)
        const res = await API.toggleIncludeConvertedForAnalytic({
            request_user_id: ruid,
            owner_id: userMainInfo.mutable_username
        })
        if (res.status) {
            toggleIncludeInAnalytics(ruid)
        } else {
            console.error('Something went wrong while toggling include and exclude')
        }
        setLoading(false)
    }

    const handleTogglePausingChatting = async () => {
        setTogglePausingChat(true)
        const res = await API.togglePauseChatting({
            request_user_id: uuid,
            owner_id: userMainInfo.mutable_username,
            request_username: userDisplayName
        })
        if (res.status) {
            togglePauseChatting(uuid)
        } else {
            console.error('Something went wrong while toggling include and exclude')
        }
        setTogglePausingChat(false)
    }

    const handleMarkAsConverted = async () => {
        setConverting(true)
        const res = await API.markAsConverted({
            request_user_id_list: [ruid],
            owner_id: userMainInfo.mutable_username
        })
        if (res.status) {
            markUserAsConverted(ruid)
        } else {
            console.error('Something went wrong while mark as converted')
        }
        setConverting(false)
    }

    if (!status) {
        return (
            <TooltipProvider>
                <ShadTooltip delayDuration={50}>
                    <TooltipTrigger asChild>
                        <button
                            style={{
                                borderRadius: '50%',
                                border: 'none',
                                height: '28px',
                                width: '28px',
                                backgroundColor: statusColorCode.mainPhase,
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center'
                            }}
                            onClick={e => e.stopPropagation()}
                        >
                            <img
                                src={chrome.runtime.getURL('./assets/svg/question.svg')}
                                className="cursor-pointer"
                                alt="question-mark"
                                style={{ height: '16px' }}
                            />
                        </button>
                    </TooltipTrigger>
                    <TooltipContent className="w-96 py-3">
                        <div className="grid gap-4">
                            <div className="space-y-2">
                                <div className="flex justify-between">
                                    <Badge
                                        style={{ backgroundColor: statusColorCode.mainPhase }}
                                        className="!text-white text-base rounded-md capitalize"
                                    >
                                        Main
                                    </Badge>
                                    <div className="flex justify-center gap-2">
                                        <Button
                                            variant="link"
                                            onClick={handleTogglePausingChatting}
                                            className="!p-0 h-6"
                                        >
                                            <MessageSquareMore
                                                size={20}
                                                className={cn('text-blue-primary')}
                                            />
                                            {togglePausingChat && <Spinner />}
                                        </Button>
                                    </div>
                                </div>
                                <p className="text-sm text-muted-foreground !mt-8">User ID:</p>
                                <p className="text-base text-white font-medium">{uuid}</p>
                                <Separator orientation="horizontal" className="bg-white" />
                                <div className="flex gap-2">
                                    <Button
                                        className="bg-[#F43A56] hover:bg-[#F43A56]/90"
                                        size="sm"
                                        disabled={true}
                                    >
                                        Exclude
                                        {loading && <Spinner />}
                                    </Button>

                                    <Button
                                        size="sm"
                                        className="flex-1 bg-[#6FD546] hover:bg-[#6FD546]/90"
                                        disabled={true}
                                    >
                                        Mark converted
                                    </Button>
                                </div>
                            </div>
                        </div>
                    </TooltipContent>
                </ShadTooltip>
            </TooltipProvider>
        )
    }

    return (
        <TooltipProvider>
            <ShadTooltip delayDuration={50}>
                <TooltipTrigger asChild>
                    <button
                        style={{
                            borderRadius: '50%',
                            border: 'none',
                            height: '28px',
                            width: '28px',
                            backgroundColor: getColor(),
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center'
                        }}
                        onClick={e => e.stopPropagation()}
                    >
                        {is_conversed ? (
                            <img
                                src={chrome.runtime.getURL('./assets/svg/dollar.svg')}
                                className="cursor-pointer"
                                alt="dollar-mark"
                                style={{ height: '16px' }}
                            />
                        ) : (
                            <img
                                src={chrome.runtime.getURL('./assets/svg/question.svg')}
                                className="cursor-pointer"
                                alt="question-mark"
                                style={{ height: '16px' }}
                            />
                        )}
                    </button>
                </TooltipTrigger>
                <TooltipContent className="w-96 py-3">
                    <div className="grid gap-4">
                        <div className="space-y-2">
                            <div className="flex justify-between">
                                <Badge
                                    style={{ backgroundColor: getColor() }}
                                    className="!text-white text-base rounded-md capitalize"
                                >
                                    {getStatus()}
                                </Badge>
                                <div className="flex justify-center gap-2">
                                    <Button
                                        variant="link"
                                        onClick={handleTogglePausingChatting}
                                        className="!p-0 h-6"
                                        disabled={
                                            is_conversed ||
                                            converting ||
                                            chat_status === 'duplicate'
                                        }
                                    >
                                        {!paused_chatting ? (
                                            <MessageSquareMore
                                                size={20}
                                                className={cn('text-blue-primary')}
                                            />
                                        ) : (
                                            <MessageSquareOff
                                                size={20}
                                                className={cn('text-[#F43A56]')}
                                            />
                                        )}
                                        {togglePausingChat && <Spinner />}
                                    </Button>
                                </div>
                            </div>
                            <p className="text-sm text-muted-foreground !mt-8">User ID:</p>
                            <p className="text-base text-white font-medium">{ruid}</p>
                            <Separator orientation="horizontal" className="bg-white" />
                            <div className="flex gap-2">
                                {include_analytic_converted ? (
                                    <Button
                                        className="bg-[#F43A56] hover:bg-[#F43A56]/90"
                                        size="sm"
                                        onClick={handleToggleIncludeAndExclude}
                                        disabled={loading || chat_status === 'duplicate'}
                                    >
                                        Exclude
                                        {loading && <Spinner />}
                                    </Button>
                                ) : (
                                    <Button
                                        size="sm"
                                        onClick={handleToggleIncludeAndExclude}
                                        disabled={loading || chat_status === 'duplicate'}
                                    >
                                        Include{loading && <Spinner />}
                                    </Button>
                                )}
                                <Button
                                    size="sm"
                                    className="flex-1 bg-[#6FD546] hover:bg-[#6FD546]/90"
                                    disabled={
                                        is_conversed || converting || chat_status === 'duplicate'
                                    }
                                    onClick={handleMarkAsConverted}
                                >
                                    Mark converted{converting && <Spinner />}
                                </Button>
                            </div>
                        </div>
                    </div>
                </TooltipContent>
            </ShadTooltip>
        </TooltipProvider>
    )
})

export default StatePopover
