import { chattingStyle, PurposeType } from '@/lib/constants'
import { DEFAULT_CTA } from '@/lib/defaultPresetsValue'
import { PresetDetailType } from '@/lib/types/preset.type'
import * as React from 'react'

type getStartedProviderProps = {
    children: React.ReactNode
}

const defaultStarterContext = {
    title: '',
    name: '',
    age: '',
    cta: DEFAULT_CTA,
    snaps: [],
    chattingStyle: chattingStyle[0].value
} as PresetDetailType & { title: string }

type licenseKeyType = {
    isValid: boolean
    key: string
}

type GetStartedStateType = {
    preset: PresetDetailType & { title: string }
    setPreset: React.Dispatch<React.SetStateAction<PresetDetailType & { title: string }>>
    licenseKey: licenseKeyType
    setLicenseKey: React.Dispatch<React.SetStateAction<licenseKeyType>>
    snaps: snapsType[]
    setSnaps: React.Dispatch<React.SetStateAction<snapsType[]>>
}

const GetStartedProviderContext = React.createContext<GetStartedStateType>(
    {} as GetStartedStateType
)

export type snapsType = {
    type: PurposeType
    file: File
    id: string
    base64: string
    description: string
}

export function GetStartedProvider({ children }: getStartedProviderProps) {
    const [preset, setPreset] = React.useState(defaultStarterContext)
    const [licenseKey, setLicenseKey] = React.useState({
        isValid: false,
        key: ''
    } as licenseKeyType)
    const [snaps, setSnaps] = React.useState<snapsType[]>([])

    const value = {
        preset,
        setPreset,
        licenseKey,
        setLicenseKey,
        setSnaps,
        snaps
    }

    return (
        <GetStartedProviderContext.Provider value={value}>
            {children}
        </GetStartedProviderContext.Provider>
    )
}

export const useGetStarted = () => {
    const context = React.useContext(GetStartedProviderContext)

    if (context === undefined) throw new Error('useTheme must be used within a ThemeProvider')

    return context
}
