const Droppable = () => {
    return (
        <div className="relative w-full h-36 bg-slate-950 border-2 border-slate-800 rounded border-dashed flex flex-col items-center justify-center cursor-pointer">
            <div className="w-12 h-12 bg-blue rounded-full flex items-center justify-center">
                <svg
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                >
                    <path d="M9 16h6v-6h4l-7-7-7 7h4zm-4 2h14v2H5z" fill="white" />
                </svg>
            </div>
            <p className="text-white mt-2">Photo ratio: 9:16</p>
            <p className="text-white">PNG or JPEG</p>
        </div>
    )
}

const Snaps = () => {
    const { snaps, setSnaps } = useGetStarted()

    const MainSnaps = snaps.filter(i => i.type === PurposeType.MAIN)

    const sexySnaps = snaps.filter(i => i.type === PurposeType.SEXY)

    const handleDeleteSnap = (id: string) => {
        setSnaps(prev => prev.filter(i => i.id !== id))
    }

    const handleUpdateDescription = (id: string, value: string) => {
        setSnaps(prev => {
            const snaps = cloneDeep(prev)
            const snapIndex = snaps.findIndex(i => i.id === id)
            const updatedSnap = {
                ...snaps[snapIndex],
                description: value
            }

            snaps.splice(snapIndex, 1, updatedSnap)

            return snaps
        })
    }

    return (
        <>
            <div>
                <p className="text-center text-white text-lg font-large">Upload Photos</p>
                <div className="text-center">
                    <span className="text-blue-primary">Recommended: </span>
                    <span className="text-white">20 Casual 20 Sexy</span>
                </div>
            </div>
            <CasualSnapsExample />
            <SexySnapsExample />

            {snaps.length < 4 && (
                <Alert variant="destructive">
                    <AlertDescription>
                        <ul className="list-disc pl-4">
                            <li>Minimum 4 snaps are required combined of Casual and Sexy snaps.</li>
                        </ul>
                    </AlertDescription>
                </Alert>
            )}

            <div className="flex flex-col gap-2.5">
                <Label>Casual upload</Label>
                {MainSnaps.length > 0 ? (
                    <ScrollArea className="whitespace-nowrap rounded-md">
                        <div className="flex w-max space-x-2 py-2">
                            {MainSnaps.map(i => (
                                <div
                                    className="min-w-[108px] flex flex-col border rounded border-slate-800"
                                    key={i.id}
                                >
                                    <Button
                                        variant="destructive"
                                        className="h-6 w-full rounded-t rounded-b-none"
                                        onClick={() => {
                                            handleDeleteSnap(i.id)
                                        }}
                                    >
                                        <Trash2 size={16} />
                                    </Button>
                                    <SnapPreview src={i.base64} className="rounded-none" />
                                    <CEInput
                                        value={i.description}
                                        onChange={e => {
                                            handleUpdateDescription(i.id, e.target.value)
                                        }}
                                        placeholder="Description"
                                        size="sm"
                                        className={cn(
                                            'w-[108px] mt-1',
                                            !i.description?.trim()
                                                ? 'border-venetian-red focus-visible:ring-venetian-red'
                                                : ''
                                        )}
                                    />
                                </div>
                            ))}
                        </div>
                        <ScrollBar orientation="horizontal" />
                    </ScrollArea>
                ) : null}
                <UploadFile
                    onProcessImage={images => {
                        setSnaps(prev => [
                            ...prev,
                            ...images.map(i => ({ ...i, description: '', type: PurposeType.MAIN }))
                        ])
                    }}
                >
                    <Droppable />
                </UploadFile>
            </div>

            <div className="flex flex-col gap-2.5">
                <Label>Sexy upload</Label>
                {sexySnaps.length > 0 ? (
                    <ScrollArea className="whitespace-nowrap rounded-md">
                        <div className="flex w-max space-x-2 py-2">
                            {sexySnaps.map(i => (
                                <div
                                    className="min-w-[108px] flex flex-col border rounded border-slate-800"
                                    key={i.id}
                                >
                                    <Button
                                        variant="destructive"
                                        className="h-6 w-full rounded-t rounded-b-none"
                                        onClick={() => {
                                            handleDeleteSnap(i.id)
                                        }}
                                    >
                                        <Trash2 size={16} />
                                    </Button>
                                    <SnapPreview src={i.base64} className="rounded-none" />
                                    <CEInput
                                        value={i.description}
                                        onChange={e => {
                                            handleUpdateDescription(i.id, e.target.value)
                                        }}
                                        placeholder="Description"
                                        size="sm"
                                        className={cn(
                                            'w-[108px] mt-1',
                                            !i.description?.trim()
                                                ? 'border-venetian-red focus-visible:ring-venetian-red'
                                                : ''
                                        )}
                                    />
                                </div>
                            ))}
                        </div>
                        <ScrollBar orientation="horizontal" />
                    </ScrollArea>
                ) : null}
                <UploadFile
                    onProcessImage={images => {
                        setSnaps(prev => [
                            ...prev,
                            ...images.map(i => ({ ...i, description: '', type: PurposeType.SEXY }))
                        ])
                    }}
                >
                    <Droppable />
                </UploadFile>
            </div>
        </>
    )
}

export default Snaps
