import CreatableSelect from '@/components/shared/creatable-select'
import { Button } from '@/components/ui/button'
import { CommandGroup, CommandItem } from '@/components/ui/command'
import { PresetType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import { Copy, FolderClosed, Trash2 } from 'lucide-react'
import React, { useMemo, useState } from 'react'
import { cloneDeep } from 'lodash'
import { matchesString } from '@/lib/common'
import { AddIcon } from '@/assets/icons'
import * as API from '@/scripts/api'
import { DEFAULT_PRESET } from '@/lib/defaultPresetsValue'
import { cn } from '@/lib/utils'
import CopyPreset from '../copy-preset'

const PresetFolder = () => {
    const {
        modelsPresets,
        modelsPresetFolder,
        selectedModel,
        selectedFolder,
        setSelectedFolder,
        selectedPreset,
        setSelectedPreset,
        getModelsPresetList
    } = useChatting()

    const [loading, setLoading] = useState(false)
    const [copyPreset, setCopyPreset] = useState<{
        preset_id: number
        open: boolean
    }>({
        preset_id: null,
        open: false
    })

    const [toBeDeletedItem, setToBeDeletedItem] = useState<
        | {
              type: 'folder' | 'preset'
              id: number
          }
        | undefined
    >()
    // memoized to be deleted folder
    const toBeDeletedFolder = useMemo(() => {
        if (toBeDeletedItem && toBeDeletedItem.type === 'folder') {
            return modelsPresetFolder.find(i => i.id === toBeDeletedItem.id)
        }
        return undefined
    }, [toBeDeletedItem])
    // memoized to be deleted preset
    const toBeDeletedPreset = useMemo(() => {
        if (toBeDeletedItem && toBeDeletedItem.type === 'preset') {
            return modelsPresets.find(i => i.id === toBeDeletedItem.id)
        }
        return undefined
    }, [toBeDeletedItem])
    // memoized delete modal title
    const deleteModalTitle = useMemo(() => {
        if (toBeDeletedItem) {
            if (toBeDeletedItem.type === 'folder') {
                return `Delete folder`
            } else if (toBeDeletedItem.type === 'preset') {
                return `Delete preset`
            }
        }
        return undefined
    }, [toBeDeletedItem])
    // memoized delete modal description
    const deleteModalDescription = useMemo(() => {
        if (toBeDeletedItem) {
            if (toBeDeletedItem.type === 'folder') {
                return `Are you sure you want to delete folder "${toBeDeletedFolder?.title}"?`
            } else if (toBeDeletedItem.type === 'preset') {
                return `Are you sure you want to delete preset "${toBeDeletedPreset?.title}"?`
            }
        }
        return undefined
    }, [toBeDeletedItem, toBeDeletedFolder, toBeDeletedPreset])

    const selectedPresetOption = modelsPresets.find(i => i.id === selectedPreset)
    const selectedFolderOption = modelsPresetFolder.find(i => i.id === selectedFolder)

    const handleCreatePreset = async (presetTitle: string) => {
        setLoading(true)
        const response = await API.createPreset({
            title: presetTitle,
            model_id: selectedModel,
            parent_id: null,
            item_type: 'preset',
            detail: DEFAULT_PRESET
        })
        if (response.status) {
            await getModelsPresetList(response.data.id, null)
        } else {
            console.log('Error while creating preset', response.message)
        }
        setLoading(false)
    }

    const handleCreateFolder = async (folderTitle: string) => {
        setLoading(true)
        const response = await API.createPreset({
            title: folderTitle,
            model_id: selectedModel,
            parent_id: null,
            item_type: 'folder',
            detail: DEFAULT_PRESET
        })
        if (response.status) {
            await getModelsPresetList(null, response.data.id)
        } else {
            console.log('Error while creating preset folder', response.message)
        }
        setLoading(false)
    }

    const handleDeletePreset = async (presetId: number) => {
        setLoading(true)
        const response = await API.deletePreset([presetId])
        if (response.status) {
            if (presetId === selectedPreset) {
                setSelectedPreset(null)
                await getModelsPresetList()
            } else {
                await getModelsPresetList(selectedPreset)
            }
        } else {
            console.log('Error while deleting preset', response.message)
        }
        setLoading(false)
    }

    const handleDeleteFolder = async (folderId: number) => {
        setLoading(true)
        const folderPresets = modelsPresets
            .filter(i => i.parent_id === selectedFolder)
            .map(i => i.id)
        const response = await API.deletePreset([folderId, ...folderPresets])
        if (response.status) {
            if (folderId === selectedFolder) {
                setSelectedFolder(null)
                await getModelsPresetList()
            } else {
                await getModelsPresetList(selectedPreset, selectedFolder)
            }
        } else {
            console.log('Error while deleting model', response.message)
        }
        setLoading(false)
    }

    return (
        <>
            <CreatableSelect
                loading={loading}
                placeholder="Type in a preset..."
                value={
                    selectedFolderOption || selectedPresetOption
                        ? {
                              id: String(selectedFolderOption?.id || selectedPresetOption.id),
                              title: selectedFolderOption?.title || selectedPresetOption.title
                          }
                        : undefined
                }
                onClear={() => {
                    setSelectedFolder(null)
                    setSelectedPreset(null)
                }}
                inputProps={{
                    prefix: selectedFolder ? <FolderClosed size={18} /> : <></>,
                    className: selectedFolder
                        ? 'px-8 w-full focus-visible:!ring-offset-0 focus-visible:!ring-transparent'
                        : 'pr-8 w-full focus-visible:!ring-offset-0 focus-visible:!ring-transparent'
                }}
                toBeDeletedId={toBeDeletedItem ? toBeDeletedItem.id : undefined}
                deleteModalTitle={deleteModalTitle}
                deleteModalDescription={deleteModalDescription}
                onDeleteCallback={async id => {
                    if (toBeDeletedItem.type === 'folder') {
                        await handleDeleteFolder(toBeDeletedItem.id)
                    } else {
                        await handleDeletePreset(toBeDeletedItem.id)
                    }

                    setToBeDeletedItem(undefined)
                }}
                onCancelDeleteCallback={() => setToBeDeletedItem(undefined)}
            >
                {({ searchValue }) => {
                    let filterPreset: PresetType[] = cloneDeep(
                        modelsPresets.filter(i => !i.parent_id)
                    )
                    let filterFolder: PresetType[] = cloneDeep(modelsPresetFolder)

                    if (searchValue.trim() && !selectedPreset && !selectedFolder) {
                        filterPreset = filterPreset.filter(i =>
                            matchesString(i.title.trim(), searchValue.trim())
                        )

                        filterFolder = filterFolder.filter(i =>
                            matchesString(i.title.trim(), searchValue.trim())
                        )
                    }

                    const allowCreateNewFolder =
                        filterFolder.filter(i =>
                            matchesString(i.title.trim(), searchValue.trim(), true)
                        ).length === 0 && searchValue.trim()

                    const allowCreateNewPreset =
                        filterPreset.filter(i =>
                            matchesString(i.title.trim(), searchValue.trim(), true)
                        ).length === 0 && searchValue.trim()

                    return (
                        <CommandGroup
                            className={cn(
                                [...filterFolder, ...filterPreset].length === 0 &&
                                    !allowCreateNewFolder &&
                                    !allowCreateNewPreset
                                    ? 'p-0'
                                    : ''
                            )}
                        >
                            {[...filterFolder, ...filterPreset].map(preset => (
                                <CommandItem
                                    disabled={loading}
                                    key={preset.id}
                                    value={String(preset.id)}
                                    onSelect={currentValue => {
                                        if (preset.item_type === 'folder') {
                                            setSelectedFolder(Number(currentValue))
                                        } else {
                                            setSelectedFolder(null)
                                            setSelectedPreset(Number(currentValue))
                                        }
                                    }}
                                    className="cursor-pointer"
                                >
                                    <div className="group flex justify-between items-center w-full gap-2">
                                        {preset.item_type === 'folder' ? (
                                            <FolderClosed size={18} />
                                        ) : null}
                                        <p className="text-white text-base font-semibold flex-1 truncate">
                                            {preset.title}
                                        </p>
                                        {preset.item_type !== 'folder' ? (
                                            <button
                                                disabled={loading}
                                                className="hidden group-hover:inline-block"
                                                onClick={e => {
                                                    e.stopPropagation()
                                                    setCopyPreset({
                                                        preset_id: preset.id,
                                                        open: true
                                                    })
                                                }}
                                            >
                                                <Copy size={18} />
                                            </button>
                                        ) : null}
                                        <Button
                                            disabled={loading}
                                            size="icon"
                                            variant="destructive"
                                            className="h-8 w-8"
                                            onClick={e => {
                                                e.stopPropagation()
                                                if (preset.item_type === 'folder') {
                                                    setToBeDeletedItem({
                                                        id: preset.id,
                                                        type: 'folder'
                                                    })
                                                } else {
                                                    setToBeDeletedItem({
                                                        id: preset.id,
                                                        type: 'preset'
                                                    })
                                                }
                                            }}
                                        >
                                            <Trash2 size={18} />
                                        </Button>
                                    </div>
                                </CommandItem>
                            ))}
                            {allowCreateNewFolder ? (
                                <CommandItem
                                    disabled={loading}
                                    value={String(`${searchValue}_folder`)}
                                    onSelect={currentValue => {
                                        handleCreateFolder(searchValue.trim())
                                    }}
                                    className="cursor-pointer"
                                >
                                    <div className="flex justify-between items-center w-full gap-2">
                                        <AddIcon fill="white" />
                                        <p className="text-white text-base font-semibold flex-1 truncate">
                                            Create folder '{searchValue.trim()}'
                                        </p>
                                    </div>
                                </CommandItem>
                            ) : null}

                            {allowCreateNewPreset ? (
                                <CommandItem
                                    disabled={loading}
                                    value={String(`${searchValue}_preset`)}
                                    onSelect={currentValue => {
                                        handleCreatePreset(searchValue.trim())
                                    }}
                                    className="cursor-pointer"
                                >
                                    <div className="flex justify-between items-center w-full gap-2">
                                        <AddIcon fill="white" />
                                        <p className="text-white text-base font-semibold flex-1 truncate">
                                            Create preset '{searchValue.trim()}'
                                        </p>
                                    </div>
                                </CommandItem>
                            ) : null}
                        </CommandGroup>
                    )
                }}
            </CreatableSelect>
            <CopyPreset
                preset_id={copyPreset.preset_id}
                open={copyPreset.open}
                onOpenChange={value => {
                    if (!value) {
                        setCopyPreset({
                            preset_id: null,
                            open: false
                        })
                    }
                }}
            />
        </>
    )
}

export default PresetFolder
