import { cn } from '@/lib/utils'
import * as React from 'react'

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
    wrapperClassName?: React.HTMLAttributes<HTMLDivElement>['className']
}

const CEUnderlineInput = React.forwardRef<HTMLInputElement, InputProps>(
    ({ className, type = 'text', placeholder, wrapperClassName = '', ...props }, ref) => {
        return (
            <div className={cn('ce-input-container', wrapperClassName)}>
                <input
                    placeholder={placeholder}
                    className="ce-input-field"
                    type={type}
                    ref={ref}
                    {...props}
                />
                <label htmlFor="ce-input-field" className="ce-input-label">
                    {placeholder}
                </label>
                <span className="ce-input-highlight"></span>
            </div>
        )
    }
)

export default CEUnderlineInput
