import CEButton from '@/components/shared/ce-button'
import { useChatting } from '@/provider/chatting-provider'
import { ChevronLeft } from 'lucide-react'
import React from 'react'
import { cloneDeep } from 'lodash'
import { ChattingSectionType } from '@/lib/constants'
import { DEFAULT_CTA_INFO } from '@/lib/defaultPresetsValue'

type propType = {
    children: React.ReactNode
}

const Layout = (props: propType) => {
    const { setOpenSectionStack, setPreset } = useChatting()
    const { children } = props

    const handleCleanUpCTA = () => {
        setPreset(prev => {
            const updatedPreset = cloneDeep(prev)

            const { cta } = updatedPreset.details ?? {}
            const { ctaSet } = cta ?? {}

            if (!ctaSet) {
                updatedPreset.details.cta.ctaSet = {
                    activeCta: 0,
                    sendRandomCta: false,
                    ctaInfo: [DEFAULT_CTA_INFO()]
                }
            }
            const filterCTAs = updatedPreset.details.cta.ctaSet.ctaInfo.filter(
                i => i.link.trim() && i.platform.trim()
            )

            updatedPreset.details.cta.ctaSet.ctaInfo =
                filterCTAs.length > 0 ? filterCTAs : [updatedPreset.details.cta.ctaSet.ctaInfo[0]]

            if (
                updatedPreset.details.cta.ctaSet.activeCta >=
                updatedPreset.details.cta.ctaSet.ctaInfo.length
            ) {
                updatedPreset.details.cta.ctaSet.activeCta =
                    updatedPreset.details.cta.ctaSet.ctaInfo.length - 1
            }

            return updatedPreset
        })
    }

    return (
        <div className="relative flex flex-col gap-5">
            <CEButton
                onClick={() => {
                    setOpenSectionStack(prev => {
                        const newPrev = cloneDeep(prev)
                        const lastTab = newPrev.splice(-1)
                        if (lastTab[0] === ChattingSectionType.CTA_LINKS) {
                            handleCleanUpCTA()
                        }
                        return newPrev
                    })
                }}
                prefix={<ChevronLeft size={16} />}
                className="w-fit bg-primary hover:bg-primary/80"
                size="sm"
                variant="secondary"
            >
                Back
            </CEButton>
            {children}
        </div>
    )
}

export default Layout
