import { ApiResponse } from './types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'
import { ClientInfoType } from '@/lib/types/clientInfo.type'

const updateClientInfo = async (info: ClientInfoType): Promise<ApiResponse> => {

    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/clients/info`,
                    params: {
                        method: 'PUT',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify(info)
                    }
                }
            },
            callback
        )
    })
}

export default updateClientInfo
    