import CreatableSelect from '@/components/shared/creatable-select'
import { Button } from '@/components/ui/button'
import { CommandGroup, CommandItem } from '@/components/ui/command'
import { useChatting } from '@/provider/chatting-provider'
import { Trash2 } from 'lucide-react'
import React, { useMemo, useState } from 'react'
import { cloneDeep } from 'lodash'
import { matchesString } from '@/lib/common'
import { ModelType } from '@/lib/types/model.type'
import { AddIcon } from '@/assets/icons'
import * as API from '@/scripts/api'
import { cn } from '@/lib/utils'

const Model = () => {
    const { models, selectedModel, setSelectedModel, resetModelAndPrest, getModelList } =
        useChatting()
    const [loading, setLoading] = useState(false)

    const [toBeDeletedModelId, setToBeDeletedModelId] = useState<number | undefined>()
    // memoized model response
    const toBeDeletedModel = useMemo(
        () => models.find(model => model.id === toBeDeletedModelId),
        [toBeDeletedModelId]
    )

    const selectedModelOption = models.find(i => i.id === selectedModel)

    const handleCreateModel = async (modelTitle: string) => {
        setLoading(true)
        const response = await API.createModel({ title: modelTitle })
        if (response.status) {
            resetModelAndPrest()
            await getModelList(response.data.id)
        } else {
            console.log('Error while creating model', response.message)
        }
        setLoading(false)
    }

    const handleDeleteModel = async (modelId: number) => {
        setLoading(true)
        const response = await API.deleteModel(modelId)
        if (response.status) {
            if (modelId === selectedModel) {
                resetModelAndPrest()
            }
            await getModelList()
        } else {
            console.log('Error while deleting model', response.message)
        }
        setLoading(false)
    }

    return (
        <CreatableSelect
            loading={loading}
            placeholder="Type in a model..."
            value={
                selectedModelOption
                    ? {
                          id: String(selectedModelOption.id),
                          title: selectedModelOption.title
                      }
                    : undefined
            }
            onClear={() => {
                setSelectedModel(null)
            }}
            toBeDeletedId={toBeDeletedModelId}
            deleteModalTitle={toBeDeletedModelId ? `Delete model` : ``}
            deleteModalDescription={
                toBeDeletedModelId
                    ? `Are you sure you want to delete model "${toBeDeletedModel.title}"?`
                    : ``
            }
            onDeleteCallback={async id => {
                console.log(`Model with id ${id} needs to be deleted`)

                await handleDeleteModel(id)
                setToBeDeletedModelId(undefined)
            }}
            onCancelDeleteCallback={() => setToBeDeletedModelId(undefined)}
        >
            {({ searchValue }) => {
                let filterModel: ModelType[] = cloneDeep(models)

                if (searchValue.trim() && !selectedModel) {
                    filterModel = filterModel.filter(i =>
                        matchesString(i.title.trim(), searchValue.trim())
                    )
                }

                const allowCreateNew =
                    models.filter(i => matchesString(i.title.trim(), searchValue.trim(), true))
                        .length === 0 && searchValue.trim()

                return (
                    <CommandGroup
                        className={cn(filterModel.length === 0 && !allowCreateNew ? 'p-0' : '')}
                    >
                        {filterModel.map(model => (
                            <CommandItem
                                key={model.id}
                                value={String(model.id)}
                                onSelect={currentValue => {
                                    setSelectedModel(Number(currentValue))
                                }}
                                disabled={loading}
                                className="cursor-pointer"
                            >
                                <div className="flex justify-between items-center w-full gap-2">
                                    <p className="text-white text-base font-semibold flex-1 truncate">
                                        {model.title}
                                    </p>
                                    <Button
                                        disabled={loading}
                                        size="icon"
                                        variant="destructive"
                                        className="h-8 w-8"
                                        onClick={e => {
                                            e.stopPropagation()
                                            setToBeDeletedModelId(model.id)
                                        }}
                                    >
                                        <Trash2 size={18} />
                                    </Button>
                                </div>
                            </CommandItem>
                        ))}
                        {allowCreateNew ? (
                            <CommandItem
                                disabled={loading}
                                value={String(searchValue)}
                                onSelect={() => {
                                    handleCreateModel(searchValue.trim())
                                }}
                                className="cursor-pointer"
                            >
                                <div className="flex justify-between items-center w-full gap-2">
                                    <AddIcon fill="white" />
                                    <p className="text-white text-base font-semibold flex-1 truncate">
                                        Create model '{searchValue.trim()}'
                                    </p>
                                </div>
                            </CommandItem>
                        ) : null}
                    </CommandGroup>
                )
            }}
        </CreatableSelect>
    )
}

export default Model
