import { Switch } from '@/components/ui/switch'
import React, { useEffect, useState } from 'react'
import Story from './story'
import { useChatting } from '@/provider/chatting-provider'
import * as API from '@/scripts/api'
import { StoryType } from '@/lib/types/stories.type'
import { Skeleton } from '@/components/ui/skeleton'
import dayjs from '@/lib/dayjs'
import CEInput from '@/components/shared/ce-input'
import { cloneDeep } from 'lodash'
import CEButton from '@/components/shared/ce-button'
import Spinner from '@/components/shared/spinner'
import { DEFAULT_OWNER_SETTINGS_VALUE } from '@/lib/defaultOwnerSettingValue'

export enum STORY_ACTION_LOADING {
    'COPY' = 'copy',
    'DELETE' = 'delete'
}

const Schedular = () => {
    const { userMainInfo, ownerDetails, setOwnerDetails, selectedPreset } = useChatting()
    const [stories, setStories] = useState<StoryType[]>([])
    const [loading, setLoading] = useState<{ [key: number]: STORY_ACTION_LOADING }>()
    const [loadingStories, setLoadingStories] = useState(false)
    const [loadingCreate, setLoadingCreate] = useState(false)

    const getCurrentDay = ownerDetails.first_activation_date
        ? Math.abs(dayjs(ownerDetails.first_activation_date).utc().diff(dayjs.utc(), 'days')) + 1
        : 1

    const handleCreateStory = async () => {
        setLoadingCreate(true)
        const res = await API.createStory({
            owner_id: userMainInfo.data.mutable_username,
            schedule_date_number: getCurrentDay + 1,
            schedule_time: new Date(),
            media_url: '',
            select_preset_id: selectedPreset
        })
        if (res.status) {
            await getStory()
        } else {
            console.error('Error while creating story')
        }
        setLoadingCreate(false)
    }

    const getStory = async () => {
        setLoadingStories(true)
        const res = await API.getStories(selectedPreset)

        if (res.status) {
            setStories(res.data)
        } else {
            console.error('Error while fetching stories')
        }
        setLoadingStories(false)
        setLoading(undefined)
    }

    useEffect(() => {
        getStory()
    }, [])

    const refetchStories = async () => {
        await getStory()
    }

    const updateEnableScheduleStory = async (value: boolean) => {
        setOwnerDetails(prev => {
            const updatedSlot = cloneDeep(prev)
            updatedSlot.owner_setting = updatedSlot.owner_setting ?? DEFAULT_OWNER_SETTINGS_VALUE

            updatedSlot.owner_setting.story_schedule_enable = value
            return updatedSlot
        })
    }

    return (
        <div className="flex flex-col gap-5">
            <div className="flex items-center gap-2 pb-3">
                <p className="text-ce-gray-400 text-2xl font-medium">Story Scheduler</p>
                <div className="flex-grow" />
                <Switch
                    id="story-schedular"
                    disabled={Object.keys(ownerDetails).length === 0}
                    checked={ownerDetails.owner_setting?.story_schedule_enable}
                    onCheckedChange={value => {
                        updateEnableScheduleStory(value)
                    }}
                />
            </div>
            <CEButton
                onClick={handleCreateStory}
                disabled={
                    loadingStories ||
                    loadingCreate ||
                    Object.keys(ownerDetails).length === 0 ||
                    !!loading
                }
                className="w-full"
            >
                Create a story {loadingCreate && <Spinner />}
            </CEButton>

            {Object.keys(ownerDetails).length === 0 ? (
                <Skeleton className="w-full h-10" />
            ) : (
                <CEInput
                    value={`Day ${getCurrentDay}`}
                    label="Account is currently on"
                    className="
                disabled:opacity-100 disabled:cursor-text"
                    disabled
                />
            )}
            <div className="flex flex-col gap-10">
                {stories.map(i => (
                    <Story
                        key={i.id}
                        story={i}
                        setLoading={setLoading}
                        loading={loading}
                        refetchStories={refetchStories}
                        currentBotDay={ownerDetails.first_activation_date}
                    />
                ))}
            </div>
        </div>
    )
}

export default Schedular
