import { ApiResponse } from './types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'
import { UpdateOwnerSettingType } from '@/lib/types/user.type'

const updateOwnerSetting = async (settings: UpdateOwnerSettingType): Promise<ApiResponse> => {

    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/update_owner_setting`,
                    params: {
                        method: 'PUT',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify(settings)
                    }
                }
            },
            callback
        )
    })
}

export default updateOwnerSetting
