import CEInput from '@/components/shared/ce-input'
import Spinner from '@/components/shared/spinner'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogFooter,
    DialogHeader,
    DialogTitle
} from '@/components/ui/dialog'
import * as API from '@/scripts/api'
import { useChatting } from '@/provider/chatting-provider'
import React, { useMemo, useState } from 'react'
import { callApiWithRetries } from '@/lib/common'
import { PresetType } from '@/lib/types/preset.type'

type propType = React.ComponentProps<typeof Dialog> & {
    preset_id: number
}

const CopyPreset = (props: propType) => {
    const { modelsPresets, getModelsPresetList } = useChatting()
    const { open, onOpenChange, preset_id, ...rest } = props
    const [loading, setLoading] = useState(false)
    const [presetName, setPresetName] = useState('')

    const toBCopiedPreset = useMemo(() => modelsPresets.find(i => i.id === preset_id), [preset_id])

    const createPresetCopy = async () => {
        setLoading(true)
        const apiCall = async () => await API.getSelectedPresetDetail(preset_id)
        try {
            const response = await callApiWithRetries(apiCall)
            if (response.status) {
                const presetDetail = response.data as PresetType
                const presetResponse = await API.createPreset({
                    detail: presetDetail.details,
                    item_type: 'preset',
                    model_id: Number(presetDetail.model_id),
                    title: presetName,
                    parent_id: presetDetail.parent_id
                })
                if (response.status) {
                    await getModelsPresetList(presetResponse.data.id, presetDetail.parent_id)
                } else {
                    throw new Error('Error while copying preset')
                }
            }
        } catch (error) {
            console.error('Error occurred while copying preset: ', error.message)
        }
        setLoading(false)
        onOpenChange(false)
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="w-[320px] max-h-[90vh] !left-[unset] right-[20px] translate-x-0 overflow-auto p-2">
                <DialogHeader className="py-2">
                    <DialogTitle className="text-white">
                        Copy preset "{toBCopiedPreset?.title}"
                    </DialogTitle>
                </DialogHeader>
                <CEInput
                    value={presetName}
                    onChange={e => {
                        setPresetName(e.target.value)
                    }}
                    className={
                        !presetName.trim()
                            ? 'border-venetian-red focus-visible:ring-venetian-red'
                            : ''
                    }
                    placeholder="preset name"
                />
                <DialogFooter>
                    <Button
                        type="button"
                        variant="link"
                        size="sm"
                        onClick={() => {
                            onOpenChange(false)
                        }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button type="submit" size="sm" onClick={createPresetCopy} disabled={loading}>
                        Create {loading && <Spinner />}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

export default CopyPreset
