import React from 'react'
import { Label } from '@/components/ui/label'
import { SBSnapSourceType, snapSourceOptions } from '@/lib/constants'
import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'
import SpecificMediaSelector from './specific-media-selector'

type propType = {
    options?: { label: string; value: string }[]
    snapPoolTypeKey: string
    specificSnapIdsKey: string
    onChange: (key: string, value: string | string[]) => void
    specificSnapId: string[]
    snapPoolType: string
    disabled?: boolean
}

const LiveSnapSource = (props: propType) => {
    const {
        options = snapSourceOptions,
        onChange,
        snapPoolTypeKey,
        specificSnapIdsKey,
        snapPoolType,
        specificSnapId,
        disabled = false
    } = props

    return (
        <div className="flex flex-col gap-2">
            <div className="flex gap-1 mb-0.5 items-center">
                <Label>Live Snap Source</Label>
            </div>
            <div className="flex gap-2 flex-col">
                {options.map(i => {
                    return (
                        <button
                            className={cn(
                                'flex items-center space-x-2 border rounded-full py-2 px-3 w-fit border-ce-gray-400 disabled:cursor-not-allowed disabled:opacity-50',
                                snapPoolType === i.value ? 'bg-blue-primary' : 'opacity-75'
                            )}
                            key={i.value}
                            onClick={e => {
                                onChange(snapPoolTypeKey, snapPoolType === i.value ? null : i.value)
                            }}
                            disabled={disabled}
                        >
                            {snapPoolType === i.value ? <Check size={16} /> : null}
                            <Label className="text-xs font-medium cursor-[inherit]">
                                {i.label}
                            </Label>
                        </button>
                    )
                })}
            </div>
            {snapPoolType === SBSnapSourceType.SPECIFIC_MEDIA_POOL.value ? (
                <SpecificMediaSelector
                    specificSnapIdsKey={specificSnapIdsKey}
                    specificSnapId={specificSnapId}
                    onChange={onChange}
                    disabled={disabled}
                />
            ) : null}
        </div>
    )
}

export default LiveSnapSource
