export const checkBotRunnable = (preset: PresetType, clientInfo: ClientInfoType) => {
    const { details } = preset
    const {
        // main
        age,
        city,
        source,
        name,
        dayTimeSetting,
        modelInfo,
        nightTimeSetting,
        matchUsersLocation,
        // opener
        opener = {} as PresetOpenerType,
        //cta
        cta = {} as PresetCtaType,
        snaps,
        followUps
    } = details || {}

    try {
        let isMainFilledUp =
            (city?.trim().length > 0 || matchUsersLocation) &&
            source?.trim().length > 0 &&
            name?.trim().length > 0 &&
            dayTimeSetting?.trim().length > 0 &&
            modelInfo?.trim().length > 0 &&
            nightTimeSetting?.trim().length > 0 && typeof age === 'string' && age?.trim().length > 0


        const isOpenerFilledUp =
            opener?.bDefaultSettings || opener?.bUseAIOpener || opener?.message?.trim()

        // const isPhasesFilledUp = () => {
        //     if (
        //         (phases.bDefaultWhiteKnightPhase &&
        //             !phases.bDefaultWhiteKnightOpener &&
        //             !phases.whiteKnightOpener?.trim()) ||
        //         (!phases.bDefaultWhiteKnightCta && !phases.whiteKnightCta?.trim())
        //     ) {
        //         return false
        //     }
        //     if (
        //         (phases.bDefaultGaslightPhase &&
        //             !phases.bDefaultGaslightOpener &&
        //             !phases.gaslightOpener?.trim()) ||
        //         (!phases.bDefaultGaslightCta && !phases.gaslightCta?.trim())
        //     ) {
        //         return false
        //     }
        //     if (
        //         (phases.bDefaultFreeTrialPhase &&
        //             !phases.bDefaultFreeTrailOpener &&
        //             !phases.freeTrialOpener?.trim()) ||
        //         (!phases.bDefaultFreeTrialCta && !phases.freeTrialCta?.trim())
        //     ) {
        //         return false
        //     }
        //     if (!cta?.ctaMessage?.bDefaultCtaMessage && !cta?.ctaMessage?.message?.trim()?.length) {
        //         return false
        //     }
        //     return true
        // }

        const isCtaFilledUp =
            cta?.finalStaticMessage?.bDefaultStaticMessage ||
            cta?.finalStaticMessage?.message?.trim()?.length

        const isCtaLinkFilledUp =
            cta?.ctaSet?.ctaInfo &&
            cta?.ctaSet?.ctaInfo?.every(i => !!i.link.trim() && !!i.platform.trim())

        // follow ups is filled
        const { xHourFollowUp } = followUps ?? {}
        const { messages, defaultSetting, hours } = xHourFollowUp ?? {}

        const isFollowUpFilled =
            defaultSetting || (hours > 0 && messages.every(i => !!i.message.trim()))

        const inCompleteSection: (keyof typeof ChattingSectionType | keyof typeof TabType)[] = []

        // validating snaps, if it does not satisfy the criteria
        if (isMainAndSexySnapListValid(snaps).length > 0) {
            // then pushing snaps into incomplete
            inCompleteSection.push('SNAPS')
        }

        if (!isMainFilledUp) {
            inCompleteSection.push('MAIN')
        }
        if (!isOpenerFilledUp) {
            inCompleteSection.push('OPENER')
        }
        if (!isCtaFilledUp) {
            inCompleteSection.push('CTAPHASE')
        }
        if (!isCtaLinkFilledUp) {
            inCompleteSection.push('CTAPHASE')
            inCompleteSection.push('CTA_LINKS')
        }
        if (!isFollowUpFilled) {
            inCompleteSection.push('FOLLOW_UPS')
        }

        if (!clientInfo.email?.trim() || !clientInfo.telegram?.trim()) {
            inCompleteSection.push('KEY')
        }

        return uniq(inCompleteSection)
    } catch (err) {
        return []
    }
}

const parseTime = (time: string | undefined): dayjs.Dayjs | null => {
    if (!time) return null
    const parsed = dayjs(time, 'HH:mm', true)
    return parsed.isValid() ? parsed : null
}

export const validateAddsRunCycle = (addRun: runCycleScheduleType) => {
    const { enabled, schedule } = addRun

    const invalidIds: Set<string> = new Set()

    // Iterate over the schedule to identify any entries with undefined start_time or end_time
    for (const item of schedule) {
        if (item.start_time === undefined || item.end_time === undefined) {
            invalidIds.add(item.id)
        }
    }

    // Sort by start_time
    const sortedSchedule = schedule.sort((a, b) => {
        const timeA = parseTime(a.start_time)
        const timeB = parseTime(b.start_time)
        if (timeA && timeB) return timeA.diff(timeB)
        return 0
    })

    for (let i = 0; i < sortedSchedule.length; i++) {
        const item = sortedSchedule[i]
        const startTime = parseTime(item.start_time)
        const endTime = parseTime(item.end_time)

        if (startTime === null) {
            invalidIds.add(item.id)
        }
        if (endTime && endTime.isBefore(startTime)) {
            invalidIds.add(item.id)
        }
        if (endTime && endTime.isSame(startTime)) {
            invalidIds.add(item.id)
        }
    }

    // Check for overlaps
    for (let i = 0; i < sortedSchedule.length - 1; i++) {
        const current = sortedSchedule[i]
        const next = sortedSchedule[i + 1]
        const currentEnd = parseTime(current.end_time)
        const nextStart = parseTime(next.start_time)

        if (currentEnd && nextStart && currentEnd.isAfter(nextStart)) {
            invalidIds.add(current.id)
            invalidIds.add(next.id)
        }
    }

    return Array.from(invalidIds)
}

export function validateOutfitCounts(liveSnaps: LiveSnapType[]): boolean {
    // Initialize counters for each outfit type
    const outfitCounts: Record<OUTFIT_TYPE, number> = {
        [OUTFIT_TYPE.OUTFIT_1]: 0,
        [OUTFIT_TYPE.OUTFIT_2]: 0,
        [OUTFIT_TYPE.OUTFIT_3]: 0
    }

    // Count how many times each outfit appears in the array
    liveSnaps.forEach(snap => {
        if (snap.outfit) {
            outfitCounts[snap.outfit]++
        }
    })

    // Check that each outfit type appears at least 4 times if it exists in the array
    return Object.values(outfitCounts).every(count => count >= 4 || count === 0)
}

/**
 * @description checks whether the main and sexy snap list is valid or not
 * @param snaps snap list
 */
export const isMainAndSexySnapListValid = (snaps: LiveSnapType[]): SnapInvalidationType[] => {
    // checking whether the user has at least 4 combined snaps of main and sexy
    const result = []

    const snapList = snaps.filter(
        snap => snap.purpose === PurposeType.MAIN || snap.purpose === PurposeType.SEXY
    )
    // if the snap list length is less than 4
    if (snapList.length < 4) {
        result.push(SnapInvalidationType.SnapsLT4)
    }
    // or every snap does not contain description
    if (!snapList.every(snap => snap.description)) {
        result.push(SnapInvalidationType.Description)
    }

    // or there should be atleast 4 snap for outfit if selected in any one
    if (!validateOutfitCounts(snaps)) {
        result.push(SnapInvalidationType.OutfitSnapLT4)
    }

    return result
}
