import { PresetDetailType, PresetItemTypeType } from '@/lib/types/preset.type'
import { ApiResponse } from './types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'

const createPreset = async ({
    detail,
    model_id,
    title,
    parent_id,
    item_type
}: {
    detail: PresetDetailType
    title: string
    model_id: number
    parent_id?: number
    item_type: PresetItemTypeType
}): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/preset`,
                    params: {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify({
                            title: title,
                            model_id: model_id,
                            details: detail,
                            parent_id: parent_id,
                            item_type: item_type
                        })
                    }
                }
            },
            callback
        )
    })
}

export default createPreset
