import React from 'react'
import { TriangleAlert } from 'lucide-react'
import { Alert, AlertDescription } from '@/components/ui/alert'

type propType = React.ComponentProps<typeof Alert> & {
    label: string
    alertDescriptionProp?: React.ComponentProps<typeof AlertDescription>
}

const CEAlert = (props: propType) => {
    const { label, variant = 'destructive', alertDescriptionProp = {}, ...rest } = props
    return (
        <Alert variant={variant} {...rest}>
            {variant === 'destructive' ? (
                <TriangleAlert strokeWidth={2} className="h-[18px] w-[18px] text-cherry-red" />
            ) : null}

            <AlertDescription {...alertDescriptionProp}>{label}</AlertDescription>
        </Alert>
    )
}

export default CEAlert
