import CEInput from '@/components/shared/ce-input'
import { useGetStarted } from '@/provider/get-started-provider'
import React from 'react'
import CEButton from '@/components/shared/ce-button'
import { handleParseInt } from '@/lib/common'

const Info = () => {
    const { preset, setPreset } = useGetStarted()

    return (
        <div className="flex flex-col gap-4">
            <CEInput
                label="Name"
                htmlFor="name"
                value={preset.name}
                onChange={e => {
                    setPreset(prev => ({ ...prev, name: e.target.value }))
                }}
                placeholder="Name"
            />
            <CEInput
                label="Age"
                htmlFor="age"
                type="number"
                value={preset.age}
                placeholder="Age"
                onChange={e => {
                    setPreset(prev => ({ ...prev, age: String(e.target.value) }))
                }}
            />
        </div>
    )
}

export default Info
