import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { ApiResponse } from '../types/response.type'
import { authStore } from '@/scripts/store'

const getStories = (preset_id: number): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/story/get/${preset_id}`,
                    params: {
                        method: 'GET',
                        headers: { Authorization: authStore.getAPIKey() }
                    }
                }
            },
            callback
        )
    })
}

export default getStories
