import { MessageSquareMore, MessageSquareOff } from 'lucide-react'
import React, { useState } from 'react'
import * as API from '@/scripts/api'
import { addRequestUserType } from '@/lib/types/scrape-engine.type'
import { sleep, waitForElement } from '@/lib/common'
import { UserInfoType } from '@/lib/types/user.type'
import { getAddRequestUserInfo } from '@/lib/getUserInfoFromElement'

const listClass = '.LtQF8 .zYgGl .JB8Z3 .ReactVirtualized__Grid__innerScrollContainer[role="list"]'

type propType = {
    userMainInfo: UserInfoType
    loadingDisabledAdds: boolean
    disableAllAdds: boolean
    setRefetchDisableAdds: React.Dispatch<React.SetStateAction<boolean>>
    setLoadingDisabledAdds: React.Dispatch<React.SetStateAction<boolean>>
    setDisableAllAdds: React.Dispatch<React.SetStateAction<boolean>>
}

const ToggleAllAdds = React.memo((props: propType) => {
    const {
        userMainInfo,
        setRefetchDisableAdds,
        loadingDisabledAdds,
        setLoadingDisabledAdds,
        setDisableAllAdds,
        disableAllAdds
    } = props

    const [loading, setLoading] = useState(false)

    const handleToggleDisabledAdds = async () => {
        setLoading(true)
        setLoadingDisabledAdds(true)
        let userNames = []

        if (!disableAllAdds) {
            let userList: addRequestUserType[] = []

            const popup = (await waitForElement(listClass, 'snap_add_list')) as HTMLDivElement

            const viewMore = popup.querySelector('div.g8CcQ') as HTMLDivElement

            if (viewMore) {
                viewMore.click()
            }
            await sleep(500)
            await getAddRequestUserList(popup, userList)

            userNames = userList.map(i => i.username)
        }
        const res = await API.bulkToggleDisableAdd({
            friend_username: userNames,
            owner_id: userMainInfo.mutable_username
        })

        if (res.status) {
            setDisableAllAdds(prev => !prev)
            setRefetchDisableAdds(true)
        } else {
            setLoadingDisabledAdds(false)
            console.error('Something went wrong while toggling disable adds')
        }
        setLoading(false)
    }

    return (
        <button
            style={{
                background: 'transparent',
                outline: 'none',
                border: 'none',
                display: 'flex',
                alignItems: 'center',
                gap: '4px'
            }}
            disabled={loadingDisabledAdds || loading}
            onClick={handleToggleDisabledAdds}
        >
            {loading || loadingDisabledAdds ? (
                <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="1em"
                    height="1em"
                    viewBox="0 0 24 24"
                >
                    <path
                        fill="currentColor"
                        d="M12 1a11 11 0 1 0 11 11A11 11 0 0 0 12 1m0 19a8 8 0 1 1 8 -8 8 8 0 0 1 -8 8"
                        opacity="0.25"
                    />
                    <path
                        fill="currentColor"
                        d="M12 4a8 8 0 0 1 7.89 6.7 1.53 1.3 0 0 0 1.49 1.3 1.5 1.5 0 0 0 1.48 -1.75 11 11 0 0 0 -21.72 0A1.5 1.5 0 0 0 2.62 12a1.53 1.53 0 0 0 1.49 -1.3A8 8 0 0 1 12 4"
                    >
                        <animateTransform
                            attributeName="transform"
                            dur="0.75s"
                            repeatCount="indefinite"
                            type="rotate"
                            values="0 12 12;360 12 12"
                        />
                    </path>
                </svg>
            ) : disableAllAdds ? (
                <MessageSquareOff size={16} style={{ color: '#F43A56', marginTop: '4px' }} />
            ) : (
                <MessageSquareMore size={16} style={{ color: '#0975F1', marginTop: '4px' }} />
            )}
        </button>
    )
})

export default ToggleAllAdds

const getAddRequestUserList = async (popup: HTMLDivElement, userList: addRequestUserType[]) => {
    const runProcess = async divElements => {
        let newUserInfo = []
        for (let i = 0; i < divElements.length; i++) {
            const userInfo = getAddRequestUserInfo(divElements[i])
            if (!userInfo) {
                continue
            }
            if (!userList.some(user => user.username === userInfo.username)) {
                userList.push(userInfo)
                newUserInfo.push(userInfo)
            }
        }

        if (newUserInfo.length == 0) {
            return true
        }
    }

    const processWhileScrollToBottom = async () => {
        let totalCount = 0
        let usersDivList = popup.querySelectorAll('div.H8CAi')
        await runProcess(usersDivList)
        while (true) {
            totalCount = userList.length

            usersDivList[usersDivList.length - 1].scrollIntoView()

            await sleep(1000)
            usersDivList = popup.querySelectorAll('div.H8CAi')

            const should_break = await runProcess(usersDivList)

            if (should_break) {
                break
            }

            // Loop it throuth seems not increase the friends
            if (totalCount == usersDivList.length) {
                break
            }
            console.log(`Total friends now: ${userList.length}`)
        }
    }

    await processWhileScrollToBottom()
}
