import CEInput from '@/components/shared/ce-input'
import { CtaSetType, PresetCtaInfoType } from '@/lib/types/preset.type'
import { cn } from '@/lib/utils'
import { Plus } from 'lucide-react'
import React, { useEffect, useRef } from 'react'
import Slider, { Settings } from 'react-slick'

type propType = {
    updateCTAInfo: (key: keyof CtaSetType, value: string | number | boolean) => void
    value: CtaSetType
    deleteCTAInfo: (id: string) => void
    addCTAInfo: () => void
    updateCTA: (id: string, key: keyof PresetCtaInfoType, value: string) => void
}

const MultipleLinks = (props: propType) => {
    const slick = useRef<Slider | null>(null)
    const { updateCTAInfo, value, addCTAInfo, deleteCTAInfo, updateCTA } = props
    const { activeCta, ctaInfo  } = value
    const prevCTAInfo = useRef(ctaInfo)

    useEffect(() => {
        if (!ctaInfo) {
            addCTAInfo()
        }
    }, [ctaInfo])

    useEffect(() => {
        if (
            ctaInfo?.length !== prevCTAInfo.current?.length &&
            ctaInfo?.length > prevCTAInfo.current?.length
        ) {
            slick.current?.slickGoTo(ctaInfo.length - 1, false)
            updateCTAInfo('activeCta', ctaInfo.length - 1)
        }
        prevCTAInfo.current = ctaInfo
    }, [ctaInfo])

    const settings: Settings = {
        dots: false,
        infinite: false,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1,
        initialSlide: activeCta,
        afterChange: next => {
            updateCTAInfo('activeCta', next)
        },
        rows:1
    }

    return (
        <div>
            <Slider ref={slick} arrows={false} {...settings} className="h-[224px] overflow-hidden">
                {ctaInfo?.map(i => {
                    return (
                        <div className="!flex flex-col relative  gap-5 p-3 pb-9 pt-9" key={i.id}>
                            {ctaInfo.length > 1 && (
                                <button
                                    className="ml-auto absolute right-3 px-3 top-3 h-6 w-fit rounded"
                                    onClick={() => {
                                        deleteCTAInfo(i.id)
                                    }}
                                >
                                    <img
                                        src={chrome.runtime.getURL('./assets/svg/bin.svg')}
                                        style={{ height: '24px' }}
                                    />
                                </button>
                            )}
                            <CEInput
                                label="Platform"
                                placeholder="Platform"
                                info={'Where you are funneling your traffic too'}
                                value={i.platform}
                                onChange={e => {
                                    updateCTA(i.id, 'platform', e.target.value)
                                }}
                            />

                            <CEInput
                                label="Link"
                                placeholder="Link"
                                info={'The link you will be sending in your CTAs'}
                                value={i.link}
                                onChange={e => {
                                    updateCTA(i.id, 'link', e.target.value)
                                }}
                            />
                        </div>
                    )
                })}
            </Slider>
            <div className="flex gap-2.5 items-center justify-center pb-5">
                {ctaInfo?.map((i, index) => {
                    const isIncomplete = !i.link.trim() || !i.platform.trim()
                    return (
                        <>
                            <button
                                className={cn(
                                    'h-2.5 w-2.5 border rounded-full border-blue cursor-pointer',
                                    index === activeCta ? 'bg-blue' : '',
                                    index === activeCta && isIncomplete ? 'bg-venetian-red' : '',
                                    isIncomplete ? 'border-venetian-red' : ''
                                )}
                                onClick={() => {
                                    slick.current?.slickGoTo(index, false)
                                }}
                            ></button>
                            {ctaInfo.length < 6 && index + 1 === ctaInfo.length && (
                                <button className="cursor-pointer">
                                    <Plus
                                        size={15}
                                        className="text-blue "
                                        onClick={e => {
                                            e.stopPropagation()
                                            addCTAInfo()
                                        }}
                                    />
                                </button>
                            )}
                        </>
                    )
                })}
            </div>
        </div>
    )
}

export default MultipleLinks
