import * as React from 'react'
import { Tabs as ShadCnTab, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { TAB_LIST, TabType } from '@/lib/constants'
import { Separator } from '@/components/ui/separator'
import Chatting from './chatting'
import Analytics from './analytics'
import LicenseKey from './license-key'
import { useChatting } from '@/provider/chatting-provider'
import Header from './header'
import ContentBody from '..'
import Schedular from './schedular'
import Settings from './settings'

type propType = React.ComponentProps<typeof ContentBody>

function Tabs(props: propType) {
    const { userMainInfo, preset, ownerDetails, activeTab, setActiveTab, inCompletePresetSection } =
        useChatting()

    const contentClassName = 'py-5 px-4 bg-slate-950 rounded-b-[10px]'

    const isNotFilled = (value: string) => {
        return inCompletePresetSection.includes(value as keyof typeof TabType)
    }

    return (
        <div className="mt-5">
            <Header {...props} />
            <div className="border border-slate-800 rounded-[10px]">
                <ShadCnTab value={activeTab} className="w-full">
                    <TabsList className="grid w-full grid-cols-5 h-12 p-0 rounded-t-[10px] rounded-b-none">
                        {TAB_LIST.map(i => (
                            <TabsTrigger
                                className="h-12 first:data-[state=active]:rounded-tl-[10px] last:data-[state=active]:rounded-tr-[10px]"
                                value={i.value}
                                onClick={() => {
                                    setActiveTab(i.value)
                                }}
                                disabled={
                                    Object.keys(preset).length === 0 ||
                                    !userMainInfo.attemptFetch ||
                                    Object.keys(ownerDetails).length === 0
                                }
                            >
                                <i.icon
                                    fill={
                                        isNotFilled(i.value)
                                            ? '#C41C1C'
                                            : activeTab === i.value
                                              ? '#0975F1'
                                              : '#9C9C9C'
                                    }
                                />
                            </TabsTrigger>
                        ))}
                    </TabsList>
                    <Separator orientation="horizontal" />
                    <TabsContent className={contentClassName} value={TabType.MESSAGE}>
                        <Chatting />
                    </TabsContent>
                    <TabsContent className={contentClassName} value={TabType.ADD}>
                        <Schedular />
                    </TabsContent>
                    <TabsContent className={contentClassName} value={TabType.CHATBAR}>
                        <Analytics />
                    </TabsContent>
                    <TabsContent className={contentClassName} value={TabType.SETTING}>
                        <Settings />
                    </TabsContent>
                    <TabsContent className={contentClassName} value={TabType.KEY}>
                        <LicenseKey />
                    </TabsContent>
                </ShadCnTab>
            </div>
        </div>
    )
}

export default Tabs
