import CESelect from '@/components/shared/ce-select'
import CETextarea from '@/components/shared/ce-textarea'
import CEUnderlineInput from '@/components/shared/ce-underline-input'
import Help from '@/components/shared/help'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { chattingStyle as chattingStyleOptions, addSources } from '@/lib/constants'
import { PresetDetailType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import React from 'react'
import City from './city'
import { handleKeyDownOnIntegerInput, setLocalPresetValue } from '@/lib/common'

const Main = () => {
    const { preset, setPreset } = useChatting()

    const { details = {} } = preset

    const {
        source,
        modelInfo,
        dayTimeSetting,
        nightTimeSetting,
        matchUsersLocation,
        name,
        age
    } = details

    const updatePreset = (name: keyof PresetDetailType | string, value: string | boolean) => {
        setPreset(prev => ({ ...prev, details: { ...(prev.details ?? {}), [name]: value } }))
    }

    return (
        <>
            <City />
            <div className="flex gap-2 items-center">
                <Label>Match users location</Label>{' '}
                <Help label="AI will pretend to be in whichever city the user is in. This means that the first part of the conversation will be spent trying to figure out where they live" />
                <div className="flex-grow" />
                <Switch
                    checked={matchUsersLocation}
                    onCheckedChange={value => {
                        updatePreset('matchUsersLocation', value)
                        setLocalPresetValue({ matchUsersLocation: value })
                    }}
                />
            </div>

            <CEUnderlineInput
                placeholder="Model Name"
                wrapperClassName="pt-2 !mb-3"
                name="name"
                value={name || ''}
                onChange={e => {
                    updatePreset(e.target.name, e.target.value)
                }}
            />
            <CEUnderlineInput
                placeholder="Model Age"
                wrapperClassName="!mb-3"
                type="number"
                min="0"
                name="age"
                value={typeof age === "string" ? age : ''}
                onChange={e => {
                    updatePreset(e.target.name, e.target.value)
                }}
                onKeyDown={handleKeyDownOnIntegerInput}
            />

            <CESelect
                options={addSources}
                label="Add Source"
                value={source}
                onValueChange={value => {
                    updatePreset('source', value)
                }}
                placeholder="a add source"
                info="where your adds are coming from"
            />
            {/* <CESelect
                options={chattingStyleOptions}
                label="Chatting Style"
                value={chattingStyle}
                onValueChange={value => {
                    updatePreset('chattingStyle', value)
                }}
                placeholder="a chatting style"
                info="Coming soon"
            /> */}

            <CETextarea
                label="Model Info"
                info={
                    <>
                        <p>Background information on your model</p>
                        <p className="mt-8">
                            Example: You study psychology at a local college and recently broke up
                            with your ex because he was too controlling. You have a high sex drive.
                        </p>
                    </>
                }
                htmlFor="modelInfo"
                name="modelInfo"
                placeholder="Enter model info"
                value={modelInfo}
                onChange={e => {
                    updatePreset('modelInfo', e.target.value)
                }}
            />

            <CETextarea
                label="Day Time Setting"
                info={
                    <>
                        <p>What your model will be doing when adds message her during the day</p>
                        <p className="mt-8">Example: you are at home and doing homework.</p>
                    </>
                }
                htmlFor="dayTimeSetting"
                name="dayTimeSetting"
                placeholder="Enter day time setting"
                value={dayTimeSetting}
                onChange={e => {
                    updatePreset('dayTimeSetting', e.target.value)
                }}
            />
            <CETextarea
                label="Night Time Setting"
                info={
                    <>
                        <p>What your model will be doing when adds message her at night</p>
                        <p className="mt-8">
                            Example: You finished your homework. You are now bored and lonely
                            cleaning your bedroom.
                        </p>
                    </>
                }
                htmlFor="nightTimeSetting"
                name="nightTimeSetting"
                placeholder="Enter night time setting"
                value={nightTimeSetting}
                onChange={e => {
                    updatePreset('nightTimeSetting', e.target.value)
                }}
            />
        </>
    )
}

export default Main
