import React, { useState } from 'react'
import { MessageSquareMore, MessageSquareOff } from 'lucide-react'
import * as Utils from '@/lib/common'
import { bulkPauseChattingParams } from '@/scripts/api/types/params.type'
import { UserInfoType } from '@/lib/types/user.type'
import * as API from '@/scripts/api'
import { chatUserType } from '@/lib/types/scrape-engine.type'
import { getUserInfoFromElement } from '@/lib/getUserInfoFromElement'

type propType = {
    userMainInfo: UserInfoType
    disableAllChatting: boolean
    setDisableAllChatting: React.Dispatch<React.SetStateAction<boolean>>
    setRefetchAllConversations: React.Dispatch<React.SetStateAction<boolean>>
}

const feedUserDivClassName =
    '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'

const ToggleAllChatting = React.memo((props: propType) => {
    const { userMainInfo, setDisableAllChatting, disableAllChatting, setRefetchAllConversations } =
        props

    const [loading, setLoading] = useState(false)

    const handleToggleDisabledChatting = async () => {
        setLoading(true)
        let userNames = []
        let response
        if (disableAllChatting) {
            response = await API.bulkPauseChatting({
                owner_id: userMainInfo.mutable_username
            })
        } else {
            const userList = await extractUserDetailsWithScroll()
            const params: bulkPauseChattingParams = {
                owner_id: userMainInfo.mutable_username,
                request_user_info: userList.map(user => ({
                    request_user_id: user.uuid,
                    request_username: user.userName
                }))
            }

            response = await API.bulkPauseChatting(params)
        }

        if (response.status) {
            setDisableAllChatting(prev => !prev)
            setRefetchAllConversations(true)
        } else {
            console.error('Something went wrong while toggling disable adds')
        }
        setLoading(false)
    }

    return (
        <button
            style={{
                background: 'transparent',
                outline: 'none',
                border: 'none',
                display: 'flex',
                alignItems: 'center',
                gap: '4px'
            }}
            disabled={loading}
            onClick={handleToggleDisabledChatting}
        >
            {loading ? (
                <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="1em"
                    height="1em"
                    viewBox="0 0 24 24"
                >
                    <path
                        fill="currentColor"
                        d="M12 1a11 11 0 1 0 11 11A11 11 0 0 0 12 1m0 19a8 8 0 1 1 8 -8 8 8 0 0 1 -8 8"
                        opacity="0.25"
                    />
                    <path
                        fill="currentColor"
                        d="M12 4a8 8 0 0 1 7.89 6.7 1.53 1.3 0 0 0 1.49 1.3 1.5 1.5 0 0 0 1.48 -1.75 11 11 0 0 0 -21.72 0A1.5 1.5 0 0 0 2.62 12a1.53 1.53 0 0 0 1.49 -1.3A8 8 0 0 1 12 4"
                    >
                        <animateTransform
                            attributeName="transform"
                            dur="0.75s"
                            repeatCount="indefinite"
                            type="rotate"
                            values="0 12 12;360 12 12"
                        />
                    </path>
                </svg>
            ) : disableAllChatting ? (
                <MessageSquareOff size={20} style={{ color: '#F43A56', marginTop: '4px' }} />
            ) : (
                <MessageSquareMore size={20} style={{ color: '#0975F1', marginTop: '4px' }} />
            )}
        </button>
    )
})

export default ToggleAllChatting

export const extractUserDetailsWithScroll = async () => {
    let userInfoArray: { uuid: string; userName: string }[] = []

    const runProcessTopToBottom = async (userElements: NodeListOf<HTMLDivElement>) => {
        let newUserInfo: { element: HTMLDivElement; info: chatUserType }[] = []

        for (let i = 0; i < userElements.length; i++) {
            const userInfo = getUserInfoFromElement(userElements[i])
            if (!userInfo) {
                continue
            }

            if (!userInfoArray.some(user => user.uuid === userInfo.uuid)) {
                userInfoArray.push({ userName: userInfo.userName, uuid: userInfo.uuid })

                newUserInfo.push({ element: userElements[i], info: userInfo })
            }
        }

        if (newUserInfo.length === 0) {
            return true
        }
        return false
    }

    const processWhileScrollToBottom = async () => {
        let totalCount = 0

        let usersElement = document.querySelectorAll(
            feedUserDivClassName
        ) as NodeListOf<HTMLDivElement>

        await runProcessTopToBottom(usersElement)

        while ((usersElement[usersElement.length - 1] as HTMLElement).offsetParent !== null) {
            totalCount = userInfoArray.length
            usersElement = document.querySelectorAll(feedUserDivClassName)

            usersElement[usersElement.length - 1].scrollIntoView()

            await Utils.sleep(1000)
            const isMainLoadUnload = await Utils.waitForElementUnloadWithTimeout(
                'div[role="listitem"] div.maLbV',
                30000
            )
            if (!isMainLoadUnload) {
                window.location.reload()
                return
            }

            usersElement = document.querySelectorAll(feedUserDivClassName)

            const should_break = await runProcessTopToBottom(usersElement)

            if (should_break) {
                break
            }

            // Loop it through till not increase the friends
            if (totalCount == userInfoArray.length) {
                break
            }
            console.log(`Total friends now: ${userInfoArray.length}`)
        }
    }

    await processWhileScrollToBottom()

    return userInfoArray
}
