import { PresetType } from '@/lib/types/preset.type'
import { ApiResponse } from './types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'

const updatePreset = async (preset: PresetType): Promise<ApiResponse> => {

    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/preset`,
                    params: {
                        method: 'PUT',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify(preset)
                    }
                }
            },
            callback
        )
    })
}

export default updatePreset
    