import React, { useState } from 'react'
import * as API from '@/scripts/api'
import { UserInfoType } from '@/lib/types/user.type'
import { MessageSquareMore, MessageSquareOff } from 'lucide-react'

type propType = {
    username: string
    userMainInfo: UserInfoType
    toggleDisabledAdd: (username: string) => void
    userDisabled: boolean
    loadingDisabledAdds: boolean
}

const DisableStatus = React.memo((props: propType) => {
    const { username, userMainInfo, toggleDisabledAdd, userDisabled, loadingDisabledAdds } = props
    const [loading, setLoading] = useState(false)


    const handleToggleDisabledAdds = async () => {
        setLoading(true)
        const res = await API.toggleDisableAdd({
            friend_username: username,
            owner_id: userMainInfo.mutable_username
        })

        if (res.status) {
            toggleDisabledAdd(username)
        } else {
            console.error('Something went wrong while toggling disable adds')
        }
        setLoading(false)
    }

    return (
        <button
            style={{
                background: 'transparent',
                outline: 'none',
                border: 'none',
                display: 'flex',
                alignItems: 'center',
                gap: '4px'
            }}
            disabled={loadingDisabledAdds || loading}
            onClick={handleToggleDisabledAdds}
        >
            {loading || loadingDisabledAdds ? (
                <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="1em"
                    height="1em"
                    viewBox="0 0 24 24"
                >
                    <path
                        fill="currentColor"
                        d="M12 1a11 11 0 1 0 11 11A11 11 0 0 0 12 1m0 19a8 8 0 1 1 8 -8 8 8 0 0 1 -8 8"
                        opacity="0.25"
                    />
                    <path
                        fill="currentColor"
                        d="M12 4a8 8 0 0 1 7.89 6.7 1.53 1.3 0 0 0 1.49 1.3 1.5 1.5 0 0 0 1.48 -1.75 11 11 0 0 0 -21.72 0A1.5 1.5 0 0 0 2.62 12a1.53 1.53 0 0 0 1.49 -1.3A8 8 0 0 1 12 4"
                    >
                        <animateTransform
                            attributeName="transform"
                            dur="0.75s"
                            repeatCount="indefinite"
                            type="rotate"
                            values="0 12 12;360 12 12"
                        />
                    </path>
                </svg>
            ) : userDisabled ? (
                <MessageSquareOff size={16} style={{ color: '#F43A56', marginTop: '4px' }} />
            ) : (
                <MessageSquareMore size={16} style={{ color: '#0975F1', marginTop: '4px' }} />
            )}
        </button>
    )
})

export default DisableStatus
