import * as React from 'react'

import { cn } from '@/lib/utils'
import { cva, type VariantProps } from 'class-variance-authority'

const inputVariants = cva(
    'flex w-full border rounded-md  px-3 py-2  file:border-0 file:bg-transparent file:text-base file:font-medium focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-offset-1 disabled:cursor-not-allowed disabled:opacity-50 border-slate-800 bg-slate-950 ring-offset-slate-950 placeholder:text-slate-400 focus-visible:ring-slate-300 text-white',
    {
        variants: {
            size: {
                default: 'h-10 text-sm',
                sm: 'h-9 text-sm',
                lg: 'h-11 text-sm'
            }
        },
        defaultVariants: {
            size: 'lg'
        }
    }
)

export interface InputProps
    extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'>,
        VariantProps<typeof inputVariants> {}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
    ({ className, type, size = 'lg', ...props }, ref) => {
        return (
            <input
                type={type}
                className={cn(inputVariants({ size, className }))}
                ref={ref}
                autoComplete='off'
                {...props}
            />
        )
    }
)
Input.displayName = 'Input'

export { Input }
