import React from 'react'
import { runCycleType } from '@/lib/types/user.type'
import { Button } from '@/components/ui/button'
import { Plus } from 'lucide-react'
import CEInput from '@/components/shared/ce-input'
import { cn } from '@/lib/utils'
import { Label } from '@/components/ui/label'

type propType = {
    slots: runCycleType[]
    handleUpdateStartTimeSlot: (value: string, id: string) => void
    handleUpdateEndTimeSlot: (value: string, id: string) => void
    handleRemoveSlot: (id: string) => void
    addNewSlotToDay: () => void
    invalidSlots: string[]
}

const TimeRange = (props: propType) => {
    const {
        slots,
        invalidSlots,
        handleUpdateStartTimeSlot,
        handleUpdateEndTimeSlot,
        handleRemoveSlot,
        addNewSlotToDay
    } = props

    return (
        <div className="flex flex-col gap-2 w-full mt-5">
            <div className="flex gap-2">
                <Label className="flex-1">start time</Label>
                <div className="w-[5px]"></div>
                <Label className="flex-1 text-end">end time</Label>
                <div className="w-6"></div>
            </div>
            {slots.map((i, index) => {
                return (
                    <div className="flex gap-2 items-center" key={i.id}>
                        <div className="flex gap-1 lg:gap-2 items-center w-full">
                            <CEInput
                                type="time"
                                value={i.start_time}
                                className={cn(
                                    'relative run-cycle',
                                    invalidSlots.includes(i.id)
                                        ? 'border-venetian-red focus-visible:ring-venetian-red'
                                        : ''
                                )}
                                onChange={e => {
                                    const timeValue = e.target.value
                                    handleUpdateStartTimeSlot(timeValue, i.id)
                                }}
                            />
                            <span>-</span>
                            <CEInput
                                type="time"
                                value={i.end_time}
                                className={cn(
                                    'relative run-cycle',
                                    invalidSlots.includes(i.id)
                                        ? 'border-venetian-red focus-visible:ring-venetian-red'
                                        : ''
                                )}
                                onChange={e => {
                                    const timeValue = e.target.value
                                    handleUpdateEndTimeSlot(timeValue, i.id)
                                }}
                            />
                            <div className="w-6 flex justify-center items-center">
                                {slots.length > 1 ? (
                                    <button
                                        className="ml-auto  h-6 w-fit rounded"
                                        onClick={() => {
                                            handleRemoveSlot(i.id)
                                        }}
                                    >
                                        <img
                                            src={chrome.runtime.getURL('./assets/svg/bin.svg')}
                                            style={{ height: '24px' }}
                                        />
                                    </button>
                                ) : null}
                            </div>
                        </div>
                    </div>
                )
            })}

            <Button
                variant="link"
                className="h-fit p-2 w-fit self-end"
                onClick={() => {
                    addNewSlotToDay()
                }}
                disabled={slots.length === 5}
            >
                Add run <Plus size={18} color="#0975F1" />
            </Button>
            <p className="italic text-gray-400 text-sm font-semibold">
                Disclaimer: Times are in UTC+0
            </p>
        </div>
    )
}

export default TimeRange
