import { ApiResponse } from '../types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../../store'
import { DuplicateStoryParamsType } from '../types/params.type'

const createStory = async (story: DuplicateStoryParamsType): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/story/duplicate`,
                    params: {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify(story)
                    }
                }
            },
            callback
        )
    })
}

export default createStory
