import * as React from 'react'
import { useChatting } from '@/provider/chatting-provider'
import LiveSnapSource from '@/components/content/live-snap-source'
import { PresetOpenerType } from '@/lib/types/preset.type'
import Help from '@/components/shared/help'
import { Separator } from '@/components/ui/separator'
import { Label } from '@/components/ui/label'
import CETextarea from '@/components/shared/ce-textarea'
import { Switch } from '@/components/ui/switch'
import SectionHeader from '@/components/shared/section-header'
import { DEFAULT_OPENER } from '@/lib/defaultPresetsValue'

const Opener = () => {
    const { preset, setPreset } = useChatting()
    const { details = {} } = preset
    const { opener = {} as PresetOpenerType } = details

    const {
        snapPoolType = null,
        specificSnapIds = [],
        bDefaultSettings,
        bUseAIOpener,
        message
    } = opener

    const updateOpener = (key: keyof PresetOpenerType, value: string | boolean | string[]) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                opener: { ...(prev.details?.opener ?? {}), [key]: value } as PresetOpenerType
            }
        }))
    }

    const setOpenerToDefault = (value: boolean) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                opener: { ...DEFAULT_OPENER, bDefaultSettings: value }
            }
        }))
    }

    return (
        <div className="bg-primary rounded-md">
            <SectionHeader
                label="Opener"
                info={
                    <>
                        <p>What the AI will say to initiate conversations</p>
                        <p className="mt-8">
                            Clarify live snap source specific media pool for customizable opener
                        </p>
                    </>
                }
            />
            <Separator />

            <div className="flex flex-col gap-5 p-3">
                <div className="flex items-center justify-between">
                    <Label htmlFor="default">Default Settings</Label>
                    <Switch
                        id="default"
                        checked={bDefaultSettings}
                        onCheckedChange={setOpenerToDefault}
                    />
                </div>
                {!bDefaultSettings ? (
                    <>
                        <div className="flex items-center justify-between">
                            <Label htmlFor="aiOpener">Use AI opener</Label>
                            <Switch
                                id="aiOpener"
                                checked={bUseAIOpener}
                                onCheckedChange={value => {
                                    updateOpener('bUseAIOpener', value)
                                }}
                            />
                        </div>
                        <CETextarea
                            label="Opening Message"
                            value={message}
                            placeholder="Add | for line break"
                            onChange={e => {
                                updateOpener('message', e.target.value)
                            }}
                        />

                        <LiveSnapSource
                            snapPoolTypeKey={'snapPoolType'}
                            specificSnapIdsKey={'specificSnapIds'}
                            onChange={updateOpener}
                            snapPoolType={snapPoolType}
                            specificSnapId={specificSnapIds ?? []}
                        />
                    </>
                ) : null}
            </div>
        </div>
    )
}

export default Opener
