import React from 'react'
import CycleInput from './cycle-input'
import Help from '@/components/shared/help'
import { handleParseInt } from '@/lib/common'
import CEInput from '@/components/shared/ce-input'
import { Label } from '@/components/ui/label'
import { useChatting } from '@/provider/chatting-provider'
import { PresetSnapsAddType } from '@/lib/types/preset.type'
import { Switch } from '@/components/ui/switch'
import { Skeleton } from '@/components/ui/skeleton'
import RunCycle from './run-cycle'

const SnapAdds = () => {
    const { preset, setPreset, ownerDetails } = useChatting()
    const { details = {} } = preset
    const { snapsAdd = {} } = details

    const updateSnapAddInfo = (
        key: keyof PresetSnapsAddType | string,
        e:
            | React.ChangeEvent<HTMLInputElement>
            | { target: { name: string; value: string | boolean } }
    ) => {
        const { name, value } = e.target

        setPreset(prev => {
            if (['addLimit'].includes(key)) {
                return {
                    ...prev,
                    details: {
                        ...(prev.details ?? {}),
                        snapsAdd: {
                            ...(prev.details?.snapsAdd ?? {}),
                            [key]: handleParseInt(value as string)
                        }
                    }
                }
            } else if (['declineQuickAdds'].includes(key)) {
                return {
                    ...prev,
                    details: {
                        ...(prev.details ?? {}),
                        snapsAdd: {
                            ...(prev.details?.snapsAdd ?? {}),
                            [key]: value
                        }
                    }
                }
            }

            return {
                ...prev,
                details: {
                    ...(prev.details ?? {}),
                    snapsAdd: {
                        ...(prev.details?.snapsAdd ?? {}),
                        [key]: {
                            ...(prev.details?.snapsAdd?.[key] ?? {}),
                            [name]: name === 'ranged' ? value : handleParseInt(value as string)
                        }
                    }
                }
            }
        })
    }

    const updateAddAcceptPerCycle = e => {
        updateSnapAddInfo('addAcceptedCycle', e)
    }

    const updateDelayPerCycle = e => {
        updateSnapAddInfo('delayPerCycle', e)
    }

    return (
        <div>
            <div className="absolute top-1 right-0">
                <Switch
                    id="default"
                    checked={snapsAdd?.enabledSnapAdd}
                    onCheckedChange={value => {
                        setPreset(prev => {
                            return {
                                ...prev,
                                details: {
                                    ...(prev.details ?? {}),
                                    snapsAdd: {
                                        ...(prev.details?.snapsAdd ?? {}),
                                        enabledSnapAdd: value
                                    }
                                }
                            }
                        })
                    }}
                />
            </div>
            <RunCycle />
            <div className=" p-3 bg-primary rounded-md">
                <div className="mb-8">
                    <CEInput
                        label="Daily Limit"
                        info={
                            <>
                                <p>Limit how many friend requests can be accepted daily.</p>
                                <p className="mt-8">
                                    Hint: Accepting 100 new active friend requests a day is best.
                                </p>
                            </>
                        }
                        suffix={'new request(s)'}
                        className="pr-[120px]"
                        type="number"
                        value={snapsAdd?.addLimit}
                        name="addLimit"
                        onChange={e => {
                            updateSnapAddInfo('addLimit', e)
                        }}
                    />
                    <div className="flex gap-1 mt-0.5 items-center">
                        <p>Today:</p>
                        <p>
                            {Object.keys(ownerDetails).length > 0 ? (
                                ownerDetails.snap_add_counter
                            ) : (
                                <Skeleton className="w-8 h-4" />
                            )}
                        </p>
                    </div>
                </div>
                <div className="text-base font-semibold leading-6 inline-flex items-center pb-2.5 gap-2">
                    <Label>Adds accepted per cycle</Label>
                    <Help label={'How many adds you want the bot to add in this cycle'} />
                </div>
                <CycleInput
                    suffix="friend(s)"
                    rateProps={{
                        name: 'addAcceptedCycleRate',
                        onChange: updateAddAcceptPerCycle,
                        defaultValue: snapsAdd?.addAcceptedCycle?.addAcceptedCycleRate
                    }}
                    minProps={{
                        name: 'addAcceptedCycleMin',
                        onChange: updateAddAcceptPerCycle,
                        defaultValue: snapsAdd?.addAcceptedCycle?.addAcceptedCycleMin
                    }}
                    maxProps={{
                        name: 'addAcceptedCycleMax',
                        onChange: updateAddAcceptPerCycle,
                        defaultValue: snapsAdd?.addAcceptedCycle?.addAcceptedCycleMax
                    }}
                    toggleProps={{
                        checked: snapsAdd?.addAcceptedCycle?.ranged ?? false,
                        onCheckedChange: value => {
                            updateAddAcceptPerCycle({ target: { name: 'ranged', value } })
                        }
                    }}
                />
                <div className="text-base font-semibold leading-6 inline-flex items-center pb-2.5 gap-2 mt-8">
                    <Label>Delay per add cycle</Label>
                </div>
                <CycleInput
                    suffix="minute(s)"
                    rateProps={{
                        name: 'delayPerCycleRate',
                        onChange: updateDelayPerCycle,
                        defaultValue: snapsAdd?.delayPerCycle?.delayPerCycleRate
                    }}
                    minProps={{
                        name: 'delayPerCycleMin',
                        onChange: updateDelayPerCycle,
                        defaultValue: snapsAdd?.delayPerCycle?.delayPerCycleMin
                    }}
                    maxProps={{
                        name: 'delayPerCycleMax',
                        onChange: updateDelayPerCycle,
                        defaultValue: snapsAdd?.delayPerCycle?.delayPerCycleMax
                    }}
                    toggleProps={{
                        checked: snapsAdd?.delayPerCycle?.ranged ?? false,
                        onCheckedChange: value => {
                            updateDelayPerCycle({ target: { name: 'ranged', value } })
                        }
                    }}
                />

                <div className="flex gap-2 items-center mt-8">
                    <Label>Decline Quick Adds</Label>{' '}
                    <Help label="Bot will not add quick add users" />
                    <div className="flex-grow" />
                    <Switch
                        checked={snapsAdd?.declineQuickAdds}
                        onCheckedChange={value => {
                            updateSnapAddInfo('declineQuickAdds', {
                                target: { name: 'declineQuickAdds', value: value }
                            })
                        }}
                    />
                </div>
            </div>
        </div>
    )
}

export default SnapAdds
