import { AccountOption, AccountType, TimeFrameOption, TimeFrameType } from '@/lib/constants'
import { AnalyticsType } from '@/lib/types/analytics.type'
import React, { useEffect, useState } from 'react'
import * as API from '@/scripts/api'
import { Table, TableBody, TableCell, TableHead, TableRow } from '@/components/ui/table'
import { Skeleton } from '@/components/ui/skeleton'
import { Label } from '@/components/ui/label'
import CESelect from '@/components/shared/ce-select'
import { useChatting } from '@/provider/chatting-provider'

const Analytics = () => {
    const { userMainInfo, selectedPreset } = useChatting()

    const { data: loggedInUser } = userMainInfo
    const [analytics, setAnalytics] = useState<AnalyticsType>({
        number_of_cta_link_sent: 0,
        number_of_conversation_not_cta_sent: 0,
        number_of_conversation_charged: 0,
        number_of_percentage_user_conversion: 0,
        number_of_converted_users: 0
    })
    const [loading, setLoading] = useState(true)
    const [selectedTimeFrame, setSelectedTimeFrame] = useState(TimeFrameType['all-time'])
    const [selectedAccount, setSelectedAccount] = useState(AccountType.all)

    const getAnalytics = async () => {
        setLoading(true)
        const response: any = await API.getCTAAnalytics({
            last_filter_day: Number(selectedTimeFrame),
            snapchat_account_owner_id:
                selectedAccount === AccountType.current ? loggedInUser?.mutable_username : '',
            select_preset_id: `${selectedPreset}`
        })

        if (response.status) {
            const data = response.analytics as AnalyticsType
            setAnalytics(data)
        } else {
            if (
                ['signal is aborted without reason', 'The user aborted a request.'].includes(
                    response.message
                )
            )
                return
            console.error('Unable to fetch user data in ')
        }
        setLoading(false)
    }

    useEffect(() => {
        if (userMainInfo.attemptFetch) {
            if (!loggedInUser) {
                console.error('Unable to fetch data logged in user in analytics')
                return
            }
            getAnalytics()
        }
    }, [selectedTimeFrame, selectedAccount, userMainInfo])

    const Placeholder = <Skeleton className="w-12 h-4" />

    return (
        <div>
            <p className="text-ce-gray-400 text-2xl font-medium pb-4">Analytics for</p>

            <div className="flex gap-2 mb-5">
                <CESelect
                    options={TimeFrameOption}
                    value={selectedTimeFrame}
                    onValueChange={value => setSelectedTimeFrame(value as TimeFrameType)}
                />
                <CESelect
                    options={AccountOption}
                    value={selectedAccount}
                    onValueChange={value => {
                        setSelectedAccount(value as AccountType)
                    }}
                />
            </div>
            <div>
                <Label className="text-md text-center mb-2.5 block">Analytics</Label>
                <Table>
                    <TableRow>
                        <TableHead>Metric</TableHead>
                        <TableHead>
                            {TimeFrameOption.find(i => i.value === selectedTimeFrame).label}
                        </TableHead>
                    </TableRow>
                    <TableBody>
                        <TableRow>
                            <TableCell className="font-medium">Conversations Charged</TableCell>
                            <TableCell>
                                {loading ? Placeholder : analytics.number_of_conversation_charged}
                            </TableCell>
                        </TableRow>
                        <TableRow>
                            <TableCell className="font-medium">CTA phase not started</TableCell>
                            <TableCell>
                                {loading
                                    ? Placeholder
                                    : analytics.number_of_conversation_not_cta_sent}
                            </TableCell>
                        </TableRow>
                        <TableRow>
                            <TableCell className="font-medium">Shared CTA link</TableCell>
                            <TableCell>
                                {loading ? Placeholder : analytics.number_of_cta_link_sent}
                            </TableCell>
                        </TableRow>
                        <TableRow>
                            <TableCell className="font-medium">Conversions</TableCell>
                            <TableCell>
                                {loading
                                    ? Placeholder
                                    : `${analytics.number_of_converted_users} (${analytics.number_of_percentage_user_conversion.toFixed(1)} %)`}
                            </TableCell>
                        </TableRow>
                    </TableBody>
                </Table>
            </div>
        </div>
    )
}

export default Analytics
