import React, { useState } from 'react'
import { Switch } from '@/components/ui/switch'
import CEInput from '@/components/shared/ce-input'

type propType = {
    suffix: string
    minProps: React.ComponentProps<typeof CEInput>
    maxProps: React.ComponentProps<typeof CEInput>
    rateProps: React.ComponentProps<typeof CEInput>
    toggleProps: React.ComponentProps<typeof Switch>
}

const CycleInput = (props: propType) => {
    const { suffix, maxProps, minProps, rateProps, toggleProps } = props
    
    return (
        <div>
            {!toggleProps.checked ? (
                <CEInput suffix={suffix} className="pr-16" type="number" {...rateProps} />
            ) : (
                <div className="flex gap-5 justify-between mt-3">
                    <CEInput
                        label="min range"
                        suffix={suffix}
                        className="pr-[72px]"
                        type="number"
                        {...minProps}
                    />

                    <CEInput
                        label="max range"
                        suffix={suffix}
                        className="pr-[72px]"
                        type="number"
                        {...maxProps}
                    />
                </div>
            )}

            <div className="flex justify-end items-center gap-2 mt-2">
                <span className="text-white text-sm font-medium">Range</span>
                <Switch {...toggleProps} />
            </div>
        </div>
    )
}

export default CycleInput
