import SectionHeader from '@/components/shared/section-header'
import { Separator } from '@/components/ui/separator'
import { PresetCtaInfoType, CtaSetType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import React from 'react'
import MultipleLinks from './multiple-links'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { cloneDeep } from 'lodash'
import Help from '@/components/shared/help'
import { DEFAULT_CTA_INFO } from '@/lib/defaultPresetsValue'
import { cn } from '@/lib/utils'

const CTALink = () => {
    const { preset, setPreset } = useChatting()
    const { details = {} } = preset
    const { cta = {} } = details
    const { ctaSet = {} as CtaSetType } = cta
    const { sendRandomCta = false, ctaInfo } = ctaSet

    const ctaInfoInValid = ctaInfo?.filter(i => !i.link.trim() || !i.platform.trim()).length > 0

    const updateCTAInfo = (key: keyof CtaSetType, value: string | number | boolean) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                cta: {
                    ...(prev.details?.cta ?? {}),

                    ctaSet: {
                        ...(prev.details?.cta?.ctaSet ?? {}),
                        [key]: value
                    } as CtaSetType
                }
            }
        }))
    }

    const deleteCTAInfo = (id: string) => {
        setPreset(prev => {
            const details = prev.details
            return {
                ...prev,
                details: {
                    ...(details ?? {}),
                    cta: {
                        ...(details?.cta ?? {}),
                        ctaSet: {
                            ...(details?.cta?.ctaSet ?? {}),
                            ctaInfo: details?.cta?.ctaSet?.ctaInfo.filter(i => i.id !== id),
                            activeCta: details?.cta?.ctaSet.activeCta < details?.cta?.ctaSet?.ctaInfo.length - 1 ? details?.cta?.ctaSet.activeCta: details?.cta?.ctaSet.activeCta -1
                        } as CtaSetType
                    }
                }
            }
        })
    }

    const addCTAInfo = () => {
        if (ctaInfoInValid) {
            return
        }
        setPreset(prev => {
            const details = prev.details
            return {
                ...prev,
                details: {
                    ...(details ?? {}),
                    cta: {
                        ...(details?.cta ?? {}),
                        ctaSet: {
                            ...(details?.cta?.ctaSet ?? {}),
                            ctaInfo: [...(details?.cta?.ctaSet?.ctaInfo ?? []), DEFAULT_CTA_INFO()]
                        } as CtaSetType
                    }
                }
            }
        })
    }

    const updateCTA = (id: string, key: keyof PresetCtaInfoType, value: string) => {
        setPreset(prev => {
            const details = prev.details
            const { ctaSet } = details?.cta
            const { ctaInfo } = ctaSet
            const updatedCTA = cloneDeep(ctaInfo)
            const index = updatedCTA.findIndex(i => i.id === id)
            updatedCTA[index][key] = value
            return {
                ...prev,
                details: {
                    ...(details ?? {}),
                    cta: {
                        ...(details?.cta ?? {}),
                        ctaSet: {
                            ...(details?.cta?.ctaSet ?? {}),
                            ctaInfo: updatedCTA
                        } as CtaSetType
                    }
                }
            }
        })
    }

    return (
        <div className="bg-primary rounded-md">
            <div className={cn(ctaInfoInValid ? 'border border-venetian-red rounded-md' : '')}>
                <SectionHeader label="CTA Link" />
                <Separator />

                <MultipleLinks
                    updateCTAInfo={updateCTAInfo}
                    value={ctaSet}
                    addCTAInfo={addCTAInfo}
                    deleteCTAInfo={deleteCTAInfo}
                    updateCTA={updateCTA}
                />
            </div>
            <div className="flex items-center gap-2 p-3">
                <Label htmlFor="random-cta">Randomize Link</Label>
                <Help label="AI will choose a random CTA to send" />
                <div className="flex-grow" />
                <Switch
                    id="random-cta"
                    checked={sendRandomCta}
                    onCheckedChange={value => {
                        updateCTAInfo('sendRandomCta', value)
                    }}
                />
            </div>
        </div>
    )
}

export default CTALink
