import { purposeOptions, PurposeType, SnapTimeType } from '@/lib/constants'
import { useChatting } from '@/provider/chatting-provider'
import React, { useState } from 'react'
import CESelect from '@/components/shared/ce-select'
import PreviewSnaps from './preview-snap'
import UploadFile from '@/components/content/upload-file'
import { DraftSnapType } from '@/lib/types/preset.type'
import DraftSnap from './draft-snap'
import CEButton from '@/components/shared/ce-button'

const Snaps = () => {
    const { preset } = useChatting()
    const { details } = preset
    const { snaps = [] } = details
    const [newSnaps, setNewSnaps] = useState<DraftSnapType[]>([])
    const [snapPurpose, setSnapPurpose] = useState(PurposeType.MAIN)

    return newSnaps.length > 0 ? (
        <DraftSnap snaps={newSnaps} setSnaps={setNewSnaps} />
    ) : (
        <div className="flex flex-col gap-5">
            <UploadFile
                onProcessImage={images => {
                    setNewSnaps(
                        images.map(i => ({
                            ...i,
                            lightning: SnapTimeType.NIGHT_TIME,
                            purpose: snapPurpose
                        }))
                    )
                }}
            >
                <CEButton className="w-full">Upload Media</CEButton>
            </UploadFile>

            <div className="flex gap-2">
                <CESelect
                    options={purposeOptions}
                    value={snapPurpose}
                    onValueChange={value => setSnapPurpose(value as PurposeType)}
                />
            </div>

            <div className="flex flex-wrap gap-2">
                {snaps
                    .filter(i => i.purpose === snapPurpose)
                    .map(i => (
                        <PreviewSnaps key={i.id} snap={i} />
                    ))}
            </div>
        </div>
    )
}

export default Snaps
