import React, { useEffect, useRef, useState } from 'react'
import SelectStoryImage from './select-story-image'
import { Badge } from '@/components/ui/badge'
import CEInput from '@/components/shared/ce-input'
import CESelect from '@/components/shared/ce-select'
import CEButton from '@/components/shared/ce-button'
import { Copy, Trash2 } from 'lucide-react'
import { StoryType } from '@/lib/types/stories.type'
import { useChatting } from '@/provider/chatting-provider'
import dayjs from '@/lib/dayjs'
import * as API from '@/scripts/api'
import { UpdateStoryParamsType } from '@/scripts/api/types/params.type'
import { deviceTimeZone } from '@/lib/common'
import { debounce } from 'lodash'
import { STORY_ACTION_LOADING } from '..'
import Spinner from '@/components/shared/spinner'
import { cn } from '@/lib/utils'
import { StoryStatus } from '@/lib/constants'

type propType = {
    story: StoryType
    setLoading: React.Dispatch<
        React.SetStateAction<{
            [key: number]: STORY_ACTION_LOADING
        }>
    >
    loading: {
        [key: number]: STORY_ACTION_LOADING
    }
    refetchStories: () => void
    currentBotDay: string
}

const handleGetNext30Days = (currentBotDay: number, selectedDay: number) => {
    const options: { value: string; label: string }[] = []
    if (selectedDay < currentBotDay) {
        options.push({ value: String(selectedDay), label: `Day ${selectedDay}` })
    }
    for (let i = 0; i < 30; i++) {
        options.push({
            value: String(currentBotDay + i),
            label: `Day ${currentBotDay + i}`
        })
    }

    return options
}

const configureStatus = (activationDate: string, postOn: string, postAt: string) => {
    const utcTime = dayjs(activationDate).utc()

    let postOnDate = utcTime.add(Number(postOn), 'days')
    const [hours, minutes] = dayjs.utc(postAt).format('HH:mm').split(':').map(Number)

    postOnDate = postOnDate.set('hours', hours)
    postOnDate = postOnDate.set('minutes', minutes)

    const now = dayjs.utc()

    const diffInMinutes = postOnDate.diff(now, 'minute')

    if (diffInMinutes < 0 && diffInMinutes > -30) {
        // return pending if past but is not more than 30 minutes yet
        return StoryStatus.PENDING
    } else if (diffInMinutes <= -30) {
        return StoryStatus.SKIPPED // skipped if is more than 30 minutes
    } else {
        return StoryStatus.PENDING // you can return this if the postOnDate is in the future
    }
}

const Story = (props: propType) => {
    const { story, loading, setLoading, refetchStories, currentBotDay } = props
    const { preset, userMainInfo, selectedPreset } = useChatting()
    const { details } = preset
    const { timezone } = details ?? {}
    const { id, caption, media_url, schedule_date, status } = story
    const getCurrentDay = Math.abs(dayjs(currentBotDay).utc().diff(dayjs.utc(), 'days')) + 1
    const getScheduleDay = Math.abs(dayjs(schedule_date).utc().diff(currentBotDay, 'days')) + 1
    const userTimezone = !!timezone ? timezone : deviceTimeZone
    const [postOn, setPostOn] = useState(String(getScheduleDay))
    const [postAt, setPostAt] = useState(schedule_date)
    const [stroyCaption, setStoryCaption] = useState(caption)
    const [media, setMedia] = useState(media_url)
    const [storyStatus, setStoryStatus] = useState(status)
    const options = handleGetNext30Days(getCurrentDay, getScheduleDay)
    const captionUpdatePrevention = useRef(false)
    const postAtUpdatePrevention = useRef(false)

    const handleUpdateStory = async (value: Partial<UpdateStoryParamsType>) => {
        await API.updateStory({
            owner_id: userMainInfo.data.mutable_username,
            select_preset_id: selectedPreset,
            story_id: id,
            ...value
        })
    }

    const handleUpdateMediaUrl = (media: string) => {
        setMedia(media)
        const status = configureStatus(currentBotDay, postOn, postAt)
        setStoryStatus(status)
        handleUpdateStory({ media_url: media, status })
    }

    const handleChangeTime = (e: React.ChangeEvent<HTMLInputElement>) => {
        const timeValue = e.target.value
        const [hours, minutes] = timeValue.split(':').map(Number)
        const userTime = dayjs()
            .tz(userTimezone)
            .hour(hours)
            .minute(minutes)
            .second(0)
            .millisecond(0)

        const utcTime = userTime.utc()
        const formattedTime = utcTime.format('YYYY-MM-DDTHH:mm:ss[Z]')

        setPostAt(formattedTime)
    }

    const handleChangeDay = (value: string) => {
        const status = configureStatus(currentBotDay, value, postAt)
        setPostOn(value)
        setStoryStatus(status)
        handleUpdateStory({ schedule_date_number: Number(value), status: status })
    }

    const handleChangeCaption = (e: React.ChangeEvent<HTMLInputElement>) => {
        setStoryCaption(e.target.value)
    }

    const updatePostAt = debounce(async () => {
        const currentPostAt = postAt
        const status = configureStatus(currentBotDay, postOn, currentPostAt)
        setStoryStatus(status)
        handleUpdateStory({ schedule_time: postAt, status: status })
    }, 500)

    useEffect(() => {
        if (!postAtUpdatePrevention.current) {
            postAtUpdatePrevention.current = true
            return
        }
        updatePostAt()
        return () => {
            updatePostAt.cancel()
        }
    }, [postAt])

    const updateCaption = debounce(async () => {
        handleUpdateStory({ caption: stroyCaption })
    }, 500)

    useEffect(() => {
        if (!captionUpdatePrevention.current) {
            captionUpdatePrevention.current = true
            return
        }
        updateCaption()
        return () => {
            updateCaption.cancel()
        }
    }, [stroyCaption])

    const handleCopyStory = async () => {
        setLoading({ [id]: STORY_ACTION_LOADING.COPY })
        const res = await API.duplicateStory({
            owner_id: userMainInfo.data.mutable_username,
            story_id: id
        })
        if (res.status) {
            refetchStories()
        } else {
            setLoading(undefined)
            console.error('Error while duplicating story')
        }
    }

    const handleDeleteStory = async () => {
        setLoading({ [id]: STORY_ACTION_LOADING.DELETE })
        const res = await API.deleteStory({
            owner_id: userMainInfo.data.mutable_username,
            story_id: id
        })
        if (res.status) {
            refetchStories()
        } else {
            setLoading(undefined)
            console.error('Error while deleting story')
        }
    }

    const storyState = !media || !postOn || !postAt ? StoryStatus.INCOMPLETE : storyStatus

    return (
        <div className="bg-primary p-3 rounded-md">
            <div className="flex gap-4">
                <SelectStoryImage
                    media={media}
                    onChange={media => {
                        handleUpdateMediaUrl(media)
                    }}
                />
                <Badge
                    className={cn(
                        'h-fit capitalize',
                        storyState === StoryStatus.SENT && 'bg-green hover:bg-green/80',
                        storyState === StoryStatus.PENDING &&
                            'bg-yellow-600 hover:bg-yellow-600/80',
                        storyState === StoryStatus.SKIPPED &&
                            'bg-venetian-red hover:bg-venetian-red/80'
                    )}
                >
                    {storyState}
                </Badge>
            </div>
            <div className="flex flex-col gap-5 mt-5">
                <CESelect
                    value={postOn}
                    label="Post On"
                    options={options}
                    onValueChange={handleChangeDay}
                />
                <div>
                    <CEInput
                        label="Post At"
                        type="time"
                        value={dayjs(postAt).tz(userTimezone).format('HH:mm')}
                        className="relative story-schedule"
                        onChange={handleChangeTime}
                    />
                    <span className="text-ce-gray-500 text-sm">{userTimezone}</span>
                </div>
                <CEInput label="Caption" value={stroyCaption} onChange={handleChangeCaption} />
                <div className="flex items-center gap-2">
                    <CEButton
                        className="bg-slate-800 text-white hover:bg-slate-800/90 flex-1"
                        size="sm"
                        variant="secondary"
                        disabled={!!loading}
                        onClick={handleCopyStory}
                    >
                        {loading?.[id] === STORY_ACTION_LOADING.COPY ? (
                            <Spinner />
                        ) : (
                            <Copy size={18} />
                        )}
                    </CEButton>
                    <CEButton
                        className="bg-slate-800 text-white hover:bg-slate-800/90"
                        size="sm"
                        variant="secondary"
                        disabled={!!loading}
                        onClick={handleDeleteStory}
                    >
                        {loading?.[id] === STORY_ACTION_LOADING.DELETE ? (
                            <Spinner />
                        ) : (
                            <Trash2 size={18} />
                        )}
                    </CEButton>
                </div>
            </div>
        </div>
    )
}

export default Story
