import * as React from 'react'
import { Label } from '../ui/label'
import Help from './help'
import { Input } from '../ui/input'
import { handleKeyDownOnIntegerInput } from '@/lib/common'

type propType = {
    label?: string
    info?: React.ReactNode
    error?: React.ReactNode
    htmlFor?: string
    suffix?: React.ReactNode
    prefix?: React.ReactNode
} & Omit<React.ComponentProps<typeof Input>, 'prefix'>

const CEInput = React.forwardRef<HTMLInputElement, propType>(
    (props: propType, ref: React.ForwardedRef<HTMLInputElement>) => {
        const { error, info, label, htmlFor, suffix, prefix, type = 'text', ...rest } = props

        const extraInputProps: React.ComponentProps<typeof Input> = {}

        if (type === 'number') {
            extraInputProps.onKeyDown = handleKeyDownOnIntegerInput
            extraInputProps.min = '0'
        }

        return (
            <div className="flex flex-col flex-1">
                {label ? (
                    <div className="flex gap-1 mb-2.5 items-center">
                        <Label htmlFor={htmlFor}>{label}</Label>
                        {info && <Help label={info} />}
                    </div>
                ) : null}
                <div className="relative flex items-center">
                    {prefix && <div className="absolute left-2 flex items-center">{prefix}</div>}
                    <Input id={htmlFor} type={type} {...extraInputProps} {...rest} ref={ref} />
                    {suffix && <div className="absolute right-2 flex items-center">{suffix}</div>}
                </div>

                {error && <p className="text-venetian-red text-sm mt-0.5">{error}</p>}
            </div>
        )
    }
)

export default CEInput
