import SnapPreview from '@/components/content/snap-preview'
import CEInput from '@/components/shared/ce-input'
import CESelect from '@/components/shared/ce-select'
import { Button } from '@/components/ui/button'
import {
    DescriptionInputEnabledForList,
    OutfitOptions,
    OutfitSelectableForList,
    purposeOptions,
    PurposeType,
} from '@/lib/constants'
import { DraftSnapType, LiveSnapType } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import { Trash2 } from 'lucide-react'
import React, { useState } from 'react'
import { cloneDeep } from 'lodash'
import * as API from '@/scripts/api/index'
import CEButton from '@/components/shared/ce-button'
import { ScrollArea, ScrollBar } from '@/components/ui/scroll-area'
import { cn } from '@/lib/utils'
import ClearableSelect from '@/components/shared/clearable-select'

type propType = {
    snaps: DraftSnapType[]
    hidePurpose?: boolean
    setSnaps: React.Dispatch<React.SetStateAction<DraftSnapType[]>>
}

const DraftSnap = (props: propType) => {
    const { setPreset } = useChatting()
    const { snaps, hidePurpose = false, setSnaps } = props
    const [loading, setLoading] = useState(false)

    const handleDeleteSnap = async (id: string) => {
        setSnaps(prev => prev.filter(i => i.id !== id))
    }

    const updateSnap = (id: string, key: keyof DraftSnapType, value: string) => {
        setSnaps(prev => {
            const snaps = cloneDeep(prev)
            const snapIndex = snaps.findIndex(i => i.id === id)
            const updatedSnap: DraftSnapType = {
                ...snaps[snapIndex],
                [key]: value
            }

            snaps.splice(snapIndex, 1, updatedSnap)

            return snaps
        })
    }

    const handleUploadSnaps = async () => {
        const snapsObjects = async (i: DraftSnapType) => {
            const res = await API.uploadSnap(i.file)
            if (res.status) {
                const snap: LiveSnapType = {
                    id: i.id,
                    lightning: i.lightning,
                    purpose: i.purpose,
                    snapUrl: res.data,
                    description: i.description,
                    outfit: i.outfit
                }
                return snap
            } else {
                return false
            }
        }

        const uploadedSnaps = await Promise.all(
            snaps.map(async i => {
                return await snapsObjects(i)
            })
        )

        return uploadedSnaps.filter(i => typeof i !== 'boolean') as LiveSnapType[]
    }

    const saveSnap = async () => {
        setLoading(true)
        const savedSnaps = await handleUploadSnaps()
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                snaps: [...(prev.details?.snaps ?? []), ...savedSnaps]
            }
        }))
        setSnaps([])
        setLoading(false)
    }

    const disableSave = snaps.findIndex(
        i => DescriptionInputEnabledForList.some(pt => pt === i.purpose) && !i.description?.trim()
    )

    return (
        <div className="flex flex-col gap-5">
            <ScrollArea className="whitespace-nowrap rounded-md">
                <div className="flex w-max space-x-2 py-2">
                    {snaps.map(i => {
                        const outfitSelectable = OutfitSelectableForList.some(
                            pt => pt === i.purpose
                        )
                        // boolean to indicate whether show description input or not
                        const descriptionInputEnabled = DescriptionInputEnabledForList.some(
                            pt => pt === i.purpose
                        )

                        return (
                            <div
                                className="min-w-[108px] flex flex-col border rounded border-slate-800"
                                key={i.id}
                            >
                                <Button
                                    variant="destructive"
                                    className="h-6 w-full rounded-t rounded-b-none"
                                    onClick={() => {
                                        handleDeleteSnap(i.id)
                                    }}
                                >
                                    <Trash2 size={16} />
                                </Button>
                                <SnapPreview src={i.base64} />

                                <div className="flex gap-1 flex-col p-1 flex-1">
                                    {!hidePurpose ? (
                                        <CESelect
                                            options={purposeOptions}
                                            value={i.purpose}
                                            onValueChange={value =>
                                                updateSnap(i.id, 'purpose', value as PurposeType)
                                            }
                                            triggerProps={{ className: 'w-[100px]', size: 'sm' }}
                                        />
                                    ) : null}
                                    {i.purpose !== PurposeType.STORY ? (
                                        <>
                                            {outfitSelectable ? (
                                                <ClearableSelect
                                                    options={OutfitOptions}
                                                    value={i.outfit}
                                                    onValueChange={value =>
                                                        updateSnap(i.id, 'outfit', value)
                                                    }
                                                    triggerProps={{
                                                        className: 'w-[100px]',
                                                        size: 'sm'
                                                    }}
                                                />
                                            ) : null}

                                            {descriptionInputEnabled ? (
                                                <CEInput
                                                    value={i.description}
                                                    onChange={e =>
                                                        updateSnap(
                                                            i.id,
                                                            'description',
                                                            e.target.value
                                                        )
                                                    }
                                                    placeholder="Description"
                                                    size="sm"
                                                    className={cn(
                                                        'w-[100px]',
                                                        !i.description?.trim()
                                                            ? 'border-venetian-red focus-visible:ring-venetian-red'
                                                            : ''
                                                    )}
                                                />
                                            ) : null}
                                        </>
                                    ) : (
                                        <></>
                                    )}
                                </div>
                            </div>
                        )
                    })}
                </div>
                <ScrollBar orientation="horizontal" />
            </ScrollArea>
            <CEButton
                className="w-full"
                onClick={() => {
                    saveSnap()
                }}
                disabled={disableSave > -1}
                submitting={loading}
            >
                Save
            </CEButton>
        </div>
    )
}

export default DraftSnap
