import React from 'react'
import CTALink from './cta-link'
import { useChatting } from '@/provider/chatting-provider'
import FinalStaticMessage from './final-static-message'
import SectionHeader from '@/components/shared/section-header'
import { Separator } from '@/components/ui/separator'
import { ChattingSectionType, CTAS_TAB } from '@/lib/constants'
import SectionTab from '@/components/shared/section-tab'
import { cloneDeep } from 'lodash'
import { Label } from '@/components/ui/label'
import Help from '@/components/shared/help'
import { Switch } from '@/components/ui/switch'
import { PresetCtaType } from '@/lib/types/preset.type'

const CTA = () => {
    const { preset, setPreset, openSectionStack, inCompletePresetSection, setOpenSectionStack } =
        useChatting()

    const { details = {} } = preset
    const { cta = {} } = details

    const updateCTAInfo = (key: keyof PresetCtaType, value: boolean) => {
        setPreset(prev => ({
            ...prev,
            details: {
                ...(prev.details ?? {}),
                cta: {
                    ...(prev.details?.cta ?? {}),
                    [key]: value
                }
            }
        }))
    }

    if (openSectionStack.includes(ChattingSectionType.CTA_LINKS)) {
        return (
            <div className="flex flex-col gap-6">
                <CTALink />
            </div>
        )
    }

    return (
        <div className="flex flex-col gap-6">
            <div className="flex flex-col rounded-md bg-primary">
                <SectionHeader label="Links" />
                <Separator />
                <div className="p-3">
                    {CTAS_TAB.map((i, index) => (
                        <SectionTab
                            prefixIcon={
                                <i.icon
                                    fill={
                                        inCompletePresetSection.includes(
                                            i.value as keyof typeof ChattingSectionType
                                        )
                                            ? '#C41C1C'
                                            : '#0975F1'
                                    }
                                />
                            }
                            onClick={() => {
                                setOpenSectionStack(prev => {
                                    const newPrev = cloneDeep(prev)
                                    newPrev.push(i.value)
                                    return newPrev
                                })
                            }}
                            className="bg-slate-950 p-2"
                            hideSeparator={index === CTAS_TAB.length - 1}
                            key={i.value}
                        >
                            {i.name}
                        </SectionTab>
                    ))}
                </div>
            </div>
            
            {/* <CTAMessage /> */}
            <FinalStaticMessage />
        </div>
    )
}

export default CTA
