import React, { useState } from 'react'

import LicenseKey from './license-key'
import Info from './info'
import Preset from './preset'
import CTA from './cta'
import Snaps from './snap'
import Layout from './layout'

const StartingGuide = () => {
    const [currentStep, setCurrentStep] = useState(1)

    const handleBack = () => {
        setCurrentStep(prev => prev - 1)
    }

    const handleNext = () => {
        setCurrentStep(prev => prev + 1)
    }

    return (
        <>
            <div className="pb-7 pt-3 text-center">
                <p className="text-blue-primary text-lg font-medium italic">Step {currentStep}/5</p>
            </div>
            {currentStep === 1 ? (
                <LicenseKey onNext={handleNext} />
            ) : (
                <Layout currentStep={currentStep} onBack={handleBack} onNext={handleNext}>
                    {currentStep === 2 ? <Info /> : null}
                    {currentStep === 3 ? <Preset /> : null}
                    {currentStep === 4 ? <CTA /> : null}
                    {currentStep === 5 ? <Snaps /> : null}
                    {/* {currentStep === 6 ? <ChattingStyle /> : null} */}
                </Layout>
            )}
        </>
    )
}

export default StartingGuide
