import React, { useCallback, useEffect, useMemo, useRef } from 'react'
import { waitForElementTillLoad } from '@/lib/common'
import ReactDOM from 'react-dom'
import { ChattingOverlayProvider, useChattingOverlay } from '@/provider/chatting-overlay-provider'
import StatePopover from './state-popover'
import { isEqual } from 'lodash'
import { ServiceMessageName } from '@/lib/constants'
import { messageParamsType } from '@/lib/types/chatting-overlay.type'
import ToggleAllChatting from './toggle-all-chatting'

const ChattingOverlayWrapper = ({ uuid, container, userDisplayName }) => {
    const {
        userStatus,
        userMainInfo,
        toggleIncludeInAnalytics,
        togglePauseChatting,
        markUserAsConverted,
        userStatusFetchSuccessfully
    } = useChattingOverlay()
    const status = useMemo(() => userStatus.find(i => i.ruid === uuid), [userStatus, uuid])
    const statusRef = useRef(undefined)

    const memoizedToggleIncludeInAnalytics = useCallback(() => {
        toggleIncludeInAnalytics(uuid)
    }, [toggleIncludeInAnalytics, uuid])

    const memoizedTogglePauseChatting = useCallback(() => {
        togglePauseChatting(uuid)
    }, [toggleIncludeInAnalytics, uuid])

    const memoizedMarkUserAsConverted = useCallback(() => {
        markUserAsConverted(uuid)
    }, [markUserAsConverted, uuid])

    useEffect(() => {
        if (!userStatusFetchSuccessfully) return
        if (statusRef.current && isEqual(status, statusRef.current)) return

        statusRef.current = status
        ReactDOM.render(
            <StatePopover
                uuid={uuid}
                userDisplayName={userDisplayName}
                status={status}
                userMainInfo={userMainInfo}
                toggleIncludeInAnalytics={memoizedToggleIncludeInAnalytics}
                markUserAsConverted={memoizedMarkUserAsConverted}
                togglePauseChatting={memoizedTogglePauseChatting}
            />,
            container
        )

        return () => {
            if (statusRef.current && isEqual(status, statusRef.current)) return
            ReactDOM.unmountComponentAtNode(container)
        }
    }, [
        uuid,
        container,
        status,
        memoizedToggleIncludeInAnalytics,
        memoizedMarkUserAsConverted,
        memoizedTogglePauseChatting,
        userStatusFetchSuccessfully,
        userDisplayName
    ])

    return null
}

const AllToggleChatting = ({ container }) => {
    const {
        userMainInfo,
        setRefetchAllConversations,
        userStatusFetchSuccessfully,
        disableAllChatting,
        setDisableAllChatting
    } = useChattingOverlay()

    useEffect(() => {
        if (!userStatusFetchSuccessfully) return
        ReactDOM.render(
            <ToggleAllChatting
                disableAllChatting={disableAllChatting}
                setDisableAllChatting={setDisableAllChatting}
                userMainInfo={userMainInfo}
                setRefetchAllConversations={setRefetchAllConversations}
            />,
            container
        )

        return () => {
            ReactDOM.unmountComponentAtNode(container)
        }
    }, [
        container,
        disableAllChatting,
        setDisableAllChatting,
        userMainInfo,
        userStatusFetchSuccessfully,
        setRefetchAllConversations
    ])
    return null
}

const ChattingOverlay = () => {
    const previousUUIDs = useRef([])
    const uuidContainerMap = useRef(new Map())
    const newChatAdded = useRef(false)

    const injectChatStateOverlay = () => {
        const feedUserListClass =
            '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'
        const listItems = document.querySelectorAll(feedUserListClass)

        let overlayContainer = document.getElementById('chattingStateOverlayContainer')
        if (!overlayContainer) {
            overlayContainer = document.createElement('div')
            overlayContainer.setAttribute('id', 'chattingStateOverlayContainer')
            document.body.appendChild(overlayContainer)
        }

        const currentUUIDs = []
        const overlayElements = []

        listItems.forEach(item => {
            const infoElement = item.querySelector('.BbZFb') as HTMLDivElement
            infoElement.style.position = 'relative'

            const userDisplayNameElement = item.querySelector('.mYSR9.nonIntl')
            const uniqueUserId = userDisplayNameElement.getAttribute('id')
            const uuid = uniqueUserId.substring('title-'.length)
            currentUUIDs.push(uuid)

            const displayNameInnerElements: NodeListOf<HTMLSpanElement> =
                item.querySelectorAll('.FiLwP .nonIntl')

            // groupname will have displayNameInnerElements length 0 or more than 1
            if (
                displayNameInnerElements.length !== 1 ||
                displayNameInnerElements[0]?.innerText === 'My AI' ||
                displayNameInnerElements[0]?.innerText === 'Team Snapchat'
            ) {
                // don't push node
            } else {
                if (!uuidContainerMap.current.has(uuid)) {
                    const container = document.createElement('div')
                    container.setAttribute('id', `chattingState-${uuid}`)
                    container.style.marginLeft = '10px'
                    container.style.position = 'absolute'
                    container.style.right = '-10px'
                    container.style.bottom = '5px'
                    infoElement.appendChild(container)

                    overlayElements.push({
                        container,
                        uuid,
                        userDisplayName: displayNameInnerElements[0]?.innerText
                    })
                    uuidContainerMap.current.set(uuid, container)
                } else {
                    overlayElements.push({
                        container: uuidContainerMap.current.get(uuid),
                        uuid,
                        userDisplayName: displayNameInnerElements[0]?.innerText
                    })
                }
            }
        })

        // Check for removed UUIDs and clear their containers
        const removedUUIDs = previousUUIDs.current.filter(uuid => !currentUUIDs.includes(uuid))
        removedUUIDs.forEach(uuid => {
            const container = uuidContainerMap.current.get(uuid)
            if (container) {
                ReactDOM.unmountComponentAtNode(container)
                uuidContainerMap.current.delete(uuid)
            }
        })

        let toggleAllChattingContainer
        const userIconContainer = document.querySelector('.BL7do .XlW_1 .AbUJt') as HTMLDivElement

        if (userIconContainer) {
            toggleAllChattingContainer = document.querySelector('#toggle-all-chatting')
            if (!toggleAllChattingContainer) {
                toggleAllChattingContainer = document.createElement('div')
                toggleAllChattingContainer.setAttribute('id', 'toggle-all-chatting')
                userIconContainer.append(toggleAllChattingContainer)
                userIconContainer.style.display = 'flex'
                userIconContainer.style.alignItems = 'center'
                userIconContainer.style.gap = '6px'
            }
        }

        // Only update if the current UUIDs are different from the previous ones
        if (!isEqual(currentUUIDs.sort(), previousUUIDs.current.sort()) || newChatAdded.current) {
            ReactDOM.render(
                <ChattingOverlayProvider>
                    {userIconContainer && (
                        <AllToggleChatting container={toggleAllChattingContainer} />
                    )}
                    {overlayElements.map(overlay => (
                        <ChattingOverlayWrapper
                            key={overlay.uuid}
                            uuid={overlay.uuid}
                            container={overlay.container}
                            userDisplayName={overlay.userDisplayName}
                        />
                    ))}
                </ChattingOverlayProvider>,
                overlayContainer
            )
            newChatAdded.current = false
        }

        previousUUIDs.current = currentUUIDs
    }

    useEffect(() => {
        let observer

        const setObserver = async () => {
            await waitForElementTillLoad('.ReactVirtualized__Grid__innerScrollContainer')
            const feedContainer = document.querySelector(
                '.ReactVirtualized__Grid__innerScrollContainer'
            )
            if (feedContainer) {
                observer = new MutationObserver(() => {
                    injectChatStateOverlay()
                })

                observer.observe(feedContainer, { childList: true, subtree: true })
            }
        }
        setObserver()

        return () => {
            if (observer) {
                observer.disconnect()
            }
        }
    }, [])

    const handleMessage = React.useCallback(() => {
        return message => {
            if (message.action === ServiceMessageName.ChatOverLay) {
                const param = message.data.params as messageParamsType['data']
                const { uuid, state } = param

                if (state === 'Main Phase') {
                    newChatAdded.current = true
                }
            }
        }
    }, [])

    React.useEffect(() => {
        const messageHandler = handleMessage()
        chrome.runtime.onMessage.addListener(messageHandler)

        return () => {
            chrome.runtime.onMessage.removeListener(messageHandler)
        }
    }, [handleMessage])

    return null
}

export default ChattingOverlay
