import React from 'react'
import { cn } from '@/lib/utils'
import { Separator } from '../ui/separator'

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
    prefixIcon?: React.ReactNode
    hideSeparator?: boolean
}

const SectionTab = ({
    children,
    prefixIcon,
    hideSeparator = false,
    className = '',
    ...props
}: ButtonProps) => {
    return (
        <button
            className={cn(
                'text-ce=gray-400 w-full hover:text-blue-primary disabled:hover:text-ce-gray-400 group flex items-start gap-x-3 rounded-md pb-2.5 text-base leading-5 font-medium ',
                className
            )}
            {...props}
        >
            {!!prefixIcon && prefixIcon}
            <div className="w-full flex items-center flex-col h-full">
                <div className="inline-flex h-[34px] items-center justify-between w-full">
                    <span>{children}</span>
                    <img
                        src={chrome.runtime.getURL('./assets/svg/arrow-right.svg')}
                        alt="arrow"
                        className="h-2.5"
                    />
                </div>
                {!hideSeparator && <Separator className="mt-2.5 " />}
            </div>
        </button>
    )
}

export default SectionTab
