import CEInput from '@/components/shared/ce-input'
import { useGetStarted } from '@/provider/get-started-provider'
import React, { useEffect, useRef, useState } from 'react'
import { authStore } from '@/scripts/store'
import { debounce } from 'lodash'
import CEButton from '@/components/shared/ce-button'
import Spinner from '@/components/shared/spinner'
import { cn } from '@/lib/utils'

type propType = {
    onNext: () => void
}

const LicenseKey = (props: propType) => {
    const { onNext } = props
    const { licenseKey, setLicenseKey } = useGetStarted()
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState('')
    const firstRender = useRef(false)

    const getFilteredBusiness = debounce(async () => {
        setLoading(true)
        const res = await authStore.validateLicenseKey(licenseKey.key)
        if (res && licenseKey.key) {
            setLicenseKey(prev => ({ ...prev, isValid: true }))
            setError('')
        } else if (!res && licenseKey.key.trim()) {
            setError('Incorrect license key')
        }
        setLoading(false)
        firstRender.current = true
    }, 500)

    useEffect(() => {
        getFilteredBusiness()
        return () => {
            getFilteredBusiness.cancel()
        }
    }, [licenseKey.key])

    return (
        <div className="flex flex-col gap-4">
            <CEInput
                label="License Key"
                htmlFor="license"
                value={licenseKey.key}
                onChange={e => {
                    setLicenseKey(prev => ({ ...prev, key: e.target.value }))
                }}
                placeholder="License key"
                error={error}
                className={cn(loading ? 'pr-8' : '')}
                suffix={firstRender.current && loading ? <Spinner /> : null}
                disabled={loading}
            />
            {authStore.isAuthenticated && (
                <CEButton size="lg" onClick={onNext} disabled={loading}>
                    Next
                </CEButton>
            )}
        </div>
    )
}

export default LicenseKey
