import SnapPreview from '@/components/content/snap-preview'
import CEInput from '@/components/shared/ce-input'
import CESelect from '@/components/shared/ce-select'
import { Button } from '@/components/ui/button'
import {
    DescriptionInputEnabledForList,
    getSnapSource,
    OutfitOptions,
    OutfitSelectableForList,
    purposeOptions,
    PurposeType
} from '@/lib/constants'
import { LiveSnapType, OUTFIT_TYPE } from '@/lib/types/preset.type'
import { useChatting } from '@/provider/chatting-provider'
import { Trash2 } from 'lucide-react'
import React, { useState } from 'react'
import { cloneDeep } from 'lodash'
import { cn } from '@/lib/utils'
import ActionTooltip from '@/components/shared/action-tooltip'
import ClearableSelect from '@/components/shared/clearable-select'

type propType = {
    snap: LiveSnapType
}

const PreviewSnaps = (props: propType) => {
    const { setPreset } = useChatting()
    const { snap } = props
    const { snapUrl, lightning, purpose, description, id, outfit } = snap

    const [editable, setEditable] = useState(false)
    const [snapPurpose, setSnapPurpose] = useState(purpose)
    const [snapLightType, setSnapLightType] = useState(lightning)
    const [snapOutfit, setSnapOutfit] = useState(outfit)
    const [snapDescription, setSnapDescription] = useState(description)

    const isNotStorySnap = snapPurpose !== PurposeType.STORY
    const outfitSelectable = OutfitSelectableForList.some(pt => pt === snapPurpose)
    // boolean to indicate whether show description input or not
    const descriptionInputEnabled = DescriptionInputEnabledForList.some(pt => pt === snapPurpose)

    const resetUpdate = () => {
        setSnapPurpose(purpose)
        setSnapLightType(lightning)
        setSnapDescription(description)
        setSnapOutfit(outfit)
        setEditable(false)
    }

    const handleDeleteSnapCard = async () => {
        setPreset(prev => {
            const currentPreset = cloneDeep(prev)
            const details = currentPreset.details || {}

            const filterSnapIds = array => (array ? array.filter(i => i !== id) : [])

            details.snaps = details.snaps.filter(i => i.id !== id)

            if (details.opener) {
                details.opener.specificSnapIds = filterSnapIds(details.opener.specificSnapIds)
            }

            if (details.cta) {
                if (details.cta.finalStaticMessage?.snapIds) {
                    details.cta.finalStaticMessage.snapIds = filterSnapIds(
                        details.cta.finalStaticMessage.snapIds
                    )
                }
            }

            return { ...currentPreset, details: details }
        })
    }

    const handleUpdateSnapCard = async () => {
        setPreset(prev => {
            const snaps = cloneDeep(prev.details.snaps ?? [])

            const snapIndex = snaps.findIndex(i => i.id === id)

            const updatedSnap: LiveSnapType = {
                lightning: snapLightType,
                purpose: snapPurpose,
                description: descriptionInputEnabled ? snapDescription : null,
                id: id,
                snapUrl: snapUrl,
                outfit: snapOutfit
            }

            snaps.splice(snapIndex, 1, updatedSnap)

            return {
                ...prev,
                details: { ...(prev.details ?? {}), snaps: snaps }
            }
        })
        setEditable(false)
    }

    return (
        <div
            className={`max-w-[108px] flex flex-col border rounded relative ${!description && [PurposeType.MAIN, PurposeType.SEXY].includes(purpose) ? 'border-red-700' : 'border-slate-800'}`}
        >
            {!editable ? (
                <Button
                    variant="destructive"
                    className="top-0 h-6 w-full rounded-t rounded-b-none"
                    onClick={() => {
                        handleDeleteSnapCard()
                    }}
                >
                    <Trash2 size={16} />
                </Button>
            ) : null}
            <SnapPreview
                src={getSnapSource(snapUrl)}
                className={cn('rounded-none', editable ? 'rounded-t' : '')}
            />

            {!editable ? (
                <ul className="flex gap-0.5 flex-col p-1 pl-5 flex-1 list-disc">
                    <li>{purpose}</li>
                    {isNotStorySnap && (
                        <>
                            {outfitSelectable && outfit ? <li>{outfit}</li> : null}
                            {DescriptionInputEnabledForList.some(pt => pt === purpose) &&
                            description?.trim() ? (
                                <li>
                                    <ActionTooltip label={description}>
                                        <div className="whitespace-nowrap overflow-hidden text-ellipsis">
                                            {description}
                                        </div>
                                    </ActionTooltip>
                                </li>
                            ) : null}
                        </>
                    )}
                </ul>
            ) : (
                <div className="flex gap-1 flex-col p-1 flex-1">
                    <CESelect
                        options={purposeOptions}
                        value={snapPurpose}
                        onValueChange={value => setSnapPurpose(value as PurposeType)}
                        triggerProps={{ className: 'w-[100px]', size: 'sm' }}
                    />
                    {isNotStorySnap ? (
                        <>
                            {outfitSelectable ? (
                                <ClearableSelect
                                    options={OutfitOptions}
                                    value={snapOutfit}
                                    onValueChange={value => setSnapOutfit(value as OUTFIT_TYPE)}
                                    triggerProps={{
                                        className: 'w-[100px]',
                                        size: 'sm'
                                    }}
                                />
                            ) : null}
                            {descriptionInputEnabled ? (
                                <CEInput
                                    value={snapDescription}
                                    onChange={e => {
                                        setSnapDescription(e.target.value)
                                    }}
                                    placeholder="Description"
                                    size="sm"
                                    className={cn(
                                        'w-[100px]',
                                        !snapDescription?.trim()
                                            ? 'border-venetian-red focus-visible:ring-venetian-red'
                                            : ''
                                    )}
                                />
                            ) : null}
                        </>
                    ) : (
                        <></>
                    )}
                </div>
            )}
            {!editable ? (
                <Button
                    className="w-full rounded-t-none h-6  rounded-b"
                    onClick={() => {
                        setEditable(true)
                    }}
                >
                    <span className="text-xs">Edit</span>
                </Button>
            ) : (
                <div className="flex gap-1 flex-col">
                    <Button
                        className="w-full h-6  rounded"
                        onClick={() => {
                            handleUpdateSnapCard()
                        }}
                        disabled={descriptionInputEnabled && !snapDescription?.trim()}
                    >
                        <span className="text-xs">Save</span>
                    </Button>
                    <Button
                        className="w-full rounded-t-none h-6  rounded-b"
                        onClick={() => {
                            resetUpdate()
                        }}
                        variant="destructive"
                    >
                        <span className="text-xs">Cancel</span>
                    </Button>
                </div>
            )}
        </div>
    )
}

export default PreviewSnaps
