import CEButton from '@/components/shared/ce-button'
import { useChatting } from '@/provider/chatting-provider'
import React, { useEffect, useState } from 'react'
import * as API from '@/scripts/api'
import CEInput from '@/components/shared/ce-input'
import { cn } from '@/lib/utils'
import { useToast } from '@/components/ui/use-toast'

const Telegram = () => {
    const { toast } = useToast()
    const { clientInfo, setClientInfo } = useChatting()
    const [telegram, setTelegram] = useState(clientInfo.telegram)

    const [editTelegram, setEditTelegram] = useState(false)
    const [loading, setLoading] = useState(false)

    const handleSubmit = async () => {
        setLoading(true)

        const response = await API.updateClientInfo({ telegram: telegram.trim() })

        if (response.status) {
            setClientInfo(prev => ({
                ...prev,
                telegram: telegram.trim()
            }))
            setEditTelegram(false)
        } else {
            toast({
                description: 'Unable to save telegram handler, it needs to be unique'
            })
        }

        setLoading(false)
    }

    const isInvalid = !telegram.trim()

    return (
        <div className="flex gap-2">
            <div className="flex-1">
                <CEInput
                    label="Telegram Username"
                    placeholder="Telegram"
                    value={telegram}
                    className={cn(
                        'relative',
                        isInvalid ? 'border-venetian-red focus-visible:ring-venetian-red' : ''
                    )}
                    onChange={e => {
                        setTelegram(e.target.value)
                    }}
                    autoComplete="off"
                    disabled={!editTelegram}
                />
            </div>
            <CEButton
                onClick={() => {
                    if (editTelegram) {
                        handleSubmit()
                    } else {
                        setEditTelegram(true)
                    }
                }}
                className="self-end"
                disabled={(isInvalid && editTelegram) || loading}
                submitting={loading}
            >
                {editTelegram ? 'Submit' : 'Edit'}
            </CEButton>
        </div>
    )
}

export default Telegram
