import CEButton from '@/components/shared/ce-button'
import { useChatting } from '@/provider/chatting-provider'
import React, { useState } from 'react'
import * as API from '@/scripts/api'
import CEInput from '@/components/shared/ce-input'
import { cn } from '@/lib/utils'
import { useToast } from '@/components/ui/use-toast'

const Email = () => {
    const { toast } = useToast()
    const { clientInfo, setClientInfo } = useChatting()
    const [email, setEmail] = useState(clientInfo.email)

    const [editEmail, setEditEmail] = useState(false)
    const [loading, setLoading] = useState(false)

    const handleSubmit = async () => {
        setLoading(true)

        const response = await API.updateClientInfo({ email: email.trim() })

        if (response.status) {
            setClientInfo(prev => ({
                ...prev,
                email: email.trim()
            }))
            setEditEmail(false)
        } else {
            toast({
                description: 'Unable to save email, it needs to be unique'
            })
        }

        setLoading(false)
    }

    const isInvalid = !email.trim()

    return (
        <div className="flex gap-2">
            <div className="flex-1">
                <CEInput
                    label="Email"
                    placeholder="Email"
                    value={email}
                    onChange={e => {
                        setEmail(e.target.value)
                    }}
                    className={cn(
                        'relative',
                        isInvalid ? 'border-venetian-red focus-visible:ring-venetian-red' : ''
                    )}
                    autoComplete="off"
                    disabled={!editEmail}
                />
            </div>
            <CEButton
                onClick={() => {
                    if (editEmail) {
                        handleSubmit()
                    } else {
                        setEditEmail(true)
                    }
                }}
                className="self-end"
                disabled={(isInvalid && editEmail) || loading}
                submitting={loading}
            >
                {editEmail ? 'Submit' : 'Edit'}
            </CEButton>
        </div>
    )
}

export default Email
